import{A as t}from"./index-Ctd68eoV.js";const e={adv_g001_shouwu:{id:"adv_g001_shouwu",title:"青溪村来了个守着一件旧物的白发老丈",mother:"M5",channel:"T2",rarity:1,entry:{node:"qingxi",chance:.11},stages:[{xinglu:"是岁青溪村逢白发老丈。白发老丈的话糙，理却直——「东西旧了不怕，怕的是没人认它。」",text:"青溪村角上，白发老丈在给一口枯而不涸的老井掸灰，一下一下，像在给它梳头。白发老丈说守这东西有讲究：「每天来看一眼，缺了补，脏了擦。不为别的——它要是哪天塌了，方圆几十里的人，心里都得空一块。」白发老丈递过来一块抹布：「搭把手？擦一擦你就懂了——懂了的人，往后走到哪儿都见不得东西受委屈。」",options:[{label:"「您守它，图什么？」",goto:1,effect:void 0},{label:"不搭话，绕着走",end:!0,effect:{stat:{wuxing:1},text_after:"「换是要换的，」白发老丈在你背后说，「可换下来旧的，总得有人管。都等着别人管，旧的就都成了垃圾。」你没回头，可这句话跟了你一路。"}}]},{xinglu:"是岁青溪村一课。白发老丈把话说到根上——「守到后来，分不清是我守它，还是它守我。」",text:"白发老丈坐下来，给你讲了件旧事——讲完自己半天没言语。「我算过账。」白发老丈扳着指头，「守它这些年，花的钱、挨的骂、误的工——全是赔的。可谁家孩子路过这儿喊一声『这东西还在啊』——这一声，全赚回来了。」白发老丈站起身，最后擦了一遍一口枯而不涸的老井：「天不早了。守物人的话就这么多——你要记，就记一句：物在人守。人要是都不守了，物就真没了。」",options:[{label:"「您守的哪里是物。」",end:!0,effect:{stat:{wuxing:1},trait:{dan:1},ledger:{type:"义",text:"帮白发老丈修缮一口枯而不涸的老井，青溪村的旧物得以长存"},text_after:"你陪白发老丈坐到日头偏西。临走他说：「今天这一坐，比擦十年灰有用。」你问为什么。他说：「东西怕的不是旧，是没人坐。有人肯坐，它就还是个去处。」"}},{label:"「您自己守着就好。」",end:!0,effect:{stat:{wuxing:1},text_after:"「记性不好的人，」白发老丈笑了，「就看一眼。眼睛比脑子诚实——看过的东西，忘不掉的。」你回头看了一口枯而不涸的老井一眼。就这一眼，你知道他说得对。"}}]}]},adv_g002_chuanyi:{id:"adv_g002_chuanyi",title:"老汉在山神庙把手艺往下传",mother:"M3",channel:"T3",rarity:2,entry:{node:"poza",chance:.07},stages:[{xinglu:"是岁山神庙逢老汉。老汉的话糙，理却直——「手艺人的坟头不用碑——他的手艺活在别人手上，就是碑。」",text:"你到山神庙时，老汉正在用一册手抄的方子簿干活，几个学徒围着看，大气不敢出。「我教徒弟，头一年不让碰一册手抄的方子簿。」老汉笑，「先看、先磨性子。心浮的人拿家伙什，糟蹋东西，也糟蹋自己。」「你要是感兴趣，我讲细点。」老汉说，「讲了你就懂——懂了的人，走到哪儿都替这门手艺说句话。」",options:[{label:"「徒弟难收吧？」",goto:1,effect:void 0},{label:"「手艺而已，不值一提。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不值一提？」老汉也不争辩，只把刚做好的活递给你看——那一处细节，你盯了半天才看出来门道。「你再看一遍，」他说，「不值一提的东西，为什么你一提就提不出来？」你臊了，他哈哈大笑：「逗你的。手艺不值一提，提的是心——你有心，就能看见。」"}}]},{xinglu:"是岁山神庙一课。老汉把话说到根上——「手艺不认血缘，只认肯下苦功的人。」",text:"「我这一册手抄的方子簿差点断在一桩事上。」老汉摩挲着它，「你听听——听完你就明白手艺人为什么较真。」「教不会的那部分，是火候。」老汉说，「差半分，药性不对、木头开裂、线走歪——这半分我说了三十年，徒弟们还是得自己烧坏三锅料才能懂。所以我改了法子：先让他们烧坏——心疼了，耳朵就开了。」老汉送你到门口：「来，我这有句话送出门的客人——艺是拿来敬的，不是拿来用的。敬它，它养你一辈子。」",options:[{label:"「您的手艺，不会断。」",end:!0,effect:{stat:{wuxing:1},trait:{yi:1},ledger:{type:"义",text:"帮老汉校对手抄册子，替一门手艺把住传承"},text_after:"你上了手，做得歪歪扭扭。老汉在旁边看着，不催不笑，等你做完才说：「歪归歪，下手不虚——你是块料，就是没人给你上过头一课。」你问什么头一课。他说：「敢在自己人面前做坏。多少有天分的人，就毁在不敢露怯上。」这句话你记了很多年。"}},{label:"「与我何干，告辞。」",end:!0,effect:{stat:{wuxing:1},text_after:"「要钱？」老汉愣了一下，随即大笑，「我今天一个字没收你钱，还搭了一下午的茶——你要是听成了要钱，那我这一下午白讲了，你的耳朵也白带了。走吧走吧——」他摆摆手，笑骂道，「亏你今天还看了我半天活。看活不看人，你差得远呢。」"}}]}]},adv_g003_haiyuan:{id:"adv_g003_haiyuan",title:"后山道里替故人还愿的婆婆",mother:"M4",channel:"T1",rarity:3,entry:{node:"shanlu",chance:.07},stages:[{xinglu:"是岁后山道逢婆婆。婆婆的话糙，理却直——「还愿不是还东西，是把人没说完的话说完。」",text:"后山道里，婆婆捧着一把没磨完的刀出神——你一问，他说这是故人留下的。「这愿许了三年了。」婆婆摩挲着一把没磨完的刀，「走一段，问一段。有人笑我：人都没了，还折腾什么？我说——就是人都没了，才要折腾。活着的人可以等你，走了的人，等不了。」婆婆看着你：「你说，人走了以后，到底知不知道我们还在替他办事？」不等答，他自己接了：「知不知道都要办——这是我的事，不是他的事。」",options:[{label:"「您这愿，尽到心了。」",goto:1,effect:void 0},{label:"「人都没了，何必呢。」",end:!0,effect:{stat:{wuxing:1},text_after:"「留着何用？」婆婆把一把没磨完的刀举起来给你看，「你看它像东西吗？不像了——它是一句没说完的话。话没了，人才真的没了。」他说完自己收好，朝你拱拱手，「客人，话糙了。可这理，你早晚用得上。」"}}]},{xinglu:"是岁后山道一课。婆婆把话说到根上——「替人还愿这行，赚的不是钱——是夜里睡得着。」",text:"「说起这个愿的来历，」婆婆坐下身来，「得从头讲。」「为我老婆子还的愿，办起来最不觉得累。」婆婆摩挲着一把没磨完的刀，「有人说我傻，人都没了。我说你没懂——她还哪儿都没去。她在这个愿里。我每走一里路，她就跟我走一里。等愿还完，她也就到家了。」婆婆说这话时眼里有泪，脸上却在笑。婆婆重新收拾好行囊：「客人的话我记下了。愿还得接着赶路——它等不起，我也不能老。」他冲你拱手，「你若哪天也遇上该还的愿——别拖。拖，是还愿这行唯一的死敌。」",options:[{label:"「我记住了。」",end:!0,effect:{stat:{wuxing:2},trait:{tong:1},ledger:{type:"恩",text:"受婆婆所托记下善缘，替走了的人结一个活缘"},text_after:"「尽到心没尽到心，我自己知道。」婆婆摇头，「可你说这话，我路上就不孤单了。还愿人最怕的不是路——是没人说一句『够了，可以了』。你说了一句。我记下了。」"}},{label:"「愿是虚的，人死了就完了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「完了就完了？」婆婆站定，认真看你，「人走茶凉是世道。可我把茶端热的这些年，凉不了——你信不信？你今天说这话，是因为还没遇着走的人。遇着了，你会想起我。」他走了，那句话你揣了一路，越揣越沉。"}}]}]},adv_g004_zengxing:{id:"adv_g004_zengxing",title:"山壁石洞的一课：少年白送路上的东西",mother:"M1",channel:"T2",rarity:2,entry:{node:"shanbi_dong",chance:.07},stages:[{xinglu:"是岁山壁石洞逢少年。少年的话糙，理却直——「我不图报——我只求受的人往后也肯搭把手。」",text:"你打山壁石洞过，少年招呼你：「歇歇脚？不要钱，也别推——推就见外了。」「有人问我图什么。」少年摆摆手，「图什么？我夜里从这儿过，看见路人的灯笼从我摆的东西旁边过去——那一刻我就图了。人活着，总得有点自己知道就行的事。」「帮我记个账呗。」少年递过来一个小本子，「不是记谁拿了什么——是记今天又有几个人用了它。这账好看，你写一笔。」",options:[{label:"「『自取』好。」",goto:1,effect:void 0},{label:"「天下哪有白给的好事。」",end:!0,effect:{stat:{wuxing:1},text_after:"「收买人心？」少年愣了一下，随即苦笑，「我要能收买人心，先把我自己这颗买服帖——它总嫌我瞎折腾。」他把东西收回，也不恼，「客人防着点也好。可你记住：天下收买人心的，都要你报答；我什么都不要——你要是连不要报答的都不敢信，这世道可就真没救了。」他这话说得平静，你却走得脸热。"}}]},{xinglu:"是岁山壁石洞一课。少年把话说到根上——「路上的东西谁都需要，路上的心谁都不肯先给——我先给。」",text:"「我最得意的不是这一盏风雨夜的引路灯。」少年朝远处一指，「是那边——你看见没有？」「碑不立。」少年说得干脆，「一立碑，这就成了我的善举。可这一盏风雨夜的引路灯一年喂饱几百人——是几百个取的人成全了这件事，不是成全我。碑上该刻他们——可他们连名字都不肯留。所以他们不留，我也不留。这事干干净净，比碑好看。」「记住这条道的规矩。」少年指指一盏风雨夜的引路灯，「用的时候想着点别人，够用的就别多拿——这不是我的规矩，是路自己的规矩。守住了，这东西就一直有。」",options:[{label:"「您这样的人，多几个才好。」",end:!0,effect:{stat:{wuxing:2},trait:{dan:1},ledger:{type:"义",text:"在山壁石洞白得一份干粮，后来也学着挂了一壶茶"},text_after:"你记住了那条规矩。后来你真在道上遇着同样的摊子，取的时候留了双份的钱压在木牌下。摊主追出来还钱，你说：「前头山壁石洞有位老丈教的——够用就行，多留是给后头的。」摊主愣了愣，朝你作了个揖。那一刻你忽然明白：少年的账本，原来一直记到你身上。"}},{label:"「世道就这样，你改变不了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「哄你？」少年笑了，「我哄你做什么？我又不要你的钱、不要你的命。我哄你，你就信了天下还有点好事——这买卖我亏了还是赚了？」他把东西又塞回你怀里，「拿着。信不信由你——东西是真的，渴了是真的，就这么简单。」"}}]}]},adv_g005_shouye:{id:"adv_g005_shouye",title:"在官道，夜里替人醒着的老妇",mother:"M2",channel:"T3",rarity:2,entry:{node:"guandao",chance:.06},stages:[{xinglu:"是岁官道逢老妇。老妇的话糙，理却直——「守夜这行，眼睛不能好使——太好使了，看见的事多，心里搁不下。」",text:"老妇守在一窑点火的老窑旁，火光把他的影子拉得很长，见你近前，先问了句：「夜里赶路，有事？」「夜里赶路的，十个里有三个心里揣着事。」老妇给你照着亮，「我不问你什么事——我就把你送到亮处。人到了亮处，事就小了一半。」「夜里的事，你遇上过么？」老妇问你，「遇上过就知道我这盏灯的用处了。」",options:[{label:"「夜里的事，讲讲。」",goto:1,effect:void 0},{label:"「半夜不睡，有病吧。」",end:!0,effect:{stat:{wuxing:1},text_after:"「出息？」老妇笑了，「我这行没出息——没出息到二十年没人抢。可你想想，谁夜里敢不睡？不是我不想睡，是官道几百户人拿觉换了我的不睡。」他敲了敲一窑点火的老窑，「出息这东西，白天论的。夜里的账，另算。」你将信将疑地走了。后来你在异乡的夜里病倒，是个守夜的老人照看了你——那一刻你想起这句话，眼睛忽然就热了。"}}]},{xinglu:"是岁官道一课。老妇把话说到根上——「夜里的事，白天看不见——看不见不等于没有。」",text:"「你以为守夜就是防贼？」老妇摇头，「夜里的事，十件有九件不是贼。」「那回真险，是山洪。」老妇说，「后半夜我听见上游水声不对——平年这时候是涓涓的，那晚是闷雷似的。我挨家砸门，砸了四十七扇。水进村的时候，人都站到坡上了。第二天清点，一只鸡都没少。后来官府来查，问谁先发现的——我说没人发现，水自己来的。他们信了。我为什么不说？说了，下回还得我去砸门——我乐意砸，可功劳这东西，一人占了，别人就不干了。」「我这班，还守得动十年。」老妇活动着腿脚，「十年后谁接？我挑着呢。你若哪天走投无路——来找我。守夜人缺人手，也缺心里有夜的人。」",options:[{label:"「保我十年太平。」",end:!0,effect:{stat:{wuxing:1},trait:{xin:1},ledger:{type:"恩",text:"受老妇一盏灯的照拂，往黑路上心里有了底"},text_after:"「心里有夜的人。」你把这句话带了很多年。后来你做了点小营生，雇伙计先看人睡觉——都笑你怪。你想起老妇，也不解释。守夜人的道理，本来就是说给夜里的人听的。"}},{label:"「守夜能守出什么名堂。」",end:!0,effect:{stat:{wuxing:1},text_after:"「运气？」老妇指指自己的眼睛，「我这双眼二十年没睡过一个整觉——官道每一块松动的石头、每一个白天咽下事的夜行人、每一处该修没人修的堤口，都在我这儿记着。运气是留给没准备的。你说是运气就运气——反正鸡叫的时候，人人都囫囵着，这就够了。」"}}]}]},adv_g006_shiyi:{id:"adv_g006_shiyi",title:"妇人在宫门当值区替失物寻主人",mother:"M6",channel:"T1",rarity:1,entry:{node:"gongmen",chance:.06},stages:[{xinglu:"是岁宫门当值区逢妇人。妇人的话糙，理却直——「遗落的东西不会说话——可它们都在等人。」",text:"宫门当值区的角落里有一间小屋，妇人守着一叠无主的田契——那是他的全部营生，也是他的全部心事。「我这册子记了二十年。」妇人翻着一叠无主的田契边的旧簿，「每件失物什么样子、哪儿捡的、像是谁丢的——都记着。册子比我的脑子靠得住。人的记忆会骗人，字不会。」妇人递给你一件失物：「你摸摸。摸完了你说说，它的主人是个什么样的人？」",options:[{label:"「这故事有意思，讲讲。」",goto:1,effect:void 0},{label:"「一堆破烂，守着做什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"「没出息。」妇人笑了，「对——没出息，饿不死，也发不了。可你告诉我，什么行当能让人二十年睡得着觉？我这行能。我每送回一件东西，就有一户人家少一夜的睡不着。」他拱拱手，「出息是活给别人看的，觉是自己睡的。慢走。」"}}]},{xinglu:"是岁宫门当值区一课。妇人把话说到根上——「世上的失物比失物的人多——总得有人替它们排队等主人。」",text:"「我师父是官府的库吏出身。」妇人说，「他传我这行当，传的却不是收东西的法子。」「被忘了才是真的没了。」妇人说，「所以我这册子上的东西，一件都不许销。人忘了，我替他记着；他哪天想起来——哪怕想起来的是十年前的一件小事——东西还在，日子就还接得上。我这行当说到底，就是给人留个『接得上』。」「天不早了。」妇人点起灯，「我这儿夜里也开门——丢东西的人，是不分时辰的。你慢走，路上小心别落了东西。落了也不要紧——这世上还有我这样的人。」",options:[{label:"「愿您满屋的东西早归主。」",end:!0,effect:{stat:{wuxing:1},trait:{dan:1},ledger:{type:"恩",text:"听妇人讲半只风筝的旧事，识得失物的轻重"},text_after:"「找主人要紧。」妇人点头，「可你方才那个问法好——问的是主人放下了没有。这些年我只顾找，忘了问这个。有的失物，主人早放下了，是我攥着不放。」他笑了，「所以你看，问路的功劳不在答——在问。你今天这一问，我这行当又多了一条规矩。」"}},{label:"「你这是痴人行当。」",end:!0,effect:{stat:{wuxing:1},text_after:"「拾不过来。」妇人坦白得很，「天下的失物，我一辈子拾不完。可我多拾一件，世上就少一件没着落的。你这话跟师父当年说的一模一样——他后来呢？他拾了一辈子。」他拿起册子，「拾不过来，就一件一件来。日子长着呢。」"}}]}]},adv_g007_wenlu:{id:"adv_g007_wenlu",title:"在天机阁，只问不答的老汉",mother:"M7",channel:"T2",rarity:1,entry:{node:"tianjige",chance:.09},stages:[{xinglu:"是岁天机阁逢老汉。老汉的话糙，理却直——「答是别人的，问才是自己的——会问的人，走哪儿都带着老师。」",text:"你路过天机阁，老汉拦住你：「客人，问你个事——你答不上来不要紧。」「你说人为什么要问路？」老汉自问自答，「因为路认生。认生的东西，你不问它，它就骗你——这是路教的，我只是转述。」「客人走南闯北，见得多。」老汉凑近了些，「帮我评评，这个问题，问得蠢不蠢？」",options:[{label:"「我想清楚再答。」",goto:1,effect:void 0},{label:"「问那么多做什么，干活要紧。」",end:!0,effect:{stat:{wuxing:1},text_after:"「怪人就怪人。」老汉笑呵呵的，「天机阁人人都这么叫。可你也看见了——他们路过还是要看一眼我那牌子。为什么？怪话里头，偶尔藏着正经。人不能全信怪人，可也不能一个怪人都不信——全信了傻，全不信了苦。你自己掂量。」他冲你摆摆手，继续挂他的问题。"}}]},{xinglu:"是岁天机阁一课。老汉把话说到根上——「人有答案还问，是心里不踏实；没答案就问，是心里明白。」",text:"「有人骂我，说问了半天屁用没有。」老汉居然点头，「他骂得对。你听听怎么回事。」「三十年挂着的那个问题是：人这一生，是答案重要，还是问得对重要？」老汉缓缓道，「年轻时我赌答案是重要的——答对了就赢了。后来发现，答对的都有过期的一天。如今我改赌了：问得对重要。问对了，答错了能重来；问错了，答对了也是白答。」老汉笑了笑，「你呢？你怎么赌？不用现在答——这个问题，现在也归你了。」老汉把一张纸条郑重推给你：「这个问题归你了。不急——哪天想通了，丢进我这竹筒里就行，人不用来。问题认字不认人。」",options:[{label:"「看，还是觉得——我记下了。」",end:!0,effect:{stat:{wuxing:1},trait:{yi:1},ledger:{type:"义",text:"受老汉所托带走一个三十年的问题"},text_after:"「先生就是你自己的心。」你出门时回头看了一眼——老汉已经转回一只装满纸条的竹筒前，又在写新问题了。你忽然明白这老头为什么从不给答案：答案是他给不起的——人人的路不一样。他给的是火折子，路得你自己摸黑走。可有了火折子，摸黑也走得直。"}},{label:"「答案拿来，问题免了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「答案？」老汉把牌子转过来给你看——「只问不答」四个字钉得结结实实。「我这不给答案，跟药铺不卖病一个理：病在你身上，药方在你身上，我这儿只管帮你把脉。」他把门推开，「你要答案，满街都是——街边随便拉个人都能给你一个。可你要问句，就得自己来。你不来，是你的损失。」"}}]}]},adv_g008_jizhang:{id:"adv_g008_jizhang",title:"内市的一课：老人替人情记着账",mother:"M8",channel:"T3",rarity:1,entry:{node:"neishi",chance:.12},stages:[{xinglu:"是岁内市逢老人。老人的话糙，理却直——「账要当众记、背后清——记账人自己先不能藏私。」",text:"老人的一串打了结记事的旧麻绳在内市人人都信——你说不清它记了多少年，只知道比庙里的功德碑还灵。「我这柜里也有死账。」老人翻开一册，「欠账的人没了，绝了户。这账我不销——我把它抄出来，年年清明在庙前念一遍。不为讨——为的是告诉街坊：这个人来过，欠过，也被人欠过。没了户，不能连名都没了。」老人打量你一番：「客人面生——有没有旧账落在我这儿？有的话，报个名姓，我一翻便知。」",options:[{label:"「先记欠的。」",goto:1,effect:void 0},{label:"「人情账，记它做什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"「闲事？」老人笑了，「张家的牛吃了李家的苗，是闲事；王家的娃读了书没人束脩，是闲事；你小时候发高热，邻家婶子背你走过三条街——也是闲事。这世上的情分，全是『闲事』堆出来的。我记的就是这些——你说的正事，反倒用不着我记。」"}}]},{xinglu:"是岁内市一课。老人把话说到根上——「我记的不是债——是这世上「有人还过」的证据。」",text:"「记账人也有难处。」老人说，「最难的一回，差一点把这柜账烧了。」「断二十年的死结，靠的不是我。」老人说，「是账。两家为了一头牲口的账翻了脸，各说各的理，说到后来连当初谁欠谁都吵不清了。我翻出二十年前的老册子——记着呢：两家当年合伙买牛，牛钱各半，牛死了一家多用了两年。白纸黑字，两家老人都画了押。」老人把册子往桌上一放，「两家人看着自己爹娘的押，当场就哭了。第二天合伙把坟头的草都拔了。你说账是什么？账是死人替活人留的话——我不过是替死人开口。」老人合上账本：「客人，账理就一句话——欠的记着，还的记着，两头都不忘，人情就断不了。你带走这一句，我这柜子就没白守。」",options:[{label:"「把我记上。」",end:!0,effect:{stat:{wuxing:2},trait:{xin:1},ledger:{type:"恩",text:"在老人账上被记了一笔：「今天有个客人，听完了整本账」"},text_after:"「当得起什么。」老人连连摆手，「我这行，说到底是替人管着念想。念想是他们的，我只是个保管员。」可你看得出来，他说这话时腰板挺得笔直——一个一辈子被几千户人信着的人，那份挺直，是拿三十年的笔一笔一笔撑起来的。"}},{label:"「人情最靠不住，你记了也白记。」",end:!0,effect:{stat:{wuxing:1},text_after:"「白记？」老人居然点头，「你说得对——十笔情账，有三笔是白记的。可剩下七笔呢？」他翻开册子给我看密密麻麻的还账记录，「人情是靠不住——可总得有人头一个信。我信了三十年，换回这七本册子的『还』字。你赌人不靠得住，你赌输了也就输了；我赌人靠得住，我赢得一街的太平。这笔账，你自己算。」"}}]}]},adv_g009_shouwu:{id:"adv_g009_shouwu",title:"四牌楼大街的一课：少年守着一件旧物",mother:"M5",channel:"T1",rarity:1,entry:{node:"chengmen_dashi",chance:.11},stages:[{xinglu:"是岁四牌楼大街逢少年。少年的话糙，理却直——「守物人死了不怕——怕的是物先觉得没人要它。」",text:"你到四牌楼大街时，少年正围着一盏长明灯忙活，动作轻得怕惊着它。「它不是我的，是大家的。」少年摆摆手，「我就是替大家看着。你今天看它一眼，你也算半个守的。」少年从怀里摸出个小本子：「守物的账。你帮我记一笔——今天有人来看过它。这一笔，比我给你什么都强。」",options:[{label:"坐下陪少年说说话",goto:1,effect:void 0},{label:"「我有正事，赶路要紧。」",end:!0,effect:{stat:{wuxing:1},text_after:"你绕着走了。走出去老远，风里飘来一句话似的调子——少年在给一盏长明灯哼曲儿。你忽然明白：人家守得高兴，根本不在乎你看不看。这么一想，你的脚步倒轻快了。"}}]},{xinglu:"是岁四牌楼大街一课。少年把话说到根上——「东西没了可以再造，守的规矩断了就接不上。」",text:"少年收了抹布，话头一转：「守它这些年，也不是没动摇过。」「师父留的那句话，我琢磨了二十年。」少年说，「他写的是：守到你觉得是它在守你，才算入门。我当时不懂——现在懂了。它站在这儿，我就不敢倒下。」少年站起身，最后擦了一遍一盏长明灯：「天不早了。守物人的话就这么多——你要记，就记一句：物在人守。人要是都不守了，物就真没了。」",options:[{label:"「这话我记一辈子。」",end:!0,effect:{stat:{wuxing:1},trait:{dan:1},ledger:{type:"恩",text:"帮少年修缮一盏长明灯，四牌楼大街的旧物得以长存"},text_after:"你帮着擦完了。手上的灰蹭了一袖子，心里却出奇地熨帖。少年看着擦亮的一盏长明灯，半天说了句：「行了，今天这一遍，值。」你走出很远才咂摸出味儿来——他谢的不是你，是它今天又被人认真对待了一回。"}},{label:"「您自己守着就好。」",end:!0,effect:{stat:{wuxing:1},text_after:"少年也不勉强：「记不记随你。这话搁在这儿，你哪天想起来了，就算我托到了。」你告辞出来，走出一段，那句话还是跟上了你——物在人守。你说不上来哪里被它戳中了。"}}]}]},adv_g010_chuanyi:{id:"adv_g010_chuanyi",title:"驼背阿婆在东市把手艺往下传",mother:"M3",channel:"T2",rarity:2,entry:{node:"dongshi",chance:.07},stages:[{xinglu:"是岁东市逢驼背阿婆。驼背阿婆的话糙，理却直——「徒弟学不学得会看天分，教不教得会看良心。」",text:"驼背阿婆见了你，先把手上的活做完才抬头：「客人别笑话，手艺人的规矩，做不完的活不抬头。」「我收徒不收钱。」驼背阿婆摆摆手，「收钱的手艺传不远——徒弟心里算账，手上就留不住分寸。我挑徒弟只看一样：肯不肯下笨功夫。」驼背阿婆让徒弟先歇了，转过身来：「客人识字吧？帮我看看这册子上的字有没有错的——手艺传得走样，多半是从错字开始的。」",options:[{label:"「徒弟难收吧？」",goto:1,effect:void 0},{label:"「这些老规矩，过时了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不值一提？」驼背阿婆也不争辩，只把刚做好的活递给你看——那一处细节，你盯了半天才看出来门道。「你再看一遍，」他说，「不值一提的东西，为什么你一提就提不出来？」你臊了，他哈哈大笑：「逗你的。手艺不值一提，提的是心——你有心，就能看见。」"}}]},{xinglu:"是岁东市一课。驼背阿婆把话说到根上——「手上的功夫十年教得会，手上的分寸三十年说不清。」",text:"「我这辈子收过九个徒弟。」驼背阿婆伸出手比划，「成器的三个，将就的三个，走了样的三个——你猜哪个我记最牢？」「九个徒弟里走得最远的那个，如今把手艺传到了三个省。」驼背阿婆满脸得意，「他当年被我骂出门的。走的时候撂话：此生不回来。前年他回来，进门就给我端了盆洗脚水——说师父，我懂了。我问懂什么了。他说：您当年骂我的每一句，如今我都原样骂给我的徒弟。」驼背阿婆送你到门口：「来，我这有句话送出门的客人——艺是拿来敬的，不是拿来用的。敬它，它养你一辈子。」",options:[{label:"「谢先生一课。」",end:!0,effect:{stat:{wuxing:1},trait:{tong:1},ledger:{type:"恩",text:"帮驼背阿婆校对手抄册子，替一门手艺把住传承"},text_after:"「能传多久？」驼背阿婆想了想，「看天。可我告诉你我的算法：只要还有人肯为一个细节较真——这门手艺就活着。你今天盯着我这活看了半晌，就在较真。所以今天，它又多活了一天。」"}},{label:"「手艺早晚要绝。」",end:!0,effect:{stat:{wuxing:1},text_after:"「道理是会讲。」驼背阿婆不恼，「可我讲了三十年，徒弟们信了——你嘴上不信，眼睛信了。你进来到现在，眼睛没离开过它三回。」你哑口无言。他笑着送你出门：「不信没关系，手艺等得起。它等你一辈子，我都等得起。」"}}]}]},adv_g011_haiyuan:{id:"adv_g011_haiyuan",title:"路遇独臂客——在漕运码头替故人还愿",mother:"M4",channel:"T3",rarity:3,entry:{node:"matou",chance:.08},stages:[{xinglu:"是岁漕运码头逢独臂客。独臂客的话糙，理却直——「人走了，愿不能跟着走——愿得有人替他走完。」",text:"独臂客在漕运码头等人，等了一个没有地址的人——他要送的是半坛没喝完的酒。「我跟他打了一辈子交道，就欠这一件。」独臂客把半坛没喝完的酒翻过来给你看，「你看这磨痕——都是他亲手磨的。他磨的时候念的什么，我大概知道。所以这愿，我认。」独臂客忽然问你：「客人识路广——你听过半坛没喝完的酒的去处么？随便一点线索，我都谢。」",options:[{label:"「帮您辨认这页纸。」",goto:1,effect:void 0},{label:"「路远事烦，别找了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「与我无关？」独臂客也不恼，「是啊，天下事都与谁无关呢？他跟我无关的时候，我欠了他一辈子。你走吧——愿你一辈子都用不上替人还愿。用不上，是福气。」"}}]},{xinglu:"是岁漕运码头一课。独臂客把话说到根上——「故人最大的悲哀不是死——是心愿烂在没人知道的地方。」",text:"独臂客沉默了一阵，说：「其实这个愿，我本可以早点还的。」「蹊跷事是这样的：那年到地方，收信的人家早搬了。」独臂客说，「我打听三个月，问遍十里八乡——就在我要走的前一天，一个后生找上门：我是他孙子，爷爷临终说，会有人送东西来。」独臂客摊开手，「你说，愿认路，还是我认路？我不知道。我只知道，愿不能停在半道。」独臂客重新收拾好行囊：「客人的话我记下了。愿还得接着赶路——它等不起，我也不能老。」他冲你拱手，「你若哪天也遇上该还的愿——别拖。拖，是还愿这行唯一的死敌。」",options:[{label:"「您到家了，替他放心。」",end:!0,effect:{stat:{wuxing:2},trait:{ren:1},ledger:{type:"恩",text:"捎独臂客一程，听了一个还愿人的故事"},text_after:"你把记得的线索全说了——竟真有一条有用。独臂客愣在原地，半晌，深深作了个揖：「客人，你今天替一个走了两年的人，把愿往前推了三里地。」他非要留给你一样谢礼，你说不必，他坚持：「愿上的账，不能欠。你收下——不然我这一路，就白背了心债。」"}},{label:"「愿是虚的，人死了就完了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「累？」独臂客笑了，「我讲的累，是别人的命换来的道理。你嫌累，道理不怪你——可道理也不会再来找你。走吧。」你走出去半里，忽然想折回来问问他那花田的事——终究没折。那半里路，你走得比来时快，也比来时轻浮。"}}]}]},adv_g012_zengxing:{id:"adv_g012_zengxing",title:"老人在武行镖局街白送路上的东西",mother:"M1",channel:"T1",rarity:1,entry:{node:"wuhangjie",chance:.13},stages:[{xinglu:"是岁武行镖局街逢老人。老人的话糙，理却直——「路边这点东西救不了命——可有时人就差这一口。」",text:"武行镖局街的路边，老人摆着一捆留给夜路人的干柴，来者不问，取者不问。「你仔细看我的木牌。」老人指给你，「写的是『自取』，不是『施与』。一字之差——拿的人心里就平了。善这个东西，得把人的脸面一起护住才算善。」老人忽然问你：「你往后还走这条路么？」不等答，他自己笑了：「走不走都一样。东西在这儿，路就在这儿。」",options:[{label:"「『自取』好。」",goto:1,effect:void 0},{label:"「少来这套收买人心。」",end:!0,effect:{stat:{wuxing:1},text_after:"「白给的好事？」老人哈哈大笑，「你算算这笔账：我一年搭进去几贯钱，换来这条道上的人夜里敢走、白天敢歇——你说值几贯？好事从来都白给，只是给的人不说。」你把他的话琢磨了一路，到家门口才咂摸出味儿来。"}}]},{xinglu:"是岁武行镖局街一课。老人把话说到根上——「赠人一程，自己脚下的路也宽了一寸。」",text:"「有一年冬天，来了个贼。」老人说起这事，倒像说旁人。「起头真是给自己备的。」老人坦白道，「那年我落魄，怕自己哪天走投无路，就先备着——备着备着，先被人用了。用的人跟我说谢，我脸上臊——原来我备下的东西，早有人比我更需要。从那天起，这就不是我的退路了，是路上的公物。」老人给你包了一份路上用的：「拿着。我别的不送——就送个『路上有人惦记』的踏实。你揣着它走夜路，脚底下稳当。」",options:[{label:"「东西我收了，情我记了。」",end:!0,effect:{stat:{wuxing:2},trait:{zhi:1},ledger:{type:"恩",text:"受老人所托，允诺传递路边的规矩"},text_after:"「路上的人认路上的人。」你把这话嚼了一路。后来你在他乡的渡口，看见一个陌生人冒着雨给等船的人撑伞——没人认识谁，可人人都往伞下凑。你站在雨里看着，忽然懂了：那条道上的规矩，早就走出武行镖局街了。"}},{label:"「我不信这些。」",end:!0,effect:{stat:{wuxing:1},text_after:"「改变不了。」老人居然点头，「我一天也就喂饱几十个人，天下人多着呢。可你倒过来算——要是人人都觉得改不了，那就真改不了了。我摆一天，就有一天不是那样。这道理笨，可它管用。」你出门时他还坐着，晨光落在他身上，那一捆留给夜路人的干柴像一方小小的印，盖在漫长的路上。"}}]}]},adv_g013_shouye:{id:"adv_g013_shouye",title:"四牌楼贫民坊里夜里替人醒着的婆婆",mother:"M2",channel:"T2",rarity:2,entry:{node:"sipailou",chance:.07},stages:[{xinglu:"是岁四牌楼贫民坊逢婆婆。婆婆的话糙，理却直——「守夜这行，眼睛不能好使——太好使了，看见的事多，心里搁不下。」",text:"夜里你到四牌楼贫民坊，婆婆提着一棚待产的牲口巡到跟前，先给你照了个亮。「夜里我谁也不查。」婆婆说，「我就是走。走给睡的人听——听见脚步，贼不敢动，病人心安，失眠的知道天总会亮。我这一双脚，是四牌楼贫民坊的定心丸。」「夜深了。」婆婆看看天，「你歇你的。我照旧巡我的——鸡叫之前，你听不见一点动静。这是我的保票。」",options:[{label:"「劳驾送一程。」",goto:1,effect:void 0},{label:"「半夜不睡，有病吧。」",end:!0,effect:{stat:{wuxing:1},text_after:"「有病？」婆婆也不恼，「我这病生了二十年，治好了几百户人的安稳觉。你说谁有病？」他把灯一提，「前头黑，跟紧——有病的人给你照路。」你跟着他走过那段黑路，一路无话。到了亮处他站住：「去吧。有病的人不送了。」你走出老远，回头看那点灯火还立在原地——你忽然觉得，有病的人，比没病的都清醒。"}}]},{xinglu:"是岁四牌楼贫民坊一课。婆婆把话说到根上——「守一夜容易，守一年也不难——难的是守着守着，把别人的夜当成自己的夜。」",text:"「你以为守夜就是防贼？」婆婆摇头，「夜里的事，十件有九件不是贼。」「师父那句话是：守夜守的不是夜，是人心里那点亮。」婆婆摩挲着一棚待产的牲口，「我用了二十年才懂——灯灭了可以再点，人心里的灯灭了，夜里就真黑了。所以我巡夜从不偷懒：我的脚步声，就是几百户人心里那盏灯的灯芯响。」「你走吧，天亮了路好走。」婆婆收了灯，「夜里的事你记着一半就行——另一半，是留给夜里的人的。」",options:[{label:"「这话我懂了。」",end:!0,effect:{stat:{wuxing:1},trait:{ren:1},ledger:{type:"义",text:"受婆婆一盏灯的照拂，往黑路上心里有了底"},text_after:"你带走了那一半话。夜里赶路时你学着婆婆的样子，给后来的人照个亮。有回一个后生问你是谁，你说：「一个守夜的教我的——夜里的另一半，留给夜里的人。」后生似懂非懂。可他往后也给人照亮了——婆婆的灯，就这么传到了你手上。"}},{label:"「你这灯，照不了多远。」",end:!0,effect:{stat:{wuxing:1},text_after:"「名堂？」婆婆把灯举起来，「你看这灯照多远——三步。可走夜路的人，缺的就是这三步。」他放下灯，「名堂是白天的事。我夜里不图名堂——图的是四牌楼贫民坊的狗都不叫唤。狗都不叫，就是真太平。你要图名堂，白天去图；你要图太平，咱们才是一路的。」"}}]}]},adv_g014_shiyi:{id:"adv_g014_shiyi",title:"在报国寺，替失物寻主人的老妇",mother:"M6",channel:"T3",rarity:3,entry:{node:"bgs_shanmen",chance:.08},stages:[{xinglu:"是岁报国寺逢老妇。老妇的话糙，理却直——「丢东西的人分两种：丢得起的一笑了之，丢不起的——那种你得跑断腿。」",text:"老妇在报国寺整理一箱无人认领的旧信，一件一件编号，比账房先生还仔细。「有人笑我守着一堆破烂。」老妇不恼，「我说你不懂——破烂搁在你家是破烂，搁在我这儿，是有主的。只等它的主人哪天想起来。人这一辈子，谁没落下过点什么？」「你眼神好。」老妇招手，「帮我认认——这个包袱上的字，是哪府的写法？」",options:[{label:"「我没见过，帮不上。」",goto:1,effect:void 0},{label:"「失物还想着领？痴人。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不会找？」老妇叹口气，「客人，会找的人，丢的都是值钱东西。不会找的——老人丢了，孩子丢了，痴了的人丢了。他们自己找不了，家里人找疯了。我这行拾的，一半是物，一半是人。」他说完不再看你。你走出去几步，觉得方才那句话，轻佻得不像自己的。"}}]},{xinglu:"是岁报国寺一课。老妇把话说到根上——「东西无主的时候最可怜——可怜它们连个喊它名字的人都没有。」",text:"「我师父是官府的库吏出身。」老妇说，「他传我这行当，传的却不是收东西的法子。」「发懵的事是这样的：有个妇人丢了亡夫的一枚章，在我这儿登了记，急得三天没吃。」老妇说，「两年后东西寻着了，送上门——她看着章，忽然平静得很，说了声『原来在这』，就收下了，连谢都没谢。」老妇苦笑，「我懵了半个月。后来懂了：她这两年，是把人一点一点放下了。章送到了，她哀也尽了。我这一行，有时候送到的是东西，有时候送到的——是结局。」老妇送你到门口，回身望着满屋一箱无人认领的旧信：「客人，你笑我守破烂也好，敬我守念想也好——这屋子东西，早晚会一件一件回到人手里。到那时候，我这屋子空了，我这心，也就满了。」",options:[{label:"「替您跑这一趟。」",end:!0,effect:{stat:{wuxing:1},trait:{dan:1},ledger:{type:"义",text:"在报国寺学了两句话：丢了先想它在谁手里，捡了先想它归谁"},text_after:"你摸着那件失物说了自己的猜测——「丢它的人手上有茧，是做粗活出身，可这物件绣工极细，是替珍视的人做的。」老妇怔了半天，说：「二十年，头一回有人把它说活。」他把它单独搁到一个格子里，「照你这么说，它主人家里必还有一个等它的人。我再寻十年，也值得。」"}},{label:"「替人守物，自己吃什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"「痴人就痴人。」老妇坦然得很，「这世上总得有人痴——都精明着，丢的东西就真没了。你精明你的，我痴我的。哪天你精明不动了、累了，我这一屋子痴，兴许还能给你焐焐手。」"}}]}]},adv_g015_wenlu:{id:"adv_g015_wenlu",title:"在鬼市入口，只问不答的中年汉子",mother:"M7",channel:"T1",rarity:1,entry:{node:"guishi_ru",chance:.07},stages:[{xinglu:"是岁鬼市入口逢中年汉子。中年汉子的话糙，理却直——「人有答案还问，是心里不踏实；没答案就问，是心里明白。」",text:"中年汉子坐在一只装满纸条的竹筒旁，见谁都想问两句——问得认真，听得也认真。「有人说我故弄玄虚。」中年汉子不恼，「玄虚是我给你答案；我给你的是问题——问题这东西，你拿回去自己酿，酿出来的才解渴。」中年汉子看着你：「客人，我问你——你这一路，是奔着什么来的？别急着答，想清楚再说。」",options:[{label:"「您考我。」",goto:1,effect:void 0},{label:"「问那么多做什么，干活要紧。」",end:!0,effect:{stat:{wuxing:1},text_after:"「干活要紧，对。」中年汉子点头，「可我问你的不是话——是你干活的那个『为什么』。差事是别人派的，为什么干是你自己的。这两个不搭上，你干一辈子，也就是个工钱。」他把纸条又塞了塞，「不搭嘴。可你总有一天会想知道——到那天，纸条上见。」"}}]},{xinglu:"是岁鬼市入口一课。中年汉子把话说到根上——「天下没有蠢问题，只有不肯问的人。」",text:"「我最得意的一个问题，」中年汉子压低了声音，「救过一个人。」「救过人的那个问题，是这样：」中年汉子说，「有个后生来问路，话里话外透着不想活。我没劝——劝是最没用的。我就问他：你打算把这一身本事还给谁？他愣了。我说，你娘把你养这么大，你这一手好木匠活，是跟她学的还是自己学的？他哭了。哭完回去接着做木匠。后来他徒弟满天下——你说我那个问题值多少钱？」中年汉子摆摆手，「不值钱。可它会勾人——勾着勾着，人就把自己勾回来了。」「客人慢走。」中年汉子拱手，「你今天答了我好几个问题——答得对不对不要紧，你认真想了。认真想的人，走哪儿都带着先生。这先生就是你自己的那颗心——别偷懒使唤它。」",options:[{label:"「看，还是觉得——我记下了。」",end:!0,effect:{stat:{wuxing:1},trait:{ren:1},ledger:{type:"义",text:"从中年汉子的墙里摘走一个问句，一年后连本带利还了"},text_after:"你摘走的问题是：「你怕的东西，值得你怕么？」这个问题你在心里盘了一年，最后自己写了个答案寄回去。半年后你路过鬼市入口，看见你的答案被挂上了墙，旁边还有七八张别人还的「利息」。你站在满墙的问句前——那一家小店，原来早成了半条街的心里话。"}},{label:"「我从不问路，只看脚下的。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不顶饭吃？」中年汉子不急不恼，「饭是吃的，问题是活的。光吃饭不想事的人，跟牲口拉磨一个样——磨转得再快，路一寸没走。我不是笑话你——我五十岁之前也是这么活的。」他拍拍一只装满纸条的竹筒，「后来才明白：问，是人跟牲口隔的那一道。」"}}]}]},adv_g016_jizhang:{id:"adv_g016_jizhang",title:"白发老丈在鬼市替人情记着账",mother:"M8",channel:"T2",rarity:3,entry:{node:"guishi",chance:.05},stages:[{xinglu:"是岁鬼市逢白发老丈。白发老丈的话糙，理却直——「记账人手上要清，心上要热——光清不热，是阎王；光热不清，是糊涂虫。」",text:"鬼市里，白发老丈守着一匣子记着人情往来的木签，谁家有笔说不清的旧账，都来问他。「有人问我，死人欠的账记来做什么。」白发老丈说，「记。儿子长大来翻账——看见他爹当年受过谁的恩、还过谁的债，他就知道自己是个什么根底。账本就是家谱，还是最老实的那一页。」「帮我断个案子。」白发老丈把两个争执的人拉到一处，「他们都信你外乡人嘴严。」",options:[{label:"「头一页，讲讲。」",goto:1,effect:void 0},{label:"「人情账，记它做什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"「过去？」白发老丈摇头，「过得去的才叫过去。过不去的，你不理它，它就长在心里长成疙瘩。我这柜子里的账，一半是让人过得去的——账面摆出来，多少年的疙瘩，一句话就解了。」"}}]},{xinglu:"是岁鬼市一课。白发老丈把话说到根上——「情分这东西，不记账就散——散了再聚，就生分了。」",text:"「我这行也有对头。」白发老丈冷笑一声，「有人最恨我这本账——你猜是谁？」「师父考我的是：背错一笔账给我听。」白发老丈说，「我背了，背得一丝不差。他摇头说：你背的是字。他要的是我记错一笔——然后自己心疼。他说，不心疼账的记账人，记的是死数；心疼账的，记的才是人情。」白发老丈摩挲着账本，「我后来真记错过一回——心疼得半宿睡不着。从那晚起，我才算入了行。」「替我记一笔。」白发老丈忽然说，「就说：今天有个过路的客人，坐下来听完了整本账。这一笔记下——你也是账里的人了。」",options:[{label:"「回头我看自家那本账。」",end:!0,effect:{stat:{wuxing:1},trait:{ren:1},ledger:{type:"义",text:"替白发老丈送一册账抄本到邻县，一笔死账两头复活"},text_after:"你回头看自家那本账——还真翻出几笔糊的：有一年落难时接过的十文钱，有一个至今没谢过的人。你起身告辞，去把这十文钱的账清了。清完你忽然懂了白发老丈的话：账不是冰的——它热在你还它的那一刻。"}},{label:"「记账记成痴，何苦。」",end:!0,effect:{stat:{wuxing:1},text_after:"「销不得。」白发老丈摇头，「死账销了，你就当这人没来过。可他来过——他欠账的时候是个活人，有爹娘、有脾气、有舍不得。销账容易，抹一个人难。」他把死账那册抱在怀里，「我清明念他们名字的时候，庙里老和尚说我痴。我说你不痴不懂——被念到的名字，才算在人间留过脚印。」"}}]}]},adv_g017_shouwu:{id:"adv_g017_shouwu",title:"在帮派堂口，守着一件旧物的妇人",mother:"M5",channel:"T3",rarity:1,entry:{node:"tangkou",chance:.07},stages:[{xinglu:"是岁帮派堂口逢妇人。妇人的话糙，理却直——「守物的规矩只有一条：别让它在你手里断。」",text:"帮派堂口角上，妇人在给一排旧船坞掸灰，一下一下，像在给它梳头。「它在这儿站了几十年，看过的路人数都数不清。」妇人拍拍一排旧船坞，「东西不嫌人多——就嫌人忘。你多看它两眼，它就不算白站。」妇人忽然问你：「你说，我百年之后，这东西归谁？」问完自己先笑了：「急什么，还早。可这话总得问问人。」",options:[{label:"帮着擦一遍一排旧船坞",goto:1,effect:void 0},{label:"扫一眼就走",end:!0,effect:{stat:{wuxing:1},text_after:"「赶路要紧，是正经话。」妇人点头，「可我告诉你——路走完了，能想起来的，往往不是路上多快，是谁让你停了一脚。你走吧，我不拦。」你走出半里地，脚步不自觉慢了下来。"}}]},{xinglu:"是岁帮派堂口一课。妇人把话说到根上——「它站了几百年，我陪它站几年，不算多。」",text:"妇人坐下来，给你讲了件旧事——讲完自己半天没言语。「挨了那顿打，第二天我照样来擦它。」妇人说，「砸的人后来再来，是帮我一起擦的。你猜为什么？——他砸累了坐下来，看了它一晚上。」妇人从怀里掏出一小截红绳系在一排旧船坞上：「系上它，往后你就是半个守物人。规矩不用你背——见了它脏了，你心里过意不去，就够格了。」",options:[{label:"「这条规矩，我带走。」",end:!0,effect:{stat:{wuxing:1},trait:{zhi:1},ledger:{type:"恩",text:"与妇人共守一排旧船坞一夜，学会守物的规矩"},text_after:"你把来处和去处都念了。念完妇人笑得眼睛眯成一条缝：「好了，你们认识了。往后你不管走多远，它都算你认识的东西——人这辈子，认识的东西多了，心里就宽。」"}},{label:"「您自己守着就好。」",end:!0,effect:{stat:{wuxing:1},text_after:"妇人也不勉强：「记不记随你。这话搁在这儿，你哪天想起来了，就算我托到了。」你告辞出来，走出一段，那句话还是跟上了你——物在人守。你说不上来哪里被它戳中了。"}}]}]},adv_g018_chuanyi:{id:"adv_g018_chuanyi",title:"销金窟的一课：白发老丈把手艺往下传",mother:"M3",channel:"T1",rarity:1,entry:{node:"xiaojinku",chance:.12},stages:[{xinglu:"是岁销金窟逢白发老丈。白发老丈的话糙，理却直——「传艺先传心，心不正，手艺就是凶器。」",text:"销金窟里最齐整的就是一册手抄的方子簿——白发老丈说，家伙什齐整，手艺才齐整。「外行看手艺，看的是巧。」白发老丈说，「内行看的是匀——匀了才稳，稳了才久。做人一个理。」「你想不想知道这一册手抄的方子簿为什么是这个形？」白发老丈卖了个关子，「知道了你就明白一半了。」",options:[{label:"「为什么是这个形？」",goto:1,effect:void 0},{label:"「这些老规矩，过时了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「过时了？」白发老丈不急不恼，「老规矩过不过时，不看年头，看它护不护人。你哪天吃了没规矩的亏，自然会想起今天这话。」你嘴上应着，心里不服。三年后你真吃了那亏——想起这话时，人在异乡，败得一塌糊涂。"}}]},{xinglu:"是岁销金窟一课。白发老丈把话说到根上——「教会徒弟饿死师父——说这话的人，手艺本来就不到家。」",text:"白发老丈说起一个走了的徒弟，说到一半停了：「不提了。可你听我讲完——这事跟我这手艺有关。」「我那桩险事是这样的：」白发老丈道，「一册手抄的方子簿借给人用了三天，回来就不好使了。我查出问题，修了三天。从那以后我的规矩是：家伙什可以借，规矩不能借——借出去之前，先教会人家怎么用。后来我索性连人带艺一起教——教会了，就不怕借了。」「你要是也有一门营生，」白发老丈说，「记得往远处传。不一定要收徒——你把活做正了，看着的人自然学。」",options:[{label:"「您的手艺，不会断。」",end:!0,effect:{stat:{wuxing:2},trait:{ren:1},ledger:{type:"恩",text:"在销金窟亲手学做白发老丈的活，得「敢露怯」之教"},text_after:"你上了手，做得歪歪扭扭。白发老丈在旁边看着，不催不笑，等你做完才说：「歪归歪，下手不虚——你是块料，就是没人给你上过头一课。」你问什么头一课。他说：「敢在自己人面前做坏。多少有天分的人，就毁在不敢露怯上。」这句话你记了很多年。"}},{label:"「道理谁都会讲。」",end:!0,effect:{stat:{wuxing:1},text_after:"「要钱？」白发老丈愣了一下，随即大笑，「我今天一个字没收你钱，还搭了一下午的茶——你要是听成了要钱，那我这一下午白讲了，你的耳朵也白带了。走吧走吧——」他摆摆手，笑骂道，「亏你今天还看了我半天活。看活不看人，你差得远呢。」"}}]}]},adv_g019_haiyuan:{id:"adv_g019_haiyuan",title:"在乱葬义庄，替故人还愿的中年汉子",mother:"M4",channel:"T2",rarity:2,entry:{node:"yizhuang",chance:.07},stages:[{xinglu:"是岁乱葬义庄逢中年汉子。中年汉子的话糙，理却直——「愿这个东西，许的时候轻飘飘，还的时候千斤重。」",text:"乱葬义庄歇脚处，中年汉子给你看了一只没送到的木匣：「我要走很远的路，就为它。」「我跟他打了一辈子交道，就欠这一件。」中年汉子把一只没送到的木匣翻过来给你看，「你看这磨痕——都是他亲手磨的。他磨的时候念的什么，我大概知道。所以这愿，我认。」「你给评评理。」中年汉子把一只没送到的木匣递过来，「我这愿，还到这一步，算不算尽到心了？」",options:[{label:"「帮您辨认这页纸。」",goto:1,effect:void 0},{label:"「与我无关，让让。」",end:!0,effect:{stat:{wuxing:1},text_after:"「留着何用？」中年汉子把一只没送到的木匣举起来给你看，「你看它像东西吗？不像了——它是一句没说完的话。话没了，人才真的没了。」他说完自己收好，朝你拱拱手，「客人，话糙了。可这理，你早晚用得上。」"}}]},{xinglu:"是岁乱葬义庄一课。中年汉子把话说到根上——「人走了，愿不能跟着走——愿得有人替他走完。」",text:"中年汉子沉默了一阵，说：「其实这个愿，我本可以早点还的。」「讲一个还愿的故事：有个老猎户，临终托我把他攒的一袋盐分给当年一起守山的弟兄。」中年汉子说，「弟兄散了，我找了四年，七个找到了六个。第七个，去年在狱里寻着——他犯了事。我把盐给他，他捧着哭了半宿，说：哥几个还记着我。出狱那天，他来找我，如今在山上替人守林。你说，一袋盐值什么？可有些时候，一袋盐就是把人从沟里拉上来的绳。」「你要是记得今天这故事，」中年汉子说，「往后见着满头白发的还愿人，别笑他痴。给他一碗水——他替这世上所有走了的人，捎着话呢。」",options:[{label:"「这碗水，我记着。」",end:!0,effect:{stat:{wuxing:2},trait:{wen:1},ledger:{type:"义",text:"为中年汉子的故人之愿指了路，了却半桩心愿"},text_after:"「尽到心没尽到心，我自己知道。」中年汉子摇头，「可你说这话，我路上就不孤单了。还愿人最怕的不是路——是没人说一句『够了，可以了』。你说了一句。我记下了。」"}},{label:"「我帮不上，别缠着我。」",end:!0,effect:{stat:{wuxing:1},text_after:"「累？」中年汉子笑了，「我讲的累，是别人的命换来的道理。你嫌累，道理不怪你——可道理也不会再来找你。走吧。」你走出去半里，忽然想折回来问问他那花田的事——终究没折。那半里路，你走得比来时快，也比来时轻浮。"}}]}]},adv_g020_zengxing:{id:"adv_g020_zengxing",title:"酒旗长街来了个白送路上的东西的白发老丈",mother:"M1",channel:"T3",rarity:3,entry:{node:"yh_changjie",chance:.05},stages:[{xinglu:"是岁酒旗长街逢白发老丈。白发老丈的话糙，理却直——「路上的善，得有人开头——开头的人不当亏心事当。」",text:"酒旗长街的路边，白发老丈摆着一坛埋在路口的清水，来者不问，取者不问。「我年轻时走远路，饿昏在道上，是个不认识的老丈给了我半块饼。」白发老丈说，「那半块饼我记了四十年。我这一坛埋在路口的清水，就是还他那半块——还不上他本人，就还给他那样的路人。」「你给我评评，」白发老丈指着木牌，「这两个字哪个当头好——『自取』还是『共济』？我想了半年了。」",options:[{label:"「我取一份，谢谢。」",goto:1,effect:void 0},{label:"「白拿的东西，来路不正。」",end:!0,effect:{stat:{wuxing:1},text_after:"「来路？」白发老丈也不恼，把本子推给你看——进货的、出账的，一笔一笔清清楚楚。「我自己掏的钱，自己种的地。白给，是我乐意，不是我有诈。」他把东西又往前推了推，「你防备人是对的——路上是多坏人。可你把好人也一并防了，亏的是你自己。」你迟疑着收了，那东西用着，到底比别的甜些。"}}]},{xinglu:"是岁酒旗长街一课。白发老丈把话说到根上——「赠出去的每一件，都是投给这世道的一票——投它个好字。」",text:"「有人劝我立个碑，写上善人某某。」白发老丈摇头，「你听听我为什么不立。」「起头真是给自己备的。」白发老丈坦白道，「那年我落魄，怕自己哪天走投无路，就先备着——备着备着，先被人用了。用的人跟我说谢，我脸上臊——原来我备下的东西，早有人比我更需要。从那天起，这就不是我的退路了，是路上的公物。」白发老丈朝你挥挥手：「走吧走吧。东西拿了，话也听了——往后你也是个路上的人了。路上的人认路上的人，一眼就认得。」",options:[{label:"「东西我收了，情我记了。」",end:!0,effect:{stat:{wuxing:1},trait:{ren:1},ledger:{type:"义",text:"听白发老丈讲一盏灯化一个贼的旧事"},text_after:"「我可没说一定是我。」你摆手。白发老丈笑道：「兴许不是。可你今天多站了这半晌——比别人近了一步。这摊子挑人，跟守物挑人一样：挑肯停脚的。」你走出几里地回头望，他还坐在一坛埋在路口的清水边——像路长出来的一部分。"}},{label:"「我不信这些。」",end:!0,effect:{stat:{wuxing:1},text_after:"「哄你？」白发老丈笑了，「我哄你做什么？我又不要你的钱、不要你的命。我哄你，你就信了天下还有点好事——这买卖我亏了还是赚了？」他把东西又塞回你怀里，「拿着。信不信由你——东西是真的，渴了是真的，就这么简单。」"}}]}]},adv_g021_shouye:{id:"adv_g021_shouye",title:"驿站里夜里替人醒着的老妇",mother:"M2",channel:"T1",rarity:2,entry:{node:"yh_yizhan",chance:.09},stages:[{xinglu:"是岁驿站逢老妇。老妇的话糙，理却直——「我守的不是这一夜——我守的是「夜里有个人」这个念想。」",text:"你被老妇的梆子声唤醒——「三更了，无事。睡吧。」他巡过你的窗，脚步又轻又稳。「夜里我谁也不查。」老妇说，「我就是走。走给睡的人听——听见脚步，贼不敢动，病人心安，失眠的知道天总会亮。我这一双脚，是驿站的定心丸。」「帮我留意件事。」老妇压低声音，「近来驿站夜里多了个生面孔——不是我疑心，守夜人的疑心就是饭碗。你白天要是见着了，给我递个话。」",options:[{label:"「陪您走一段。」",goto:1,effect:void 0},{label:"「半夜不睡，有病吧。」",end:!0,effect:{stat:{wuxing:1},text_after:"「出息？」老妇笑了，「我这行没出息——没出息到二十年没人抢。可你想想，谁夜里敢不睡？不是我不想睡，是驿站几百户人拿觉换了我的不睡。」他敲了敲一仓新入的粮食，「出息这东西，白天论的。夜里的账，另算。」你将信将疑地走了。后来你在异乡的夜里病倒，是个守夜的老人照看了你——那一刻你想起这句话，眼睛忽然就热了。"}}]},{xinglu:"是岁驿站一课。老妇把话说到根上——「白天是人管人，夜里是心管心——守夜守的就是那颗不该动的心。」",text:"「守夜二十年，我就遇过一回真险。」老妇说到这儿，摸了摸一仓新入的粮食。「换班的事，是真出过。」老妇说，「有一年我病了半个月，换了个年轻的顶班。他守得也认真——可他睡觉沉。就那半个月，驿站丢了两头牲口、走失了一个老人——老人后来在河滩上寻着的，冻的。」老妇声音哑了，「不是他坏——是这行当挑人。觉沉的人守夜，等于没人守。从那以后我收徒，头一件事：看他睡觉。」老妇把灯吹熄了——天光已经泛白。「灯不用了。」他说，「灯是夜里的东西。你记住这盏灯照过你——就够了。」",options:[{label:"「保我十年太平。」",end:!0,effect:{stat:{wuxing:1},trait:{ren:1},ledger:{type:"恩",text:"为老妇递了一句生面孔的话，替驿站夜里防了一手"},text_after:"灯熄了，天亮了。你走出驿站很远，回头看不见灯，可你知道它在——就像你知道这世上有一群人，一辈子活在别人的梦里，为的是别人的梦别变成噩梦。你朝着驿站的方向作了个揖。天光大亮，路上人多了，谁也不知道你这一揖揖的是什么。"}},{label:"「守夜能守出什么名堂。」",end:!0,effect:{stat:{wuxing:1},text_after:"「运气？」老妇指指自己的眼睛，「我这双眼二十年没睡过一个整觉——驿站每一块松动的石头、每一个白天咽下事的夜行人、每一处该修没人修的堤口，都在我这儿记着。运气是留给没准备的。你说是运气就运气——反正鸡叫的时候，人人都囫囵着，这就够了。」"}}]}]},adv_g022_shiyi:{id:"adv_g022_shiyi",title:"驼背阿婆在平安号镖局分号替失物寻主人",mother:"M6",channel:"T2",rarity:1,entry:{node:"yh_biaoju",chance:.09},stages:[{xinglu:"是岁平安号镖局分号逢驼背阿婆。驼背阿婆的话糙，理却直——「拾遗不图利——图的是物归原主那一声「啊」。」",text:"你到平安号镖局分号时，驼背阿婆正对着一面牌子出神——牌上写着：「失物招领，三年不领，代为寻主」。「你看这物件，针脚多细。」驼背阿婆捧着它给你看，「做它的人花的工夫，比它本身的价钱贵十倍。丢它的人找不找得着它，就差我这样的人肯不肯多问一句。」「客人有闲功夫没有？」驼背阿婆半开玩笑，「搭把手，帮我给这箱子归归类。你归过的，我记下——算你在这行挂个号。」",options:[{label:"「它像是个念旧的人丢的。」",goto:1,effect:void 0},{label:"「一堆破烂，守着做什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"「痴人？」驼背阿婆摇头，「你丢了东西就知道了——丢东西的人，个个都是痴人。我见过丢了亡妻一支簪子的铁塔似的汉子，在我这儿哭成泪人。你笑痴——那是你的福气。真到了痴那天，你盼着世上多几个痴人。」他把门为你拉开，「慢走。愿你一辈子用不上我这行。」"}}]},{xinglu:"是岁平安号镖局分号一课。驼背阿婆把话说到根上——「东西无主的时候最可怜——可怜它们连个喊它名字的人都没有。」",text:"「拾遗这行，也有发懵的时候。」驼背阿婆说，「讲一件，你听听值不值。」「被忘了才是真的没了。」驼背阿婆说，「所以我这册子上的东西，一件都不许销。人忘了，我替他记着；他哪天想起来——哪怕想起来的是十年前的一件小事——东西还在，日子就还接得上。我这行当说到底，就是给人留个『接得上』。」驼背阿婆把册子递给你看：「客人，失物账一页一页都在这儿。你帮不上不要紧——记住：往后你丢了东西，先想想它在谁手里；捡了东西，先想想它归谁。这两句话做到了，我这行就算白教了你。」",options:[{label:"「两句话，我记牢了。」",end:!0,effect:{stat:{wuxing:2},trait:{wen:1},ledger:{type:"义",text:"一眼认出包袱上的字迹，省了驼背阿婆三个月的腿"},text_after:"你摸着那件失物说了自己的猜测——「丢它的人手上有茧，是做粗活出身，可这物件绣工极细，是替珍视的人做的。」驼背阿婆怔了半天，说：「二十年，头一回有人把它说活。」他把它单独搁到一个格子里，「照你这么说，它主人家里必还有一个等它的人。我再寻十年，也值得。」"}},{label:"「替人守物，自己吃什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"「再买就是？」驼背阿婆笑了，「钱能买回来的，都不叫失物。叫失物的，钱买不回来——亡人的东西、旧人的信、娃他娘缝的鞋。这些丢了，买一百件新的，心里那个窟窿还是圆不上。你年纪轻，还没到懂的时候——哪天懂了，别哭，来我这儿坐坐。」"}}]}]},adv_g023_wenlu:{id:"adv_g023_wenlu",title:"在城隍庙，只问不答的老妇",mother:"M7",channel:"T3",rarity:1,entry:{node:"yh_chenghuang",chance:.06},stages:[{xinglu:"是岁城隍庙逢老妇。老妇的话糙，理却直——「人有答案还问，是心里不踏实；没答案就问，是心里明白。」",text:"城隍庙里，老妇守着一只装满纸条的竹筒，面前立着块牌子：「只问不答」。「有人说我故弄玄虚。」老妇不恼，「玄虚是我给你答案；我给你的是问题——问题这东西，你拿回去自己酿，酿出来的才解渴。」「我考考你。」老妇眼睛一亮，「就一个问题——答上来，我这一只装满纸条的竹筒上的问题随你挑一个带走。」",options:[{label:"「我是在奔着一条路。」",goto:1,effect:void 0},{label:"「问那么多做什么，干活要紧。」",end:!0,effect:{stat:{wuxing:1},text_after:"「怪人就怪人。」老妇笑呵呵的，「城隍庙人人都这么叫。可你也看见了——他们路过还是要看一眼我那牌子。为什么？怪话里头，偶尔藏着正经。人不能全信怪人，可也不能一个怪人都不信——全信了傻，全不信了苦。你自己掂量。」他冲你摆摆手，继续挂他的问题。"}}]},{xinglu:"是岁城隍庙一课。老妇把话说到根上——「一个好问题，顶十个好答案。」",text:"「问了一辈子，也栽过跟头。」老妇说，「讲一件——讲完你就知道，问题也能伤人。」「我师父哑，怎么教我问？」老妇说，「他用手指比划，写在沙地上。他写的第一个问句是：你今天看见了什么？我答：什么都看见了。他摇头，写：不——你看见的是你觉得的。这句话我琢磨了半辈子。到今天，我每天还问自己这一句。」老妇指指一只装满纸条的竹筒，「这上头挂的头一个问题，就是他写的。」老妇把一张纸条郑重推给你：「这个问题归你了。不急——哪天想通了，丢进我这竹筒里就行，人不用来。问题认字不认人。」",options:[{label:"「这问题，我收下了。」",end:!0,effect:{stat:{wuxing:1},trait:{dan:1},ledger:{type:"恩",text:"受老妇所托带走一个三十年的问题"},text_after:"你摘走的问题是：「你怕的东西，值得你怕么？」这个问题你在心里盘了一年，最后自己写了个答案寄回去。半年后你路过城隍庙，看见你的答案被挂上了墙，旁边还有七八张别人还的「利息」。你站在满墙的问句前——那一家小店，原来早成了半条街的心里话。"}},{label:"「我从不问路，只看脚下的。」",end:!0,effect:{stat:{wuxing:1},text_after:"「答案？」老妇把牌子转过来给你看——「只问不答」四个字钉得结结实实。「我这不给答案，跟药铺不卖病一个理：病在你身上，药方在你身上，我这儿只管帮你把脉。」他把门推开，「你要答案，满街都是——街边随便拉个人都能给你一个。可你要问句，就得自己来。你不来，是你的损失。」"}}]}]},adv_g024_jizhang:{id:"adv_g024_jizhang",title:"驼背阿婆在车马行替人情记着账",mother:"M8",channel:"T1",rarity:1,entry:{node:"yh_chemahang",chance:.09},stages:[{xinglu:"是岁车马行逢驼背阿婆。驼背阿婆的话糙，理却直——「账不怕欠——怕的是没人记。记着，就还有还的一天。」",text:"驼背阿婆的一本记了几代人的情分簿在车马行人人都信——你说不清它记了多少年，只知道比庙里的功德碑还灵。「你看过穷人家怎么还账么？」驼背阿婆声音柔下来，「还一只鸡蛋、帮半天工、送一把自己种的葱。搁在钱庄，这不算还。搁在我这儿，照样一笔一笔冲抵——账清了，人的腰杆就直了。」「帮我断个案子。」驼背阿婆把两个争执的人拉到一处，「他们都信你外乡人嘴严。」",options:[{label:"「这笔账，我也想记。」",goto:1,effect:void 0},{label:"「人情账，记它做什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"「闲事？」驼背阿婆笑了，「张家的牛吃了李家的苗，是闲事；王家的娃读了书没人束脩，是闲事；你小时候发高热，邻家婶子背你走过三条街——也是闲事。这世上的情分，全是『闲事』堆出来的。我记的就是这些——你说的正事，反倒用不着我记。」"}}]},{xinglu:"是岁车马行一课。驼背阿婆把话说到根上——「记仇的不算记账人——记仇的账越记越窄，我这种账越记越宽。」",text:"「你见过两家人为一笔账断了二十年的来往么？」驼背阿婆说，「我接手过。」「最恨我的是人贩子。」驼背阿婆冷冷道，「他们拐走的孩子，我账上都有底——哪家孩子哪年生、什么胎记、谁抱走的。他们烧过我的铺子，砍过我的门。可账在人心里的那份，他们烧不掉——街上人人替我记着。」驼背阿婆把柜子锁好，「我这账本为什么比官府的册子灵？因为官府的册子锁在库里，我的账——长在几千户人的嘴里。」「我这行干到死。」驼背阿婆说，「死了我这账传给徒弟——徒弟再传徒弟。账本不怕旧，就怕断。你哪天路过，看看它还开着门不——开着，就说明有人接着记呢。」",options:[{label:"「回头我看自家那本账。」",end:!0,effect:{stat:{wuxing:2},trait:{zhi:1},ledger:{type:"义",text:"听驼背阿婆讲大饥年保账的旧事，识得一页纸的分量"},text_after:"「当得起什么。」驼背阿婆连连摆手，「我这行，说到底是替人管着念想。念想是他们的，我只是个保管员。」可你看得出来，他说这话时腰板挺得笔直——一个一辈子被几千户人信着的人，那份挺直，是拿三十年的笔一笔一笔撑起来的。"}},{label:"「死账就销了罢。」",end:!0,effect:{stat:{wuxing:1},text_after:"「靠山？」驼背阿婆把账本举起来，「靠山会倒，靠人会跑，靠钱会花完——靠账呢？账是死的，可它记得的事是活的。你走投无路那天，敲开一户人家的门，报上名姓，人家翻出账本：『你家当年救济过我们……』——你说这不是靠山，什么才是？我这柜子，是几千户人的老底。」"}}]}]},adv_g025_shouwu:{id:"adv_g025_shouwu",title:"少年在雁回峡守着一件旧物",mother:"M5",channel:"T2",rarity:1,entry:{node:"yh_xia",chance:.1},stages:[{xinglu:"是岁雁回峡逢少年。少年的话糙，理却直——「我陪它一辈子，它记我一辈子，两清。」",text:"雁回峡的角落里，少年守着一块无字碑，守得像守着一户人家。「有人问这破玩意儿有啥可守的。」少年笑了，「我说，你家里老人的旧物，你说有啥可留的？一个理——念想这东西，不作价。」「你眼神正。」少年端详你半天，「守东西这行，挑的就是眼神。你这样的，学会了走到哪儿都饿不死——心里有东西的人，饿不死。」",options:[{label:"「我听您说。」",goto:1,effect:void 0},{label:"「这种闲事，与我何干。」",end:!0,effect:{stat:{wuxing:1},text_after:"少年也没恼，只是摆摆手：「不守也对。守物这行，本来就挑人——不挑出个肯停脚的，守也守不住。」你走出去老远，回头一看，他还在擦。你忽然觉得，这世上的道理，一半在书里，一半在这样的人手里。"}}]},{xinglu:"是岁雁回峡一课。少年把话说到根上——「守的东西不值钱——守本身值钱。」",text:"「我师父守它三十年，我接了二十年。」少年说，「加起来五十年，还没它站着的年头长。」少年展开那件旧物，上面是一行字：「物在人守，人在物传。」——上一任守物人给他的话，如今他念给你听。「守物人不说谢。」少年说，「你要真帮了它，它自己会谢你——哪天你落难了，想起这世上有一处地方，有个东西好好站着——你就暖和了。」",options:[{label:"「替它谢谢您。」",end:!0,effect:{stat:{wuxing:1},trait:{zhi:1},ledger:{type:"恩",text:"在雁回峡听少年讲守一块无字碑的道理，助守一日"},text_after:"「它听见了。」少年把本子合上，「往后它记你一笔。你别不当真——东西的账比人的账久。人忘了，它身上那道擦亮的印子忘不了。」"}},{label:"「您自己守着就好。」",end:!0,effect:{stat:{wuxing:1},text_after:"「管不过来是实话。」少年点头，「可你今天站在它跟前这么久——它就多认得一个人。一个一个攒，攒着攒着，就有人管了。」"}}]}]},adv_g026_chuanyi:{id:"adv_g026_chuanyi",title:"水门码头里把手艺往下传的独臂客",mother:"M3",channel:"T3",rarity:2,entry:{node:"lj_shuimen",chance:.09},stages:[{xinglu:"是岁水门码头逢独臂客。独臂客的话糙，理却直——「手艺不传，人就白活一遭。」",text:"水门码头里最齐整的就是一杆磨得发亮的老秤——独臂客说，家伙什齐整，手艺才齐整。「外行看手艺，看的是巧。」独臂客说，「内行看的是匀——匀了才稳，稳了才久。做人一个理。」「你要是感兴趣，我讲细点。」独臂客说，「讲了你就懂——懂了的人，走到哪儿都替这门手艺说句话。」",options:[{label:"「我帮您对对字。」",goto:1,effect:void 0},{label:"「我有急事，不多聊。」",end:!0,effect:{stat:{wuxing:1},text_after:"「急事要紧，去忙吧。」独臂客摆摆手，忽然又补了一句：「急事里最急的，往往是最不该急的。你路上想想这话。」你出了门越想越不是味儿——他怎么知道你心里正为一件不该急的事上火？"}}]},{xinglu:"是岁水门码头一课。独臂客把话说到根上——「怕徒弟抢饭碗的，那手艺本来就该失传。」",text:"独臂客指指墙上挂的一幅旧字：「我师父写的。我挂了三十年，今天念给你听。」「那个走了样的徒弟，拿这门手艺坑人。」独臂客声音沉下来，「我上门去，当着人面把一杆磨得发亮的老秤从他手里要走回来——手艺是从这上头学的，现在从这上头收回来。他哭，我也难受。可规矩就是规矩：艺不正，师收之。」「我这一杆磨得发亮的老秤，早晚传给肯下苦功的人。」独臂客望着作坊，「也许是我徒弟，也许是徒弟的徒弟，也许——是个今天来歇脚的路人。缘分这东西说不准。」",options:[{label:"「我若有徒，也这么教。」",end:!0,effect:{stat:{wuxing:1},trait:{tong:1},ledger:{type:"恩",text:"帮独臂客校对手抄册子，替一门手艺把住传承"},text_after:"你上了手，做得歪歪扭扭。独臂客在旁边看着，不催不笑，等你做完才说：「歪归歪，下手不虚——你是块料，就是没人给你上过头一课。」你问什么头一课。他说：「敢在自己人面前做坏。多少有天分的人，就毁在不敢露怯上。」这句话你记了很多年。"}},{label:"「道理谁都会讲。」",end:!0,effect:{stat:{wuxing:1},text_after:"「要绝就绝。」独臂客淡淡地说，「手艺绝不绝，不看我这代人喊多响——看下代人肯不肯弯腰。我弯了三十年腰了，够了。绝了也不冤：它来的时候有人敬，走的时候有人送，全始全终。」你出门时回头看了一眼，独臂客已经又坐回一杆磨得发亮的老秤前——绝不绝的话撂在那儿，手上的活一天没停。"}}]}]},adv_g027_haiyuan:{id:"adv_g027_haiyuan",title:"漕帮总舵的一课：婆婆替故人还愿",mother:"M4",channel:"T1",rarity:1,entry:{node:"lj_caobang",chance:.06},stages:[{xinglu:"是岁漕帮总舵逢婆婆。婆婆的话糙，理却直——「故人最大的悲哀不是死——是心愿烂在没人知道的地方。」",text:"婆婆在漕帮总舵打听路，手里攥着一把没磨完的刀——他在替谁了却一桩心愿。「他说过，这事办成了，他就了无遗憾。」婆婆望着一把没磨完的刀，「他走了两年，我走了两万里的路。你说值不值？我不算这个账——我只知道，他临终看我的那一眼，我一辈子忘不掉。」「帮我看看这字还认得出么？」婆婆展开一页旧纸，「水渍沤了一角——这可是他的亲笔，少一个字，愿就缺一角。」",options:[{label:"「帮您辨认这页纸。」",goto:1,effect:void 0},{label:"「与我无关，让让。」",end:!0,effect:{stat:{wuxing:1},text_after:"「与我无关？」婆婆也不恼，「是啊，天下事都与谁无关呢？他跟我无关的时候，我欠了他一辈子。你走吧——愿你一辈子都用不上替人还愿。用不上，是福气。」"}}]},{xinglu:"是岁漕帮总舵一课。婆婆把话说到根上——「还愿不是还东西，是把人没说完的话说完。」",text:"婆婆沉默了一阵，说：「其实这个愿，我本可以早点还的。」「早点还不上，是因为我放不下脸面。」婆婆认了，「当年跟他置气，他托的事我故意拖着。后来他走了，我提着一把没磨完的刀在他坟前跪了一夜——第二天启程。你还愿，一半还的是他的愿，一半还的是自己的脸。我这张老脸，路上磨掉了一半，如今才算个人。」「你要是记得今天这故事，」婆婆说，「往后见着满头白发的还愿人，别笑他痴。给他一碗水——他替这世上所有走了的人，捎着话呢。」",options:[{label:"「您到家了，替他放心。」",end:!0,effect:{stat:{wuxing:2},trait:{yi:1},ledger:{type:"义",text:"在漕帮总舵听婆婆讲花田旧事，懂了「愿不能等」"},text_after:"你捎了他一程。一路上他把愿的来历讲了个通透，讲完长出一口气：「背了两年，今天讲顺了——讲顺了，就快了。」到了岔路口他下车，冲你长揖：「送佛送到西，你今天送的不止是我。」"}},{label:"「这故事听着累。」",end:!0,effect:{stat:{wuxing:1},text_after:"「累？」婆婆笑了，「我讲的累，是别人的命换来的道理。你嫌累，道理不怪你——可道理也不会再来找你。走吧。」你走出去半里，忽然想折回来问问他那花田的事——终究没折。那半里路，你走得比来时快，也比来时轻浮。"}}]}]},adv_g028_zengxing:{id:"adv_g028_zengxing",title:"书院来了个白送路上的东西的老人",mother:"M1",channel:"T2",rarity:1,entry:{node:"lj_shuyuan",chance:.1},stages:[{xinglu:"是岁书院逢老人。老人的话糙，理却直——「白给的东西要正大光明地白给——藏着掖着，善就变了味。」",text:"你路过书院，看见老人正把一缸摆在路边的凉茶摆放齐整——摆完冲空荡荡的路作了个揖。「有人问我图什么。」老人摆摆手，「图什么？我夜里从这儿过，看见路人的灯笼从我摆的东西旁边过去——那一刻我就图了。人活着，总得有点自己知道就行的事。」「客人腿脚快，是赶远路的？」老人问完不等答，已经把东西包好了，「远路更要带——不是干粮，是个念想。」",options:[{label:"「往后还走。」",goto:1,effect:void 0},{label:"「少来这套收买人心。」",end:!0,effect:{stat:{wuxing:1},text_after:"「白给的好事？」老人哈哈大笑，「你算算这笔账：我一年搭进去几贯钱，换来这条道上的人夜里敢走、白天敢歇——你说值几贯？好事从来都白给，只是给的人不说。」你把他的话琢磨了一路，到家门口才咂摸出味儿来。"}}]},{xinglu:"是岁书院一课。老人把话说到根上——「路上的善，得有人开头——开头的人不当亏心事当。」",text:"「我这一缸摆在路边的凉茶，起头不是给人用的。」老人声音低了，「是我给自己备的。」「最高兴的一回，是个哑巴。」老人说，「他拿了我半年，一句话说不了。有天他忽然比划着——旁边的货郎给我翻：他说，他往后的营生有了，是帮渡口搬货，东家管饭。说完他给我磕了个头。」老人抹了把脸，「我拦都没拦住。我不是图这个——可这个，比什么都沉。」「我老了，这摊子早晚交出去。」老人望着路，「交给谁？交给先坐下来的那个人。谁肯坐下来陪它过日子，它就是谁的。你哪天路过歇脚——兴许就是你。」",options:[{label:"「这摊子会一直在的。」",end:!0,effect:{stat:{wuxing:2},trait:{tong:1},ledger:{type:"义",text:"帮老人记了一日赠账，见一条道的人心"},text_after:"「我可没说一定是我。」你摆手。老人笑道：「兴许不是。可你今天多站了这半晌——比别人近了一步。这摊子挑人，跟守物挑人一样：挑肯停脚的。」你走出几里地回头望，他还坐在一缸摆在路边的凉茶边——像路长出来的一部分。"}},{label:"「别拿这些哄我。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不算上你。」老人点头，「我的账是我的。可你走在这条道上，喝过路边的井水、走过别人修的桥、睡过别人盖的亭子——这些账都跟我一样，没人跟你要过。」他拍拍一缸摆在路边的凉茶，「不用你算我的账。哪天你想起这世道不全是黑的，就够了。」"}}]}]},adv_g029_shouye:{id:"adv_g029_shouye",title:"在城外湖泽，夜里替人醒着的清瘦老者",mother:"M2",channel:"T3",rarity:2,entry:{node:"lj_huze",chance:.07},stages:[{xinglu:"是岁城外湖泽逢清瘦老者。清瘦老者的话糙，理却直——「我守的不是这一夜——我守的是「夜里有个人」这个念想。」",text:"城外湖泽的夜里只有清瘦老者醒着——他给你指了宿处，又提着一仓新入的粮食巡回去了。「白天他们叫我老夜猫子。」清瘦老者嘿嘿地笑，「等你夜里病了、丢了东西、被人堵了——你第一个想起的就是老夜猫子。到那时我就不是夜猫子了，是恩人。人呐，白天夜里两张脸，我两样都见惯了。」「夜里的事，你遇上过么？」清瘦老者问你，「遇上过就知道我这盏灯的用处了。」",options:[{label:"「夜里的事，讲讲。」",goto:1,effect:void 0},{label:"「黑路我自己认得。」",end:!0,effect:{stat:{wuxing:1},text_after:"「认得黑路是好事。」清瘦老者没拦你，「可你认得的是路——路认不认你，两说。去年有个自认得路的，掉进了拆了半截的桥坑里，躺了一夜——他不知道那坑，我知道。」他举灯照了照那个方向，「喏，就那儿。坑还在，天亮我得上报。」你没再犟，跟着他走了那条亮路。"}}]},{xinglu:"是岁城外湖泽一课。清瘦老者把话说到根上——「守一夜容易，守一年也不难——难的是守着守着，把别人的夜当成自己的夜。」",text:"「我师父传我一仓新入的粮食的时候说过一句话。」清瘦老者说，「我用了二十年才听懂。」「当官的那位，姓陈。」清瘦老者说，「那年他赶考，盘缠被偷了，蹲在一仓新入的粮食边上哭。我陪他坐了一夜，把攒的几吊钱塞给他——我婆娘还跟我吵了一架。后来他中了，回来找我，要给我修房子。我说不用——你记住这一夜就行：往后你坐堂，遇上夜里犯的事，先问问人家为什么夜里走这条路。」清瘦老者说，「他真照做了。去年他断了一桩案子——贼是贼，可贼的娘病着。他判了贼，也治了他娘的病。你说我这几吊钱，值不值？」「天快亮了。」清瘦老者打了个梆，「五更，天下太平。你听——鸡都叫了。这就是守夜人的一天：什么都没发生，就是最大的事。」",options:[{label:"「您的班，值得。」",end:!0,effect:{stat:{wuxing:1},trait:{zhi:1},ledger:{type:"义",text:"听清瘦老者讲砸门四十七扇的旧事，识得守夜人的分寸"},text_after:"天亮了。你按清瘦老者教的走了那条新路——果然避开了塌方段。回头望，清瘦老者已经收了灯，正往回走。他的背影在晨光里瘦得像根梆子，可你觉得，这一夜城外湖泽的太平，全是这根梆子敲出来的。"}},{label:"「别拦着我，我要赶路。」",end:!0,effect:{stat:{wuxing:1},text_after:"「名堂？」清瘦老者把灯举起来，「你看这灯照多远——三步。可走夜路的人，缺的就是这三步。」他放下灯，「名堂是白天的事。我夜里不图名堂——图的是城外湖泽的狗都不叫唤。狗都不叫，就是真太平。你要图名堂，白天去图；你要图太平，咱们才是一路的。」"}}]}]},adv_g030_shiyi:{id:"adv_g030_shiyi",title:"老汉在青羊观替失物寻主人",mother:"M6",channel:"T1",rarity:1,entry:{node:"lj_qingyang",chance:.09},stages:[{xinglu:"是岁青羊观逢老汉。老汉的话糙，理却直——「遗落的东西不会说话——可它们都在等人。」",text:"老汉在青羊观整理一筐孩子丢在路边的玩物，一件一件编号，比账房先生还仔细。「我这册子记了二十年。」老汉翻着一筐孩子丢在路边的玩物边的旧簿，「每件失物什么样子、哪儿捡的、像是谁丢的——都记着。册子比我的脑子靠得住。人的记忆会骗人，字不会。」「你眼神好。」老汉招手，「帮我认认——这个包袱上的字，是哪府的写法？」",options:[{label:"「这故事有意思，讲讲。」",goto:1,effect:void 0},{label:"「这行当，没出息。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不会找？」老汉叹口气，「客人，会找的人，丢的都是值钱东西。不会找的——老人丢了，孩子丢了，痴了的人丢了。他们自己找不了，家里人找疯了。我这行拾的，一半是物，一半是人。」他说完不再看你。你走出去几步，觉得方才那句话，轻佻得不像自己的。"}}]},{xinglu:"是岁青羊观一课。老汉把话说到根上——「东西丢了有人找，人丢了没人寻——我干的是寻人的活。」",text:"「我师父是官府的库吏出身。」老汉说，「他传我这行当，传的却不是收东西的法子。」「认走三回的那位，是个老先生。」老汉说，「第一回认走怀表，第二回认走烟斗，第三回又要认走一顶帽子——我留了个心眼，问他东西上有什么记号。他答不上来。」老汉叹口气，「不是贼——是痴了的老爷子。他的东西都在儿子那儿，他自个儿记不得，看见像我库里描述的就认。我没拆穿，陪他坐了一下午，听他讲他丢的每一件东西——哪一件背后都是他的老伴儿。后来他儿子来谢我，说老爷子那晚睡了两年来头一个整觉。」老汉把册子递给你看：「客人，失物账一页一页都在这儿。你帮不上不要紧——记住：往后你丢了东西，先想想它在谁手里；捡了东西，先想想它归谁。这两句话做到了，我这行就算白教了你。」",options:[{label:"「这行当，敬您一声。」",end:!0,effect:{stat:{wuxing:2},trait:{tong:1},ledger:{type:"恩",text:"在青羊观帮老汉归类失物，替七户人家拆了死结"},text_after:"「找主人要紧。」老汉点头，「可你方才那个问法好——问的是主人放下了没有。这些年我只顾找，忘了问这个。有的失物，主人早放下了，是我攥着不放。」他笑了，「所以你看，问路的功劳不在答——在问。你今天这一问，我这行当又多了一条规矩。」"}},{label:"「东西丢了再买就是。」",end:!0,effect:{stat:{wuxing:1},text_after:"「吃什么？」老汉指指墙角的一张木床、一只小灶，「我就住这儿。失物招领不收钱——我另有营生，替各家修修补补，饿不死。」他嘿嘿一笑，「你问的不是这个吧？你是问我图什么。图什么——图我娘。我娘丢了她的陪嫁镯子，急疯了。有人替她寻回来了。那年我十岁，站在门口看那个人把镯子递给我娘——我娘笑了。我这辈子，就想当那个人。」"}}]}]},adv_g031_wenlu:{id:"adv_g031_wenlu",title:"关墙戍楼来了个只问不答的清瘦老者",mother:"M7",channel:"T2",rarity:2,entry:{node:"tw_guanqiang",chance:.06},stages:[{xinglu:"是岁关墙戍楼逢清瘦老者。清瘦老者的话糙，理却直——「人有答案还问，是心里不踏实；没答案就问，是心里明白。」",text:"关墙戍楼的人都认得清瘦老者——那是个只提问题、从不给答案的怪人。「我这一张折了又折的路引上挂满了问句。」清瘦老者指给你看，「有客人替我答的，有我自己想了三十年的。挂在这儿——路过的人看一眼，想一会儿，这一会儿，就值。」「我考考你。」清瘦老者眼睛一亮，「就一个问题——答上来，我这一张折了又折的路引上的问题随你挑一个带走。」",options:[{label:"「这个利息，我还。」",goto:1,effect:void 0},{label:"「卖关子，无聊。」",end:!0,effect:{stat:{wuxing:1},text_after:"「我答？」清瘦老者摊开手，「我要是答得上，还开店做什么？」他指指一张折了又折的路引，「你看这满墙的问题——我答上的不到十个。剩下的，都是别人答的、路教的、年头给的。我这不是卖关子——我是个替人传话的，传天地的、传岁月的、传你自己心里的。你急着要我答，就像问镜子要路——路在你脚下，不在镜子里。」"}}]},{xinglu:"是岁关墙戍楼一课。清瘦老者把话说到根上——「人这一生，答案会过期——问题不会。」",text:"「有个问题，我自己答不上来。」清瘦老者望着一张折了又折的路引，「挂了三十年。今天说给你听听。」「问题伤人那件事，我认。」清瘦老者说，「有年一个败了家的商人来问我，我脱口问了一句：你的家业里，哪一样是你自己的？他当场就崩了——后来我才听说，他败家就是因为这辈子全在替他爹活。我那一问，是把他最后一块遮羞布扯了。」清瘦老者沉默半晌，「可第二年他回来谢我。他说那一问疼是疼，疼完才知道疼的原来是假的。问题这东西——下刀的时候狠，愈合的时候快。可我打那以后，问之前，都先看看人扛不扛得住。」「客人慢走。」清瘦老者拱手，「你今天答了我好几个问题——答得对不对不要紧，你认真想了。认真想的人，走哪儿都带着先生。这先生就是你自己的那颗心——别偷懒使唤它。」",options:[{label:"「有您这样的店，是关墙戍楼的福气。」",end:!0,effect:{stat:{wuxing:2},trait:{ren:1},ledger:{type:"义",text:"受清瘦老者所托带走一个三十年的问题"},text_after:"「先生就是你自己的心。」你出门时回头看了一眼——清瘦老者已经转回一张折了又折的路引前，又在写新问题了。你忽然明白这老头为什么从不给答案：答案是他给不起的——人人的路不一样。他给的是火折子，路得你自己摸黑走。可有了火折子，摸黑也走得直。"}},{label:"「问题再好，不顶饭吃。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不顶饭吃？」清瘦老者不急不恼，「饭是吃的，问题是活的。光吃饭不想事的人，跟牲口拉磨一个样——磨转得再快，路一寸没走。我不是笑话你——我五十岁之前也是这么活的。」他拍拍一张折了又折的路引，「后来才明白：问，是人跟牲口隔的那一道。」"}}]}]},adv_g032_jizhang:{id:"adv_g032_jizhang",title:"老人在马市替人情记着账",mother:"M8",channel:"T3",rarity:1,entry:{node:"tw_mashi",chance:.1},stages:[{xinglu:"是岁马市逢老人。老人的话糙，理却直——「记账人手上要清，心上要热——光清不热，是阎王；光热不清，是糊涂虫。」",text:"你到马市时，两个人正拉扯着找老人评理——老人翻开账本，一句话就断了案。「我这账，记的不是钱。」老人敲敲一串打了结记事的旧麻绳，「你欠谁一顿饭、谁替你垫过棺材本、你小时候谁背你趟过河——这些，钱还不清，礼还不上，就记在我这儿。记着，人情就还活着。」老人打量你一番：「客人面生——有没有旧账落在我这儿？有的话，报个名姓，我一翻便知。」",options:[{label:"「报个名姓，帮我翻翻。」",goto:1,effect:void 0},{label:"「你这行当，多管闲事。」",end:!0,effect:{stat:{wuxing:1},text_after:"「你不欠谁的——好啊。」老人忽然笑得眼睛弯起来，「这话我就给你记上：某年某月某日，有位客人说，他不欠谁的。这一笔怎么用呢——你哪天受了人的恩，想起这笔账，就得掂量掂量：真不欠，还是不肯欠？不肯欠的人多，不欠的少。」他冲你举举茶碗，「客人，别恼。账记上了，就等你哪天来改。」"}}]},{xinglu:"是岁马市一课。老人把话说到根上——「钱账好记，情账难记——难记的才需要人记。」",text:"「我师父传我的时候，只考了我一件事。」老人说，「不是算术——你猜猜是什么。」「烧账的事，是大饥那年。」老人说，「富户囤粮抬价，我这账上记着他们家欠下的十七户人情——都是灾年穷人帮过他们先人的。他们怕我这张账掀老底，半夜送来一箱金子，让我把那页烧了。」老人冷冷道，「我把金子退了，账抄了三份：一份我收着，一份藏在庙里，一份连夜送到那十七户人手里。后来饥年过完，那富户的粮，被十七户人凭一页旧账联名告发了。官府问：谁记的账？——没人说。账在，就够了。」「替我记一笔。」老人忽然说，「就说：今天有个过路的客人，坐下来听完了整本账。这一笔记下——你也是账里的人了。」",options:[{label:"「把我记上。」",end:!0,effect:{stat:{wuxing:1},trait:{xin:1},ledger:{type:"义",text:"帮老人誊账一页，字正心平，得了保管员三分真传"},text_after:"你替他跑了一趟，把一册抄本送到了邻县。收账的是个白胡子老者，翻开一看就红了眼：「还有人记着这笔……」你回程时老人已在门口候着——他不要你讲细节，只问了一句：「送到就行了？」你说送到了。他长出一口气：「好。这一笔，两头都活了。」"}},{label:"「人情最靠不住，你记了也白记。」",end:!0,effect:{stat:{wuxing:1},text_after:"「白记？」老人居然点头，「你说得对——十笔情账，有三笔是白记的。可剩下七笔呢？」他翻开册子给我看密密麻麻的还账记录，「人情是靠不住——可总得有人头一个信。我信了三十年，换回这七本册子的『还』字。你赌人不靠得住，你赌输了也就输了；我赌人靠得住，我赢得一街的太平。这笔账，你自己算。」"}}]}]},adv_g033_shouwu:{id:"adv_g033_shouwu",title:"路遇盲眼老者——在佛骨塔下院守着一件旧物",mother:"M5",channel:"T1",rarity:1,entry:{node:"tw_foguta",chance:.11},stages:[{xinglu:"是岁佛骨塔下院逢盲眼老者。盲眼老者的话糙，理却直——「物是死的，可你守它的年头是活的。」",text:"你还没开口，盲眼老者先给你讲了一座老水闸的故事——讲得像讲自家孩子。「当年交给我的时候说，守到守不动为止。」盲眼老者摩挲着一座老水闸，「我算了算，还早。我还能守——它也还站得住。」「帮我看看它哪儿不对。」盲眼老者退开半步，「外人一眼看出来的毛病，守的人反而看不见。」",options:[{label:"「您守它，图什么？」",goto:1,effect:void 0},{label:"「这种闲事，与我何干。」",end:!0,effect:{stat:{wuxing:1},text_after:"你绕着走了。走出去老远，风里飘来一句话似的调子——盲眼老者在给一座老水闸哼曲儿。你忽然明白：人家守得高兴，根本不在乎你看不看。这么一想，你的脚步倒轻快了。"}}]},{xinglu:"是岁佛骨塔下院一课。盲眼老者把话说到根上——「守到后来，分不清是我守它，还是它守我。」",text:"盲眼老者收了抹布，话头一转：「守它这些年，也不是没动摇过。」「挨了那顿打，第二天我照样来擦它。」盲眼老者说，「砸的人后来再来，是帮我一起擦的。你猜为什么？——他砸累了坐下来，看了它一晚上。」盲眼老者从怀里掏出一小截红绳系在一座老水闸上：「系上它，往后你就是半个守物人。规矩不用你背——见了它脏了，你心里过意不去，就够格了。」",options:[{label:"「这条规矩，我带走。」",end:!0,effect:{stat:{wuxing:1},trait:{zhi:1},ledger:{type:"义",text:"在佛骨塔下院听盲眼老者讲守一座老水闸的道理，助守一日"},text_after:"你帮着查出了两处毛病——一处是底座松了，一处是渗水。盲眼老者当场就修，修完冲你抱拳：「你这一眼，顶它多站十年。」你摆手说客气了，他正色道：「不是客气。守物人最大的难处是看不出毛病——你看出来了，就是它的造化。」"}},{label:"「天下旧物多了，管不过来。」",end:!0,effect:{stat:{wuxing:1},text_after:"盲眼老者也不勉强：「记不记随你。这话搁在这儿，你哪天想起来了，就算我托到了。」你告辞出来，走出一段，那句话还是跟上了你——物在人守。你说不上来哪里被它戳中了。"}}]}]},adv_g034_chuanyi:{id:"adv_g034_chuanyi",title:"在关外荒驿，把手艺往下传的婆婆",mother:"M3",channel:"T2",rarity:1,entry:{node:"tw_huangyi",chance:.08},stages:[{xinglu:"是岁关外荒驿逢婆婆。婆婆的话糙，理却直——「手艺这东西，捂在手里就馊了——得传。」",text:"婆婆见了你，先把手上的活做完才抬头：「客人别笑话，手艺人的规矩，做不完的活不抬头。」婆婆教你认一把断了又接的长篙的门道：「你看这儿，磨了三十年才有的包浆。手艺也一样——急不来的东西，才立得住。」「来，站我旁边看。」婆婆招招手，「看一遍，顶听十遍。」",options:[{label:"「我试试。」",goto:1,effect:void 0},{label:"「我有急事，不多聊。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不值一提？」婆婆也不争辩，只把刚做好的活递给你看——那一处细节，你盯了半天才看出来门道。「你再看一遍，」他说，「不值一提的东西，为什么你一提就提不出来？」你臊了，他哈哈大笑：「逗你的。手艺不值一提，提的是心——你有心，就能看见。」"}}]},{xinglu:"是岁关外荒驿一课。婆婆把话说到根上——「传艺如点灯——你点了我，我点他，火就一直亮。」",text:"「人家都说教会徒弟饿死师父。」婆婆把茶碗一放，「我给你讲讲我师父是怎么『饿死』的。」「成器的那个，如今在外头独当一面；走了样的那三个，拿了手艺去糊弄人。」婆婆说，「我记牢的是骂我最狠的那个——他嫌我严，走了。前年他回来磕头，说在外头吃了不懂规矩的亏。我没怪他——他这一圈弯路，就是他没听完的课。」婆婆送你到门口：「来，我这有句话送出门的客人——艺是拿来敬的，不是拿来用的。敬它，它养你一辈子。」",options:[{label:"「谢先生一课。」",end:!0,effect:{stat:{wuxing:2},trait:{wen:1},ledger:{type:"恩",text:"在关外荒驿亲手学做婆婆的活，得「敢露怯」之教"},text_after:"你上了手，做得歪歪扭扭。婆婆在旁边看着，不催不笑，等你做完才说：「歪归歪，下手不虚——你是块料，就是没人给你上过头一课。」你问什么头一课。他说：「敢在自己人面前做坏。多少有天分的人，就毁在不敢露怯上。」这句话你记了很多年。"}},{label:"「说了这么多，不就是要钱。」",end:!0,effect:{stat:{wuxing:1},text_after:"「要绝就绝。」婆婆淡淡地说，「手艺绝不绝，不看我这代人喊多响——看下代人肯不肯弯腰。我弯了三十年腰了，够了。绝了也不冤：它来的时候有人敬，走的时候有人送，全始全终。」你出门时回头看了一眼，婆婆已经又坐回一把断了又接的长篙前——绝不绝的话撂在那儿，手上的活一天没停。"}}]}]},adv_g035_haiyuan:{id:"adv_g035_haiyuan",title:"老人在赌坊替故人还愿",mother:"M4",channel:"T3",rarity:1,entry:{node:"hq_dufang",chance:.13},stages:[{xinglu:"是岁赌坊逢老人。老人的话糙，理却直——「还愿的人不问值不值——问值不值的时候，愿就已经不是愿了。」",text:"老人把一封没寄出去的信护在怀里避雨——护得比自己的性命还紧。「家里人劝我，人走了就放下。」老人摇头，「放下是给活人的宽心话。可愿不是包袱——愿是路标。我把这个愿还了，往后他坟头的草，我看着都顺眼。」「你给评评理。」老人把一封没寄出去的信递过来，「我这愿，还到这一步，算不算尽到心了？」",options:[{label:"「我听过，说与你听。」",goto:1,effect:void 0},{label:"「路远事烦，别找了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「与我无关？」老人也不恼，「是啊，天下事都与谁无关呢？他跟我无关的时候，我欠了他一辈子。你走吧——愿你一辈子都用不上替人还愿。用不上，是福气。」"}}]},{xinglu:"是岁赌坊一课。老人把话说到根上——「愿这个东西，许的时候轻飘飘，还的时候千斤重。」",text:"「有人劝我把一封没寄出去的信放到庙里，让菩萨替我管。」老人摇头，「你听听我为什么不肯。」「蹊跷事是这样的：那年到地方，收信的人家早搬了。」老人说，「我打听三个月，问遍十里八乡——就在我要走的前一天，一个后生找上门：我是他孙子，爷爷临终说，会有人送东西来。」老人摊开手，「你说，愿认路，还是我认路？我不知道。我只知道，愿不能停在半道。」「我走了。」老人背起行囊，「这愿还完，我就回家种地——把替人还愿的道理，讲给村口的娃娃们听。让他们知道：这世上有一种债，还的是心安。」",options:[{label:"「我记住了。」",end:!0,effect:{stat:{wuxing:1},trait:{dan:1},ledger:{type:"恩",text:"捎老人一程，听了一个还愿人的故事"},text_after:"你把记得的线索全说了——竟真有一条有用。老人愣在原地，半晌，深深作了个揖：「客人，你今天替一个走了两年的人，把愿往前推了三里地。」他非要留给你一样谢礼，你说不必，他坚持：「愿上的账，不能欠。你收下——不然我这一路，就白背了心债。」"}},{label:"「我帮不上，别缠着我。」",end:!0,effect:{stat:{wuxing:1},text_after:"「完了就完了？」老人站定，认真看你，「人走茶凉是世道。可我把茶端热的这些年，凉不了——你信不信？你今天说这话，是因为还没遇着走的人。遇着了，你会想起我。」他走了，那句话你揣了一路，越揣越沉。"}}]}]},adv_g036_zengxing:{id:"adv_g036_zengxing",title:"白发老丈在黑市白送路上的东西",mother:"M1",channel:"T1",rarity:1,entry:{node:"hq_heishi",chance:.13},stages:[{xinglu:"是岁黑市逢白发老丈。白发老丈的话糙，理却直——「我不图报——我只求受的人往后也肯搭把手。」",text:"黑市的路边，白发老丈摆着一桶拴在渡口的姜汤，来者不问，取者不问。「别多想，不是施舍。」白发老丈把东西推给你，「施舍是人上人下，我这个是递手——你渴了，我这里正好有。就这么简单。」「你给我评评，」白发老丈指着木牌，「这两个字哪个当头好——『自取』还是『共济』？我想了半年了。」",options:[{label:"「我取一份，谢谢。」",goto:1,effect:void 0},{label:"「少来这套收买人心。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不占便宜是好品性。」白发老丈点头，「可我这不叫便宜——叫过路钱。你今天不喝我这口，往后你发达了在别处摆摊，让人白喝——这账就平了。」他硬塞给你，「路上没有白拿，只有先拿后还。你先欠着，我说这话不臊——你将来还得起。」"}}]},{xinglu:"是岁黑市一课。白发老丈把话说到根上——「白给的东西要正大光明地白给——藏着掖着，善就变了味。」",text:"「有人劝我立个碑，写上善人某某。」白发老丈摇头，「你听听我为什么不立。」「那年来了个贼，夜里偷我的东西不说，还砸了我的牌子。」白发老丈说，「我第二天照样摆，牌子重写一块，添了四个字：『夜路慢行』。后来那贼又来——这回是白天，红着脸放下一捆柴，一句话没说走了。」白发老丈呵呵地笑，「你瞧，善这东西不咬人，它泡人。泡久了，铁石心肠也软。」白发老丈朝你挥挥手：「走吧走吧。东西拿了，话也听了——往后你也是个路上的人了。路上的人认路上的人，一眼就认得。」",options:[{label:"「这摊子会一直在的。」",end:!0,effect:{stat:{wuxing:2},trait:{yi:1},ledger:{type:"义",text:"听白发老丈讲一盏灯化一个贼的旧事"},text_after:"「我可没说一定是我。」你摆手。白发老丈笑道：「兴许不是。可你今天多站了这半晌——比别人近了一步。这摊子挑人，跟守物挑人一样：挑肯停脚的。」你走出几里地回头望，他还坐在一桶拴在渡口的姜汤边——像路长出来的一部分。"}},{label:"「别拿这些哄我。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不算上你。」白发老丈点头，「我的账是我的。可你走在这条道上，喝过路边的井水、走过别人修的桥、睡过别人盖的亭子——这些账都跟我一样，没人跟你要过。」他拍拍一桶拴在渡口的姜汤，「不用你算我的账。哪天你想起这世道不全是黑的，就够了。」"}}]}]},adv_g037_shouye:{id:"adv_g037_shouye",title:"在药人坊，夜里替人醒着的老汉",mother:"M2",channel:"T2",rarity:2,entry:{node:"hq_yaorenfang",chance:.1},stages:[{xinglu:"是岁药人坊逢老汉。老汉的话糙，理却直——「守夜这行，眼睛不能好使——太好使了，看见的事多，心里搁不下。」",text:"药人坊的夜里只有老汉醒着——他给你指了宿处，又提着一条巷子的更道巡回去了。「夜里我谁也不查。」老汉说，「我就是走。走给睡的人听——听见脚步，贼不敢动，病人心安，失眠的知道天总会亮。我这一双脚，是药人坊的定心丸。」「夜里的事，你遇上过么？」老汉问你，「遇上过就知道我这盏灯的用处了。」",options:[{label:"「劳驾送一程。」",goto:1,effect:void 0},{label:"「黑路我自己认得。」",end:!0,effect:{stat:{wuxing:1},text_after:"「有病？」老汉也不恼，「我这病生了二十年，治好了几百户人的安稳觉。你说谁有病？」他把灯一提，「前头黑，跟紧——有病的人给你照路。」你跟着他走过那段黑路，一路无话。到了亮处他站住：「去吧。有病的人不送了。」你走出老远，回头看那点灯火还立在原地——你忽然觉得，有病的人，比没病的都清醒。"}}]},{xinglu:"是岁药人坊一课。老汉把话说到根上——「守夜不图别的——图鸡叫的时候，家家还都是囫囵的。」",text:"「白天的官府管不了的，夜里都得有人管。」老汉说，「你猜夜里都有什么事？」「夜里的事，是病人、是醉汉、是走投无路的人。」老汉一样样数给你听，「产妇半夜要生，是我跑去接的稳婆；醉汉躺在冰边上，是我拖回来的；还有个后生想跳河——我在河边陪他坐到天亮，一句话没劝，他就自己回去了。」老汉叹口气，「白天的人都以为夜里干净。夜里最不干净——夜里的难处，都是白天咽下去的。」「我这班，还守得动十年。」老汉活动着腿脚，「十年后谁接？我挑着呢。你若哪天走投无路——来找我。守夜人缺人手，也缺心里有夜的人。」",options:[{label:"「您的班，值得。」",end:!0,effect:{stat:{wuxing:2},trait:{xin:1},ledger:{type:"恩",text:"受老汉夜路相送一程，药人坊三里无事故"},text_after:"「心里有夜的人。」你把这句话带了很多年。后来你做了点小营生，雇伙计先看人睡觉——都笑你怪。你想起老汉，也不解释。守夜人的道理，本来就是说给夜里的人听的。"}},{label:"「别拦着我，我要赶路。」",end:!0,effect:{stat:{wuxing:1},text_after:"「名堂？」老汉把灯举起来，「你看这灯照多远——三步。可走夜路的人，缺的就是这三步。」他放下灯，「名堂是白天的事。我夜里不图名堂——图的是药人坊的狗都不叫唤。狗都不叫，就是真太平。你要图名堂，白天去图；你要图太平，咱们才是一路的。」"}}]}]},adv_g038_shiyi:{id:"adv_g038_shiyi",title:"镇外乱葬岭来了个替失物寻主人的老妇",mother:"M6",channel:"T3",rarity:1,entry:{node:"hq_luanzangling",chance:.07},stages:[{xinglu:"是岁镇外乱葬岭逢老妇。老妇的话糙，理却直——「世上的失物比失物的人多——总得有人替它们排队等主人。」",text:"老妇见你打量一摞当铺里过期的死当，主动开了口：「别看它们破——件件都有来处，件件都在等人。」「这一屋子，全是三年没人认的。」老妇拍了拍一摞当铺里过期的死当，「按理可以处置了。我不——三年找不到主人，我就再等三年。东西等得起，等不起的是万一哪天，那个找它的人来了，东西没了。」老妇忽然问你：「客人一路走来，可曾在别处见过这样的物件？」他把一件失物举到你眼前。",options:[{label:"「我没见过，帮不上。」",goto:1,effect:void 0},{label:"「一堆破烂，守着做什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"「没出息。」老妇笑了，「对——没出息，饿不死，也发不了。可你告诉我，什么行当能让人二十年睡得着觉？我这行能。我每送回一件东西，就有一户人家少一夜的睡不着。」他拱拱手，「出息是活给别人看的，觉是自己睡的。慢走。」"}}]},{xinglu:"是岁镇外乱葬岭一课。老妇把话说到根上——「东西无主的时候最可怜——可怜它们连个喊它名字的人都没有。」",text:"「我这行有个祖师爷。」老妇笑了，「说出来你都不信——是个邮差。」「师父传我的话是：物有主，主有心，心有急缓。」老妇说，「收东西的法子三天就会，辨人心的功夫十年难成。丢了药方的人和丢了银子的，急法不一样；丢东西的穷人和丢东西的富人，找法也不一样。这行当的功夫，全在听人说丢东西那几句话里。」老妇送你到门口，回身望着满屋一摞当铺里过期的死当：「客人，你笑我守破烂也好，敬我守念想也好——这屋子东西，早晚会一件一件回到人手里。到那时候，我这屋子空了，我这心，也就满了。」",options:[{label:"「两句话，我记牢了。」",end:!0,effect:{stat:{wuxing:1},trait:{wen:1},ledger:{type:"义",text:"受老妇所托，携一件失物出远门寻主"},text_after:"你认出了包袱上的字——是北边某府的馆阁体，还带着军中的写法。「军中的！」老妇一拍大腿，「怪不得我在商旅里问不出——我往驿站问去！」他高兴得像捡了宝，拉着你的手直摇：「客人，你这一眼，顶我三个月的腿。」"}},{label:"「替人守物，自己吃什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"「吃什么？」老妇指指墙角的一张木床、一只小灶，「我就住这儿。失物招领不收钱——我另有营生，替各家修修补补，饿不死。」他嘿嘿一笑，「你问的不是这个吧？你是问我图什么。图什么——图我娘。我娘丢了她的陪嫁镯子，急疯了。有人替她寻回来了。那年我十岁，站在门口看那个人把镯子递给我娘——我娘笑了。我这辈子，就想当那个人。」"}}]}]},adv_g039_wenlu:{id:"adv_g039_wenlu",title:"入坞山门里只问不答的独臂客",mother:"M7",channel:"T1",rarity:2,entry:{node:"bc_yaomen",chance:.06},stages:[{xinglu:"是岁入坞山门逢独臂客。独臂客的话糙，理却直——「我问了一辈子——问出来的东西，比读出来的多。」",text:"独臂客正把新写的问题挂上一册写满问句的手记：「客人看看，这个问题值得挂么？」「我这一册写满问句的手记上挂满了问句。」独臂客指给你看，「有客人替我答的，有我自己想了三十年的。挂在这儿——路过的人看一眼，想一会儿，这一会儿，就值。」「我考考你。」独臂客眼睛一亮，「就一个问题——答上来，我这一册写满问句的手记上的问题随你挑一个带走。」",options:[{label:"「我想清楚再答。」",goto:1,effect:void 0},{label:"「问那么多做什么，干活要紧。」",end:!0,effect:{stat:{wuxing:1},text_after:"「无聊？」独臂客哈哈大笑，「你这话说得对——问题是挺无聊的。答案多痛快，一刀见血。可我告诉你，一刀见血的痛快，跟一刀断命的糊涂，是同一个刀法。你嫌我无聊，就是嫌自己想事太慢——慢工出的东西，急工比不了。走吧走吧，等你哪天急不动了，自然会回来找无聊。」"}}]},{xinglu:"是岁入坞山门一课。独臂客把话说到根上——「问路的人最聪明——他省下的冤枉路，就是他的学问。」",text:"「有人骂我，说问了半天屁用没有。」独臂客居然点头，「他骂得对。你听听怎么回事。」「三十年挂着的那个问题是：人这一生，是答案重要，还是问得对重要？」独臂客缓缓道，「年轻时我赌答案是重要的——答对了就赢了。后来发现，答对的都有过期的一天。如今我改赌了：问得对重要。问对了，答错了能重来；问错了，答对了也是白答。」独臂客笑了笑，「你呢？你怎么赌？不用现在答——这个问题，现在也归你了。」「客人慢走。」独臂客拱手，「你今天答了我好几个问题——答得对不对不要紧，你认真想了。认真想的人，走哪儿都带着先生。这先生就是你自己的那颗心——别偷懒使唤它。」",options:[{label:"「先生二字，您当得起。」",end:!0,effect:{stat:{wuxing:2},trait:{ren:1},ledger:{type:"恩",text:"从独臂客的墙里摘走一个问句，一年后连本带利还了"},text_after:"你摘走的问题是：「你怕的东西，值得你怕么？」这个问题你在心里盘了一年，最后自己写了个答案寄回去。半年后你路过入坞山门，看见你的答案被挂上了墙，旁边还有七八张别人还的「利息」。你站在满墙的问句前——那一家小店，原来早成了半条街的心里话。"}},{label:"「问题再好，不顶饭吃。」",end:!0,effect:{stat:{wuxing:1},text_after:"「从不问路？」独臂客看着你，忽然认真了，「客人，我不拦你。可我送你一句话：不问路的人，不是路盲——是路盲里胆子最大的。老天爷不在乎你问不问，它只管把你引到岔路口。你凭本事闯，闯对了是命大，闯错了——」他顿了顿，「没有人给你收尸。走吧。这话搁这儿，你哪天想起，算我的。」"}}]}]},adv_g040_jizhang:{id:"adv_g040_jizhang",title:"药市大街的一课：婆婆替人情记着账",mother:"M8",channel:"T2",rarity:1,entry:{node:"bc_yaoshi",chance:.13},stages:[{xinglu:"是岁药市大街逢婆婆。婆婆的话糙，理却直——「别人记账怕错——我记账怕漏。错了改得回来，漏了就真没了。」",text:"婆婆正往一册人人信服的老账本上添一笔，添完念给你听：「某年某月，某人还清。」——念得像唱。「我这账，记的不是钱。」婆婆敲敲一册人人信服的老账本，「你欠谁一顿饭、谁替你垫过棺材本、你小时候谁背你趟过河——这些，钱还不清，礼还不上，就记在我这儿。记着，人情就还活着。」「帮我断个案子。」婆婆把两个争执的人拉到一处，「他们都信你外乡人嘴严。」",options:[{label:"「我来断。」",goto:1,effect:void 0},{label:"「人情账，记它做什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"「记它做什么？」婆婆把笔搁下，「你不记，它就不存在了么？不——它在你心里烂着，在他心里烂着，两败俱伤。记出来，才有得还、有得清、有得忘。账不是记仇——是把烂在心里的东西，拿到日头底下晾晾。」"}}]},{xinglu:"是岁药市大街一课。婆婆把话说到根上——「情分这东西，不记账就散——散了再聚，就生分了。」",text:"「账本上最沉的一页，」婆婆翻出来给你看，「不是钱最多的那页。你认认这页上的字。」「师父考我的是：背错一笔账给我听。」婆婆说，「我背了，背得一丝不差。他摇头说：你背的是字。他要的是我记错一笔——然后自己心疼。他说，不心疼账的记账人，记的是死数；心疼账的，记的才是人情。」婆婆摩挲着账本，「我后来真记错过一回——心疼得半宿睡不着。从那晚起，我才算入了行。」「替我记一笔。」婆婆忽然说，「就说：今天有个过路的客人，坐下来听完了整本账。这一笔记下——你也是账里的人了。」",options:[{label:"「它开着门，我就放心。」",end:!0,effect:{stat:{wuxing:2},trait:{tong:1},ledger:{type:"恩",text:"替婆婆送一册账抄本到邻县，一笔死账两头复活"},text_after:"你回头看自家那本账——还真翻出几笔糊的：有一年落难时接过的十文钱，有一个至今没谢过的人。你起身告辞，去把这十文钱的账清了。清完你忽然懂了婆婆的话：账不是冰的——它热在你还它的那一刻。"}},{label:"「人情最靠不住，你记了也白记。」",end:!0,effect:{stat:{wuxing:1},text_after:"「销不得。」婆婆摇头，「死账销了，你就当这人没来过。可他来过——他欠账的时候是个活人，有爹娘、有脾气、有舍不得。销账容易，抹一个人难。」他把死账那册抱在怀里，「我清明念他们名字的时候，庙里老和尚说我痴。我说你不痴不懂——被念到的名字，才算在人间留过脚印。」"}}]}]},adv_g041_shouwu:{id:"adv_g041_shouwu",title:"药王庙的一课：老妇守着一件旧物",mother:"M5",channel:"T3",rarity:1,entry:{node:"bc_yaowangmiao",chance:.11},stages:[{xinglu:"是岁药王庙逢老妇。老妇的话糙，理却直——「它站了几百年，我陪它站几年，不算多。」",text:"药王庙的角落里，老妇守着一块无字碑，守得像守着一户人家。老妇说守这东西有讲究：「每天来看一眼，缺了补，脏了擦。不为别的——它要是哪天塌了，方圆几十里的人，心里都得空一块。」老妇忽然问你：「你说，我百年之后，这东西归谁？」问完自己先笑了：「急什么，还早。可这话总得问问人。」",options:[{label:"「它的来历，讲讲。」",goto:1,effect:void 0},{label:"不搭话，绕着走",end:!0,effect:{stat:{wuxing:1},text_after:"「换是要换的，」老妇在你背后说，「可换下来旧的，总得有人管。都等着别人管，旧的就都成了垃圾。」你没回头，可这句话跟了你一路。"}}]},{xinglu:"是岁药王庙一课。老妇把话说到根上——「东西没了可以再造，守的规矩断了就接不上。」",text:"老妇坐下来，给你讲了件旧事——讲完自己半天没言语。「挨了那顿打，第二天我照样来擦它。」老妇说，「砸的人后来再来，是帮我一起擦的。你猜为什么？——他砸累了坐下来，看了它一晚上。」「守物人不说谢。」老妇说，「你要真帮了它，它自己会谢你——哪天你落难了，想起这世上有一处地方，有个东西好好站着——你就暖和了。」",options:[{label:"「这话我记一辈子。」",end:!0,effect:{stat:{wuxing:1},trait:{tong:1},ledger:{type:"恩",text:"在药王庙听老妇讲守一块无字碑的道理，助守一日"},text_after:"你帮着擦完了。手上的灰蹭了一袖子，心里却出奇地熨帖。老妇看着擦亮的一块无字碑，半天说了句：「行了，今天这一遍，值。」你走出很远才咂摸出味儿来——他谢的不是你，是它今天又被人认真对待了一回。"}},{label:"「您自己守着就好。」",end:!0,effect:{stat:{wuxing:1},text_after:"老妇也不勉强：「记不记随你。这话搁在这儿，你哪天想起来了，就算我托到了。」你告辞出来，走出一段，那句话还是跟上了你——物在人守。你说不上来哪里被它戳中了。"}}]}]},adv_g042_chuanyi:{id:"adv_g042_chuanyi",title:"老汉在山谷药田把手艺往下传",mother:"M3",channel:"T1",rarity:1,entry:{node:"bc_yaotian",chance:.07},stages:[{xinglu:"是岁山谷药田逢老汉。老汉的话糙，理却直——「我这一双手是从师父手上接来的，得接着往下递。」",text:"老汉正用一架自制的旧织机示范，做坏了，当着徒弟的面拆了重来：「错不藏——藏了错，就传了错。」老汉教你认一架自制的旧织机的门道：「你看这儿，磨了三十年才有的包浆。手艺也一样——急不来的东西，才立得住。」老汉忽然把一架自制的旧织机递过来：「来，上手试试？」",options:[{label:"「说实话——这是真功夫。」",goto:1,effect:void 0},{label:"「学这个能挣几个钱？」",end:!0,effect:{stat:{wuxing:1},text_after:"你没搭理就走了。老汉也没留你，只在你背后继续教徒弟。可那句「错不藏」追了你半条街——你想起自己上回做错事推了个干净，脚步忽然就沉了。"}}]},{xinglu:"是岁山谷药田一课。老汉把话说到根上——「传艺如点灯——你点了我，我点他，火就一直亮。」",text:"「手艺里最难的，不是教会的，是教不会的。」老汉看着你，「你听我讲讲教不会的那部分。」「成器的那个，如今在外头独当一面；走了样的那三个，拿了手艺去糊弄人。」老汉说，「我记牢的是骂我最狠的那个——他嫌我严，走了。前年他回来磕头，说在外头吃了不懂规矩的亏。我没怪他——他这一圈弯路，就是他没听完的课。」「我这一架自制的旧织机，早晚传给肯下苦功的人。」老汉望着作坊，「也许是我徒弟，也许是徒弟的徒弟，也许——是个今天来歇脚的路人。缘分这东西说不准。」",options:[{label:"「这句话，我带走了。」",end:!0,effect:{stat:{wuxing:1},trait:{zhi:1},ledger:{type:"恩",text:"帮老汉校对手抄册子，替一门手艺把住传承"},text_after:"「实话说得好听。」老汉满意地笑了，「就冲你这句实话，我把关子揭了——这一架自制的旧织机是这个形，是因为它得让用的人先低头。你低头了，心就沉了；心沉了，活就稳了。器物教人，比人教人快。」"}},{label:"「手艺早晚要绝。」",end:!0,effect:{stat:{wuxing:1},text_after:"「道理是会讲。」老汉不恼，「可我讲了三十年，徒弟们信了——你嘴上不信，眼睛信了。你进来到现在，眼睛没离开过它三回。」你哑口无言。他笑着送你出门：「不信没关系，手艺等得起。它等你一辈子，我都等得起。」"}}]}]},adv_g043_haiyuan:{id:"adv_g043_haiyuan",title:"试毒巷的一课：老汉替故人还愿",mother:"M4",channel:"T2",rarity:2,entry:{node:"bc_shidu",chance:.11},stages:[{xinglu:"是岁试毒巷逢老汉。老汉的话糙，理却直——「愿这个东西，许的时候轻飘飘，还的时候千斤重。」",text:"试毒巷里，老汉捧着一把没磨完的刀出神——你一问，他说这是故人留下的。「这是我欠他的。」老汉说，「当年他有难处，我没能帮上。如今他走了，我把他的愿当我的债——债这东西，躲一辈子，不如还一趟。」「你给评评理。」老汉把一把没磨完的刀递过来，「我这愿，还到这一步，算不算尽到心了？」",options:[{label:"「我捎您一段。」",goto:1,effect:void 0},{label:"「故人的东西，留着何用。」",end:!0,effect:{stat:{wuxing:1},text_after:"「何必？」老汉站住了，回头看你，「你也有一天会走。你走的时候，愿没还完的滋味，你尝过才知道。我劝你一句——趁身边人都在，把该说的话说了，该办的事办了。别像我，净走夜路。」他走了，你的脚步比来时重。"}}]},{xinglu:"是岁试毒巷一课。老汉把话说到根上——「故人最大的悲哀不是死——是心愿烂在没人知道的地方。」",text:"「你还愿还出过蹊跷事没有？」老汉忽然问你，「我遇到过一回——你说邪门不邪门。」「蹊跷事是这样的：那年到地方，收信的人家早搬了。」老汉说，「我打听三个月，问遍十里八乡——就在我要走的前一天，一个后生找上门：我是他孙子，爷爷临终说，会有人送东西来。」老汉摊开手，「你说，愿认路，还是我认路？我不知道。我只知道，愿不能停在半道。」老汉重新收拾好行囊：「客人的话我记下了。愿还得接着赶路——它等不起，我也不能老。」他冲你拱手，「你若哪天也遇上该还的愿——别拖。拖，是还愿这行唯一的死敌。」",options:[{label:"「我记住了。」",end:!0,effect:{stat:{wuxing:2},trait:{tong:1},ledger:{type:"恩",text:"受老汉所托记下善缘，替走了的人结一个活缘"},text_after:"你帮着辨出了那页纸上的字——缺的那一角，是收信人的名字。老汉盯着那个名字看了许久：「对上了。就差这个字，我在县里翻了三天的户籍。」他抬头时眼眶红了，「客人，你今天不是帮我看字——你是替他把最后一句话，送到了门口。」"}},{label:"「这故事听着累。」",end:!0,effect:{stat:{wuxing:1},text_after:"「完了就完了？」老汉站定，认真看你，「人走茶凉是世道。可我把茶端热的这些年，凉不了——你信不信？你今天说这话，是因为还没遇着走的人。遇着了，你会想起我。」他走了，那句话你揣了一路，越揣越沉。"}}]}]},adv_g044_zengxing:{id:"adv_g044_zengxing",title:"采药人客栈的一课：清瘦老者白送路上的东西",mother:"M1",channel:"T3",rarity:1,entry:{node:"bc_kezhan",chance:.1},stages:[{xinglu:"是岁采药人客栈逢清瘦老者。清瘦老者的话糙，理却直——「善不留名不是清高——是留了名，来的人就不好意思拿了。」",text:"清瘦老者守着一串挂在树上的旧草鞋打盹，木牌上的字被风雨磨得快看不清了，他还是每天来摆。「别多想，不是施舍。」清瘦老者把东西推给你，「施舍是人上人下，我这个是递手——你渴了，我这里正好有。就这么简单。」「你给我评评，」清瘦老者指着木牌，「这两个字哪个当头好——『自取』还是『共济』？我想了半年了。」",options:[{label:"「我取一份，谢谢。」",goto:1,effect:void 0},{label:"「天下哪有白给的好事。」",end:!0,effect:{stat:{wuxing:1},text_after:"「收买人心？」清瘦老者愣了一下，随即苦笑，「我要能收买人心，先把我自己这颗买服帖——它总嫌我瞎折腾。」他把东西收回，也不恼，「客人防着点也好。可你记住：天下收买人心的，都要你报答；我什么都不要——你要是连不要报答的都不敢信，这世道可就真没救了。」他这话说得平静，你却走得脸热。"}}]},{xinglu:"是岁采药人客栈一课。清瘦老者把话说到根上——「我一辈子的买卖：本钱是自己出的，利息是天下人的。」",text:"「有一年冬天，来了个贼。」清瘦老者说起这事，倒像说旁人。「起头真是给自己备的。」清瘦老者坦白道，「那年我落魄，怕自己哪天走投无路，就先备着——备着备着，先被人用了。用的人跟我说谢，我脸上臊——原来我备下的东西，早有人比我更需要。从那天起，这就不是我的退路了，是路上的公物。」「记住这条道的规矩。」清瘦老者指指一串挂在树上的旧草鞋，「用的时候想着点别人，够用的就别多拿——这不是我的规矩，是路自己的规矩。守住了，这东西就一直有。」",options:[{label:"「东西我收了，情我记了。」",end:!0,effect:{stat:{wuxing:2},trait:{xin:1},ledger:{type:"义",text:"帮清瘦老者记了一日赠账，见一条道的人心"},text_after:"「我可没说一定是我。」你摆手。清瘦老者笑道：「兴许不是。可你今天多站了这半晌——比别人近了一步。这摊子挑人，跟守物挑人一样：挑肯停脚的。」你走出几里地回头望，他还坐在一串挂在树上的旧草鞋边——像路长出来的一部分。"}},{label:"「别拿这些哄我。」",end:!0,effect:{stat:{wuxing:1},text_after:"「改变不了。」清瘦老者居然点头，「我一天也就喂饱几十个人，天下人多着呢。可你倒过来算——要是人人都觉得改不了，那就真改不了了。我摆一天，就有一天不是那样。这道理笨，可它管用。」你出门时他还坐着，晨光落在他身上，那一串挂在树上的旧草鞋像一方小小的印，盖在漫长的路上。"}}]}]},adv_g045_shouye:{id:"adv_g045_shouye",title:"澳港码头来了个夜里替人醒着的老人",mother:"M2",channel:"T1",rarity:2,entry:{node:"cl_aogang",chance:.06},stages:[{xinglu:"是岁澳港码头逢老人。老人的话糙，理却直——「我守的不是这一夜——我守的是「夜里有个人」这个念想。」",text:"澳港码头的夜里只有老人醒着——他给你指了宿处，又提着一段堤坝的巡查路巡回去了。「夜里赶路的，十个里有三个心里揣着事。」老人给你照着亮，「我不问你什么事——我就把你送到亮处。人到了亮处，事就小了一半。」「夜里的事，你遇上过么？」老人问你，「遇上过就知道我这盏灯的用处了。」",options:[{label:"「我给您留意。」",goto:1,effect:void 0},{label:"「半夜不睡，有病吧。」",end:!0,effect:{stat:{wuxing:1},text_after:"「出息？」老人笑了，「我这行没出息——没出息到二十年没人抢。可你想想，谁夜里敢不睡？不是我不想睡，是澳港码头几百户人拿觉换了我的不睡。」他敲了敲一段堤坝的巡查路，「出息这东西，白天论的。夜里的账，另算。」你将信将疑地走了。后来你在异乡的夜里病倒，是个守夜的老人照看了你——那一刻你想起这句话，眼睛忽然就热了。"}}]},{xinglu:"是岁澳港码头一课。老人把话说到根上——「夜里的灯为什么少？因为人都在睡——总得有人替睡的人醒着。」",text:"「有个人在我这儿守过一夜，后来当了官。」老人笑了，「他还记得我，你信不信？」「夜里的事，是病人、是醉汉、是走投无路的人。」老人一样样数给你听，「产妇半夜要生，是我跑去接的稳婆；醉汉躺在冰边上，是我拖回来的；还有个后生想跳河——我在河边陪他坐到天亮，一句话没劝，他就自己回去了。」老人叹口气，「白天的人都以为夜里干净。夜里最不干净——夜里的难处，都是白天咽下去的。」「你走吧，天亮了路好走。」老人收了灯，「夜里的事你记着一半就行——另一半，是留给夜里的人的。」",options:[{label:"「这一夜，谢过了。」",end:!0,effect:{stat:{wuxing:1},trait:{xin:1},ledger:{type:"恩",text:"为老人递了一句生面孔的话，替澳港码头夜里防了一手"},text_after:"灯熄了，天亮了。你走出澳港码头很远，回头看不见灯，可你知道它在——就像你知道这世上有一群人，一辈子活在别人的梦里，为的是别人的梦别变成噩梦。你朝着澳港码头的方向作了个揖。天光大亮，路上人多了，谁也不知道你这一揖揖的是什么。"}},{label:"「守夜能守出什么名堂。」",end:!0,effect:{stat:{wuxing:1},text_after:"「运气？」老人指指自己的眼睛，「我这双眼二十年没睡过一个整觉——澳港码头每一块松动的石头、每一个白天咽下事的夜行人、每一处该修没人修的堤口，都在我这儿记着。运气是留给没准备的。你说是运气就运气——反正鸡叫的时候，人人都囫囵着，这就够了。」"}}]}]},adv_g046_shiyi:{id:"adv_g046_shiyi",title:"鱼市来了个替失物寻主人的少年",mother:"M6",channel:"T2",rarity:2,entry:{node:"cl_yushi",chance:.08},stages:[{xinglu:"是岁鱼市逢少年。少年的话糙，理却直——「我这一行没有大买卖——都是小东西，可小东西连着大心事。」",text:"鱼市里，少年守着一屋一船漂来的遗物，见你进来，先问一句：「客人丢过什么？」「我这册子记了二十年。」少年翻着一船漂来的遗物边的旧簿，「每件失物什么样子、哪儿捡的、像是谁丢的——都记着。册子比我的脑子靠得住。人的记忆会骗人，字不会。」「客人有闲功夫没有？」少年半开玩笑，「搭把手，帮我给这箱子归归类。你归过的，我记下——算你在这行挂个号。」",options:[{label:"「我帮你认认。」",goto:1,effect:void 0},{label:"「这行当，没出息。」",end:!0,effect:{stat:{wuxing:1},text_after:"「没出息。」少年笑了，「对——没出息，饿不死，也发不了。可你告诉我，什么行当能让人二十年睡得着觉？我这行能。我每送回一件东西，就有一户人家少一夜的睡不着。」他拱拱手，「出息是活给别人看的，觉是自己睡的。慢走。」"}}]},{xinglu:"是岁鱼市一课。少年把话说到根上——「遗落的东西不会说话——可它们都在等人。」",text:"「拾遗这行，也有发懵的时候。」少年说，「讲一件，你听听值不值。」「师父传我的话是：物有主，主有心，心有急缓。」少年说，「收东西的法子三天就会，辨人心的功夫十年难成。丢了药方的人和丢了银子的，急法不一样；丢东西的穷人和丢东西的富人，找法也不一样。这行当的功夫，全在听人说丢东西那几句话里。」「东西你拿走一件。」少年忽然说，「不是送你——是托你。你走到别处，替它问问它的主人。我守在这儿出不去，你的腿比我的长。」",options:[{label:"「两句话，我记牢了。」",end:!0,effect:{stat:{wuxing:1},trait:{tong:1},ledger:{type:"义",text:"在鱼市学了两句话：丢了先想它在谁手里，捡了先想它归谁"},text_after:"你帮着把那箱旧信按笔迹归了类——竟分出七户不同的人家。少年眼睛都亮了：「七年了，头一回有人帮我拆这个死结。这七户人家，我挨家去送——送完一户，我就少守一件。」他非要塞给你一枚旧铜钱作谢：「失物账上添你一笔——这行的规矩，帮过忙的，都是祖师爷的人。」"}},{label:"「替人守物，自己吃什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"「拾不过来。」少年坦白得很，「天下的失物，我一辈子拾不完。可我多拾一件，世上就少一件没着落的。你这话跟师父当年说的一模一样——他后来呢？他拾了一辈子。」他拿起册子，「拾不过来，就一件一件来。日子长着呢。」"}}]}]},adv_g047_wenlu:{id:"adv_g047_wenlu",title:"海神庙来了个只问不答的少年",mother:"M7",channel:"T3",rarity:1,entry:{node:"cl_haishenmiao",chance:.09},stages:[{xinglu:"是岁海神庙逢少年。少年的话糙，理却直——「问题挂在这儿，不急着答——有些问题本身就是灯。」",text:"少年正把新写的问题挂上一张折了又折的路引：「客人看看，这个问题值得挂么？」「我年轻时最烦人提问。」少年笑了，「后来自己开了店——才发现，肯问你的人才拿你当回事。不问的人，早就把你算计好了。问，是信。」「留个问题给你。」少年说着要往你手里塞纸条，「不白留——哪天你想通了，回来告诉一声。这店里的规矩：问题不白送，得还利息。」",options:[{label:"「不蠢，问得好。」",goto:1,effect:void 0},{label:"「你到底答不答。」",end:!0,effect:{stat:{wuxing:1},text_after:"「怪人就怪人。」少年笑呵呵的，「海神庙人人都这么叫。可你也看见了——他们路过还是要看一眼我那牌子。为什么？怪话里头，偶尔藏着正经。人不能全信怪人，可也不能一个怪人都不信——全信了傻，全不信了苦。你自己掂量。」他冲你摆摆手，继续挂他的问题。"}}]},{xinglu:"是岁海神庙一课。少年把话说到根上——「我不教人——我提问题，路让人自己走。」",text:"「我最得意的一个问题，」少年压低了声音，「救过一个人。」「救过人的那个问题，是这样：」少年说，「有个后生来问路，话里话外透着不想活。我没劝——劝是最没用的。我就问他：你打算把这一身本事还给谁？他愣了。我说，你娘把你养这么大，你这一手好木匠活，是跟她学的还是自己学的？他哭了。哭完回去接着做木匠。后来他徒弟满天下——你说我那个问题值多少钱？」少年摆摆手，「不值钱。可它会勾人——勾着勾着，人就把自己勾回来了。」「我这一张折了又折的路引上的问题，谁都可以摘。」少年说，「摘走的记得回来还——还的不是纸条，是你自己酿的答案。利息不高，一辈子还一回就行。」",options:[{label:"「先生二字，您当得起。」",end:!0,effect:{stat:{wuxing:1},trait:{zhi:1},ledger:{type:"义",text:"在少年店里吵了一架，各自往前挪了半步"},text_after:"「看，还是觉得——这一句你带走了。」少年满意地送你出门。后来你在生意上、恩怨里、抉择前，无数次问自己这一句。它不能替你做对的事——可它让你少做了许多自以为对的事。你从此逢人便传这句话，传的时候都说是从一个怪老头那儿听来的。"}},{label:"「问题再好，不顶饭吃。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不顶饭吃？」少年不急不恼，「饭是吃的，问题是活的。光吃饭不想事的人，跟牲口拉磨一个样——磨转得再快，路一寸没走。我不是笑话你——我五十岁之前也是这么活的。」他拍拍一张折了又折的路引，「后来才明白：问，是人跟牲口隔的那一道。」"}}]}]},adv_g048_jizhang:{id:"adv_g048_jizhang",title:"路遇中年汉子——在船坞替人情记着账",mother:"M8",channel:"T1",rarity:1,entry:{node:"cl_chuanwu",chance:.09},stages:[{xinglu:"是岁船坞逢中年汉子。中年汉子的话糙，理却直——「情分这东西，不记账就散——散了再聚，就生分了。」",text:"船坞里，中年汉子守着一册人人信服的老账本，谁家有笔说不清的旧账，都来问他。「记账三十年，我笔底下没错过一文。」中年汉子说，「不是我算术好——是我每笔记两遍、念一遍、过三天再核一遍。账这东西，错一笔，一街的信就塌了。」中年汉子打量你一番：「客人面生——有没有旧账落在我这儿？有的话，报个名姓，我一翻便知。」",options:[{label:"「报个名姓，帮我翻翻。」",goto:1,effect:void 0},{label:"「人情账，记它做什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"「你不欠谁的——好啊。」中年汉子忽然笑得眼睛弯起来，「这话我就给你记上：某年某月某日，有位客人说，他不欠谁的。这一笔怎么用呢——你哪天受了人的恩，想起这笔账，就得掂量掂量：真不欠，还是不肯欠？不肯欠的人多，不欠的少。」他冲你举举茶碗，「客人，别恼。账记上了，就等你哪天来改。」"}}]},{xinglu:"是岁船坞一课。中年汉子把话说到根上——「别人记账怕错——我记账怕漏。错了改得回来，漏了就真没了。」",text:"「你见过两家人为一笔账断了二十年的来往么？」中年汉子说，「我接手过。」「烧账的事，是大饥那年。」中年汉子说，「富户囤粮抬价，我这账上记着他们家欠下的十七户人情——都是灾年穷人帮过他们先人的。他们怕我这张账掀老底，半夜送来一箱金子，让我把那页烧了。」中年汉子冷冷道，「我把金子退了，账抄了三份：一份我收着，一份藏在庙里，一份连夜送到那十七户人手里。后来饥年过完，那富户的粮，被十七户人凭一页旧账联名告发了。官府问：谁记的账？——没人说。账在，就够了。」中年汉子把茶续满：「别急着走。听账人的道理，不在账上——在你听完以后，回头看你自家那本账。人人心里都有一本，只是没人替你誊清。」",options:[{label:"「这句话，我带走了。」",end:!0,effect:{stat:{wuxing:1},trait:{wen:1},ledger:{type:"恩",text:"帮中年汉子誊账一页，字正心平，得了保管员三分真传"},text_after:"你替他跑了一趟，把一册抄本送到了邻县。收账的是个白胡子老者，翻开一看就红了眼：「还有人记着这笔……」你回程时中年汉子已在门口候着——他不要你讲细节，只问了一句：「送到就行了？」你说送到了。他长出一口气：「好。这一笔，两头都活了。」"}},{label:"「账本又不是靠山。」",end:!0,effect:{stat:{wuxing:1},text_after:"「靠山？」中年汉子把账本举起来，「靠山会倒，靠人会跑，靠钱会花完——靠账呢？账是死的，可它记得的事是活的。你走投无路那天，敲开一户人家的门，报上名姓，人家翻出账本：『你家当年救济过我们……』——你说这不是靠山，什么才是？我这柜子，是几千户人的老底。」"}}]}]},adv_g049_shouwu:{id:"adv_g049_shouwu",title:"番商货栈里守着一件旧物的中年汉子",mother:"M5",channel:"T2",rarity:3,entry:{node:"cl_huozhan",chance:.08},stages:[{xinglu:"是岁番商货栈逢中年汉子。中年汉子的话糙，理却直——「我陪它一辈子，它记我一辈子，两清。」",text:"番商货栈的角落里，中年汉子守着一杆褪色的大旗，守得像守着一户人家。「当年交给我的时候说，守到守不动为止。」中年汉子摩挲着一杆褪色的大旗，「我算了算，还早。我还能守——它也还站得住。」中年汉子从怀里摸出个小本子：「守物的账。你帮我记一笔——今天有人来看过它。这一笔，比我给你什么都强。」",options:[{label:"坐下陪中年汉子说说话",goto:1,effect:void 0},{label:"「破烂一个，守它做什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"你绕着走了。走出去老远，风里飘来一句话似的调子——中年汉子在给一杆褪色的大旗哼曲儿。你忽然明白：人家守得高兴，根本不在乎你看不看。这么一想，你的脚步倒轻快了。"}}]},{xinglu:"是岁番商货栈一课。中年汉子把话说到根上——「守到后来，分不清是我守它，还是它守我。」",text:"「最难的不是守，是没人懂。」中年汉子笑笑，「懂的人不来，来的人不懂——守着守着就只剩你一个人了。」「我算过账。」中年汉子扳着指头，「守它这些年，花的钱、挨的骂、误的工——全是赔的。可谁家孩子路过这儿喊一声『这东西还在啊』——这一声，全赚回来了。」「守物人不说谢。」中年汉子说，「你要真帮了它，它自己会谢你——哪天你落难了，想起这世上有一处地方，有个东西好好站着——你就暖和了。」",options:[{label:"「这条规矩，我带走。」",end:!0,effect:{stat:{wuxing:1},trait:{tong:1},ledger:{type:"恩",text:"受中年汉子所托，允诺路过时看顾一杆褪色的大旗"},text_after:"你把来处和去处都念了。念完中年汉子笑得眼睛眯成一条缝：「好了，你们认识了。往后你不管走多远，它都算你认识的东西——人这辈子，认识的东西多了，心里就宽。」"}},{label:"「往后再说吧。」",end:!0,effect:{stat:{wuxing:1},text_after:"「记性不好的人，」中年汉子笑了，「就看一眼。眼睛比脑子诚实——看过的东西，忘不掉的。」你回头看了一杆褪色的大旗一眼。就这一眼，你知道他说得对。"}}]}]},adv_g050_chuanyi:{id:"adv_g050_chuanyi",title:"路遇驼背阿婆——在灯塔崖把手艺往下传",mother:"M3",channel:"T3",rarity:3,entry:{node:"cl_dengtaya",chance:.07},stages:[{xinglu:"是岁灯塔崖逢驼背阿婆。驼背阿婆的话糙，理却直——「徒弟学不学得会看天分，教不教得会看良心。」",text:"驼背阿婆见了你，先把手上的活做完才抬头：「客人别笑话，手艺人的规矩，做不完的活不抬头。」「我教徒弟，头一年不让碰一副传了三代的药戥。」驼背阿婆笑，「先看、先磨性子。心浮的人拿家伙什，糟蹋东西，也糟蹋自己。」「你要是感兴趣，我讲细点。」驼背阿婆说，「讲了你就懂——懂了的人，走到哪儿都替这门手艺说句话。」",options:[{label:"「这手艺，能传多久？」",goto:1,effect:void 0},{label:"「学这个能挣几个钱？」",end:!0,effect:{stat:{wuxing:1},text_after:"「过时了？」驼背阿婆不急不恼，「老规矩过不过时，不看年头，看它护不护人。你哪天吃了没规矩的亏，自然会想起今天这话。」你嘴上应着，心里不服。三年后你真吃了那亏——想起这话时，人在异乡，败得一塌糊涂。"}}]},{xinglu:"是岁灯塔崖一课。驼背阿婆把话说到根上——「手艺不传，人就白活一遭。」",text:"驼背阿婆做完了活，泡了壶茶，话头就长了：「说起传艺，我有一肚子话。」「我师父『饿死』的说法是这样的：」驼背阿婆慢慢道，「他把手艺全教给我，自己接的活越来越少。有人笑他傻。他说：徒弟活得好，就是我的老有所养——这比攒银子牢靠。后来他走的时候，来送的全是他教出来的徒弟的徒弟。你说，他饿死了吗？」驼背阿婆把一副传了三代的药戥放回原位，郑重其事：「手艺人就说手艺人的话。你今天听的多，能带走一句就够——做什么都行，把手上的活当人看。」",options:[{label:"「谢先生一课。」",end:!0,effect:{stat:{wuxing:2},trait:{tong:1},ledger:{type:"义",text:"在灯塔崖亲手学做驼背阿婆的活，得「敢露怯」之教"},text_after:"「实话说得好听。」驼背阿婆满意地笑了，「就冲你这句实话，我把关子揭了——这一副传了三代的药戥是这个形，是因为它得让用的人先低头。你低头了，心就沉了；心沉了，活就稳了。器物教人，比人教人快。」"}},{label:"「道理谁都会讲。」",end:!0,effect:{stat:{wuxing:1},text_after:"「要绝就绝。」驼背阿婆淡淡地说，「手艺绝不绝，不看我这代人喊多响——看下代人肯不肯弯腰。我弯了三十年腰了，够了。绝了也不冤：它来的时候有人敬，走的时候有人送，全始全终。」你出门时回头看了一眼，驼背阿婆已经又坐回一副传了三代的药戥前——绝不绝的话撂在那儿，手上的活一天没停。"}}]}]},adv_g051_haiyuan:{id:"adv_g051_haiyuan",title:"路遇少年——在剑山道替故人还愿",mother:"M4",channel:"T1",rarity:1,entry:{node:"kw_jianshan",chance:.13},stages:[{xinglu:"是岁剑山道逢少年。少年的话糙，理却直——「故人把愿留给我，是拿我当自己人——这份信，比愿本身重。」",text:"少年把一袋没撒进河里的花籽护在怀里避雨——护得比自己的性命还紧。「我跟他打了一辈子交道，就欠这一件。」少年把一袋没撒进河里的花籽翻过来给你看，「你看这磨痕——都是他亲手磨的。他磨的时候念的什么，我大概知道。所以这愿，我认。」少年看着你：「你说，人走了以后，到底知不知道我们还在替他办事？」不等答，他自己接了：「知不知道都要办——这是我的事，不是他的事。」",options:[{label:"「帮您辨认这页纸。」",goto:1,effect:void 0},{label:"「与我无关，让让。」",end:!0,effect:{stat:{wuxing:1},text_after:"「留着何用？」少年把一袋没撒进河里的花籽举起来给你看，「你看它像东西吗？不像了——它是一句没说完的话。话没了，人才真的没了。」他说完自己收好，朝你拱拱手，「客人，话糙了。可这理，你早晚用得上。」"}}]},{xinglu:"是岁剑山道一课。少年把话说到根上——「愿这个东西，许的时候轻飘飘，还的时候千斤重。」",text:"「我老婆子生前总念叨，」少年声音软下来，「这个愿，是为她还的。」「庙里管不着这个愿。」少年摆摆手，「菩萨收的是香火，我老婆子要的不是香火——她说想再看一眼当年我们的花田。花田早荒了。我这两万里，就是要把她撒剩的这袋花籽，撒回去。」少年顿了顿，「我不求花开——求个撒了。撒了，我就能跟她交账了。」少年把一小撮路上的干粮分给你：「同行一程，就是有缘。这个你拿着——路上的人情，也是愿的一部分。我替故人结的善缘，多一个是一个。」",options:[{label:"「这碗水，我记着。」",end:!0,effect:{stat:{wuxing:2},trait:{tong:1},ledger:{type:"恩",text:"为少年的故人之愿指了路，了却半桩心愿"},text_after:"你帮着辨出了那页纸上的字——缺的那一角，是收信人的名字。少年盯着那个名字看了许久：「对上了。就差这个字，我在县里翻了三天的户籍。」他抬头时眼眶红了，「客人，你今天不是帮我看字——你是替他把最后一句话，送到了门口。」"}},{label:"「快些走吧，别误了我赶路。」",end:!0,effect:{stat:{wuxing:1},text_after:"「完了就完了？」少年站定，认真看你，「人走茶凉是世道。可我把茶端热的这些年，凉不了——你信不信？你今天说这话，是因为还没遇着走的人。遇着了，你会想起我。」他走了，那句话你揣了一路，越揣越沉。"}}]}]},adv_g052_zengxing:{id:"adv_g052_zengxing",title:"婆婆在剑炉街白送路上的东西",mother:"M1",channel:"T2",rarity:3,entry:{node:"kw_jianlu",chance:.05},stages:[{xinglu:"是岁剑炉街逢婆婆。婆婆的话糙，理却直——「路边这点东西救不了命——可有时人就差这一口。」",text:"剑炉街人人都认得婆婆和他那一垛谁都可取的干草——你初来乍到，也被他拦下了。「别多想，不是施舍。」婆婆把东西推给你，「施舍是人上人下，我这个是递手——你渴了，我这里正好有。就这么简单。」「你给我评评，」婆婆指着木牌，「这两个字哪个当头好——『自取』还是『共济』？我想了半年了。」",options:[{label:"「我来记这一笔。」",goto:1,effect:void 0},{label:"「白拿的东西，来路不正。」",end:!0,effect:{stat:{wuxing:1},text_after:"「收买人心？」婆婆愣了一下，随即苦笑，「我要能收买人心，先把我自己这颗买服帖——它总嫌我瞎折腾。」他把东西收回，也不恼，「客人防着点也好。可你记住：天下收买人心的，都要你报答；我什么都不要——你要是连不要报答的都不敢信，这世道可就真没救了。」他这话说得平静，你却走得脸热。"}}]},{xinglu:"是岁剑炉街一课。婆婆把话说到根上——「东西有价，搭把手没价。」",text:"「我最得意的不是这一垛谁都可取的干草。」婆婆朝远处一指，「是那边——你看见没有？」「贼的事后来还有下文。」婆婆说，「那放柴的汉子，如今每年冬天帮我补牌换绳——他说他当年走投无路，是砸牌子那一晚看见『夜路慢行』四个字，坐在地上哭了半夜。第二天天亮他就不偷了。」婆婆拍拍新牌子，「一块破木头，救了两个人——我一个，他一个。」婆婆朝你挥挥手：「走吧走吧。东西拿了，话也听了——往后你也是个路上的人了。路上的人认路上的人，一眼就认得。」",options:[{label:"「规矩我守住了。」",end:!0,effect:{stat:{wuxing:1},trait:{zhi:1},ledger:{type:"恩",text:"受婆婆所托，允诺传递路边的规矩"},text_after:"「我可没说一定是我。」你摆手。婆婆笑道：「兴许不是。可你今天多站了这半晌——比别人近了一步。这摊子挑人，跟守物挑人一样：挑肯停脚的。」你走出几里地回头望，他还坐在一垛谁都可取的干草边——像路长出来的一部分。"}},{label:"「世道就这样，你改变不了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不算上你。」婆婆点头，「我的账是我的。可你走在这条道上，喝过路边的井水、走过别人修的桥、睡过别人盖的亭子——这些账都跟我一样，没人跟你要过。」他拍拍一垛谁都可取的干草，「不用你算我的账。哪天你想起这世道不全是黑的，就够了。」"}}]}]},adv_g053_shouye:{id:"adv_g053_shouye",title:"路遇妇人——在矿石市夜里替人醒着",mother:"M2",channel:"T3",rarity:1,entry:{node:"kw_kuangshi",chance:.06},stages:[{xinglu:"是岁矿石市逢妇人。妇人的话糙，理却直——「守一夜容易，守一年也不难——难的是守着守着，把别人的夜当成自己的夜。」",text:"你被妇人的梆子声唤醒——「三更了，无事。睡吧。」他巡过你的窗，脚步又轻又稳。「夜里赶路的，十个里有三个心里揣着事。」妇人给你照着亮，「我不问你什么事——我就把你送到亮处。人到了亮处，事就小了一半。」「往前头去有段黑路。」妇人把灯举高了些，「我送你过——反正我也要巡到那边。」",options:[{label:"「劳驾送一程。」",goto:1,effect:void 0},{label:"「守夜的能有什么出息。」",end:!0,effect:{stat:{wuxing:1},text_after:"「认得黑路是好事。」妇人没拦你，「可你认得的是路——路认不认你，两说。去年有个自认得路的，掉进了拆了半截的桥坑里，躺了一夜——他不知道那坑，我知道。」他举灯照了照那个方向，「喏，就那儿。坑还在，天亮我得上报。」你没再犟，跟着他走了那条亮路。"}}]},{xinglu:"是岁矿石市一课。妇人把话说到根上——「白天人挤人，夜里心贴心——夜里肯应你一声的，都是家里人。」",text:"「白天的官府管不了的，夜里都得有人管。」妇人说，「你猜夜里都有什么事？」「当官的那位，姓陈。」妇人说，「那年他赶考，盘缠被偷了，蹲在一窑点火的老窑边上哭。我陪他坐了一夜，把攒的几吊钱塞给他——我婆娘还跟我吵了一架。后来他中了，回来找我，要给我修房子。我说不用——你记住这一夜就行：往后你坐堂，遇上夜里犯的事，先问问人家为什么夜里走这条路。」妇人说，「他真照做了。去年他断了一桩案子——贼是贼，可贼的娘病着。他判了贼，也治了他娘的病。你说我这几吊钱，值不值？」「我这班，还守得动十年。」妇人活动着腿脚，「十年后谁接？我挑着呢。你若哪天走投无路——来找我。守夜人缺人手，也缺心里有夜的人。」",options:[{label:"「保我十年太平。」",end:!0,effect:{stat:{wuxing:2},trait:{dan:1},ledger:{type:"义",text:"为妇人递了一句生面孔的话，替矿石市夜里防了一手"},text_after:"天亮了。你按妇人教的走了那条新路——果然避开了塌方段。回头望，妇人已经收了灯，正往回走。他的背影在晨光里瘦得像根梆子，可你觉得，这一夜矿石市的太平，全是这根梆子敲出来的。"}},{label:"「你这灯，照不了多远。」",end:!0,effect:{stat:{wuxing:1},text_after:"「运气？」妇人指指自己的眼睛，「我这双眼二十年没睡过一个整觉——矿石市每一块松动的石头、每一个白天咽下事的夜行人、每一处该修没人修的堤口，都在我这儿记着。运气是留给没准备的。你说是运气就运气——反正鸡叫的时候，人人都囫囵着，这就够了。」"}}]}]},adv_g054_shiyi:{id:"adv_g054_shiyi",title:"铸剑世家工坊的一课：婆婆替失物寻主人",mother:"M6",channel:"T1",rarity:2,entry:{node:"kw_gongfang",chance:.07},stages:[{xinglu:"是岁铸剑世家工坊逢婆婆。婆婆的话糙，理却直——「每件遗物背后都站着一个着急的人——我急他所急。」",text:"你到铸剑世家工坊时，婆婆正对着一面牌子出神——牌上写着：「失物招领，三年不领，代为寻主」。「有人笑我守着一堆破烂。」婆婆不恼，「我说你不懂——破烂搁在你家是破烂，搁在我这儿，是有主的。只等它的主人哪天想起来。人这一辈子，谁没落下过点什么？」「你眼神好。」婆婆招手，「帮我认认——这个包袱上的字，是哪府的写法？」",options:[{label:"「这故事有意思，讲讲。」",goto:1,effect:void 0},{label:"「失物还想着领？痴人。」",end:!0,effect:{stat:{wuxing:1},text_after:"「没出息。」婆婆笑了，「对——没出息，饿不死，也发不了。可你告诉我，什么行当能让人二十年睡得着觉？我这行能。我每送回一件东西，就有一户人家少一夜的睡不着。」他拱拱手，「出息是活给别人看的，觉是自己睡的。慢走。」"}}]},{xinglu:"是岁铸剑世家工坊一课。婆婆把话说到根上——「我这一行没有大买卖——都是小东西，可小东西连着大心事。」",text:"「有人在我这儿认走过三回东西的人。」婆婆摇头笑了，「你猜是丢三落四，还是别的？」「师父传我的话是：物有主，主有心，心有急缓。」婆婆说，「收东西的法子三天就会，辨人心的功夫十年难成。丢了药方的人和丢了银子的，急法不一样；丢东西的穷人和丢东西的富人，找法也不一样。这行当的功夫，全在听人说丢东西那几句话里。」婆婆把册子递给你看：「客人，失物账一页一页都在这儿。你帮不上不要紧——记住：往后你丢了东西，先想想它在谁手里；捡了东西，先想想它归谁。这两句话做到了，我这行就算白教了你。」",options:[{label:"「替您跑这一趟。」",end:!0,effect:{stat:{wuxing:1},trait:{wen:1},ledger:{type:"恩",text:"一眼认出包袱上的字迹，省了婆婆三个月的腿"},text_after:"你帮着把那箱旧信按笔迹归了类——竟分出七户不同的人家。婆婆眼睛都亮了：「七年了，头一回有人帮我拆这个死结。这七户人家，我挨家去送——送完一户，我就少守一件。」他非要塞给你一枚旧铜钱作谢：「失物账上添你一笔——这行的规矩，帮过忙的，都是祖师爷的人。」"}},{label:"「东西丢了再买就是。」",end:!0,effect:{stat:{wuxing:1},text_after:"「再买就是？」婆婆笑了，「钱能买回来的，都不叫失物。叫失物的，钱买不回来——亡人的东西、旧人的信、娃他娘缝的鞋。这些丢了，买一百件新的，心里那个窟窿还是圆不上。你年纪轻，还没到懂的时候——哪天懂了，别哭，来我这儿坐坐。」"}}]}]},adv_g055_wenlu:{id:"adv_g055_wenlu",title:"路遇妇人——在剑冢下院只问不答",mother:"M7",channel:"T2",rarity:1,entry:{node:"kw_jianzhong",chance:.06},stages:[{xinglu:"是岁剑冢下院逢妇人。妇人的话糙，理却直——「一个好问题，顶十个好答案。」",text:"妇人正把新写的问题挂上一张折了又折的路引：「客人看看，这个问题值得挂么？」「我这一张折了又折的路引上挂满了问句。」妇人指给你看，「有客人替我答的，有我自己想了三十年的。挂在这儿——路过的人看一眼，想一会儿，这一会儿，就值。」「客人走南闯北，见得多。」妇人凑近了些，「帮我评评，这个问题，问得蠢不蠢？」",options:[{label:"「您考我。」",goto:1,effect:void 0},{label:"「卖关子，无聊。」",end:!0,effect:{stat:{wuxing:1},text_after:"「我答？」妇人摊开手，「我要是答得上，还开店做什么？」他指指一张折了又折的路引，「你看这满墙的问题——我答上的不到十个。剩下的，都是别人答的、路教的、年头给的。我这不是卖关子——我是个替人传话的，传天地的、传岁月的、传你自己心里的。你急着要我答，就像问镜子要路——路在你脚下，不在镜子里。」"}}]},{xinglu:"是岁剑冢下院一课。妇人把话说到根上——「天下没有蠢问题，只有不肯问的人。」",text:"「有个问题，我自己答不上来。」妇人望着一张折了又折的路引，「挂了三十年。今天说给你听听。」「我师父哑，怎么教我问？」妇人说，「他用手指比划，写在沙地上。他写的第一个问句是：你今天看见了什么？我答：什么都看见了。他摇头，写：不——你看见的是你觉得的。这句话我琢磨了半辈子。到今天，我每天还问自己这一句。」妇人指指一张折了又折的路引，「这上头挂的头一个问题，就是他写的。」「我送你出门。」妇人边走边说，「记住——路上遇事，先别急着找答案。先问自己一句：这事我是在看，还是在觉得？这一句，顶你半生的学费。」",options:[{label:"「利息我必还。」",end:!0,effect:{stat:{wuxing:1},trait:{xin:1},ledger:{type:"恩",text:"在妇人店里吵了一架，各自往前挪了半步"},text_after:"「先生就是你自己的心。」你出门时回头看了一眼——妇人已经转回一张折了又折的路引前，又在写新问题了。你忽然明白这老头为什么从不给答案：答案是他给不起的——人人的路不一样。他给的是火折子，路得你自己摸黑走。可有了火折子，摸黑也走得直。"}},{label:"「我从不问路，只看脚下的。」",end:!0,effect:{stat:{wuxing:1},text_after:"「答案？」妇人把牌子转过来给你看——「只问不答」四个字钉得结结实实。「我这不给答案，跟药铺不卖病一个理：病在你身上，药方在你身上，我这儿只管帮你把脉。」他把门推开，「你要答案，满街都是——街边随便拉个人都能给你一个。可你要问句，就得自己来。你不来，是你的损失。」"}}]}]},adv_g056_jizhang:{id:"adv_g056_jizhang",title:"岛链渔村的一课：中年汉子替人情记着账",mother:"M8",channel:"T3",rarity:1,entry:{node:"qd_yucun",chance:.06},stages:[{xinglu:"是岁岛链渔村逢中年汉子。中年汉子的话糙，理却直——「账不怕欠——怕的是没人记。记着，就还有还的一天。」",text:"中年汉子的一匣子记着人情往来的木签在岛链渔村人人都信——你说不清它记了多少年，只知道比庙里的功德碑还灵。「记账三十年，我笔底下没错过一文。」中年汉子说，「不是我算术好——是我每笔记两遍、念一遍、过三天再核一遍。账这东西，错一笔，一街的信就塌了。」「帮我断个案子。」中年汉子把两个争执的人拉到一处，「他们都信你外乡人嘴严。」",options:[{label:"「这笔账，我也想记。」",goto:1,effect:void 0},{label:"「你这行当，多管闲事。」",end:!0,effect:{stat:{wuxing:1},text_after:"「你不欠谁的——好啊。」中年汉子忽然笑得眼睛弯起来，「这话我就给你记上：某年某月某日，有位客人说，他不欠谁的。这一笔怎么用呢——你哪天受了人的恩，想起这笔账，就得掂量掂量：真不欠，还是不肯欠？不肯欠的人多，不欠的少。」他冲你举举茶碗，「客人，别恼。账记上了，就等你哪天来改。」"}}]},{xinglu:"是岁岛链渔村一课。中年汉子把话说到根上——「记账人手上要清，心上要热——光清不热，是阎王；光热不清，是糊涂虫。」",text:"「账本上最沉的一页，」中年汉子翻出来给你看，「不是钱最多的那页。你认认这页上的字。」「烧账的事，是大饥那年。」中年汉子说，「富户囤粮抬价，我这账上记着他们家欠下的十七户人情——都是灾年穷人帮过他们先人的。他们怕我这张账掀老底，半夜送来一箱金子，让我把那页烧了。」中年汉子冷冷道，「我把金子退了，账抄了三份：一份我收着，一份藏在庙里，一份连夜送到那十七户人手里。后来饥年过完，那富户的粮，被十七户人凭一页旧账联名告发了。官府问：谁记的账？——没人说。账在，就够了。」中年汉子把茶续满：「别急着走。听账人的道理，不在账上——在你听完以后，回头看你自家那本账。人人心里都有一本，只是没人替你誊清。」",options:[{label:"「它开着门，我就放心。」",end:!0,effect:{stat:{wuxing:2},trait:{dan:1},ledger:{type:"恩",text:"替中年汉子送一册账抄本到邻县，一笔死账两头复活"},text_after:"你把那句话带走了。后来你受了人的恩，总会想起那笔「不欠谁的」的账——想起时脸就发热，热完了就认真去还。再后来你也学着记：谁帮过你、你欠过谁，一笔一笔记在心里。你还真把这些教给了你的孩子——账本没传下去，账理传下去了。"}},{label:"「记账记成痴，何苦。」",end:!0,effect:{stat:{wuxing:1},text_after:"「何苦？」中年汉子笑了，「我这一柜账，年年有人来对、来还、来谢——我苦什么？苦的是你们这些不记的：受了恩转脸就忘，欠了债装不知道——你以为你们轻省？你们那才是苦——账在心里烂着，夜夜硌得慌。我睡得着，就凭我这柜子。」"}}]}]},adv_g057_shouwu:{id:"adv_g057_shouwu",title:"岛主议会里守着一件旧物的婆婆",mother:"M5",channel:"T1",rarity:1,entry:{node:"qd_yihui",chance:.09},stages:[{xinglu:"是岁岛主议会逢婆婆。婆婆的话糙，理却直——「守的东西不值钱——守本身值钱。」",text:"婆婆见了你，头一句就是：「别嫌它旧。」说的是一块无字碑。「这东西看着孤，其实不孤。」婆婆指给你看，「它身上有几十年的手印。守它的人一代传一代，手印摞手印——它比谁的家底都厚。」「你眼神正。」婆婆端详你半天，「守东西这行，挑的就是眼神。你这样的，学会了走到哪儿都饿不死——心里有东西的人，饿不死。」",options:[{label:"「守了多久了？」",goto:1,effect:void 0},{label:"「这种闲事，与我何干。」",end:!0,effect:{stat:{wuxing:1},text_after:"婆婆没追出来。你走了几里地，越想越不对——人家守了几十年的东西，你一句「破烂」就打发了。回头补一句的时候，婆婆正围着一块无字碑忙，见了你也不提方才的事，只说：「回来了？搭把手。」你愣是没说出道歉的话——他已经把它翻篇了。"}}]},{xinglu:"是岁岛主议会一课。婆婆把话说到根上——「东西没了可以再造，守的规矩断了就接不上。」",text:"婆婆坐下来，给你讲了件旧事——讲完自己半天没言语。「师父留的那句话，我琢磨了二十年。」婆婆说，「他写的是：守到你觉得是它在守你，才算入门。我当时不懂——现在懂了。它站在这儿，我就不敢倒下。」婆婆站起身，最后擦了一遍一块无字碑：「天不早了。守物人的话就这么多——你要记，就记一句：物在人守。人要是都不守了，物就真没了。」",options:[{label:"「您守的哪里是物。」",end:!0,effect:{stat:{wuxing:1},trait:{wen:1},ledger:{type:"义",text:"在岛主议会听婆婆讲守一块无字碑的道理，助守一日"},text_after:"「它听见了。」婆婆把本子合上，「往后它记你一笔。你别不当真——东西的账比人的账久。人忘了，它身上那道擦亮的印子忘不了。」"}},{label:"「这话太重，我不敢当。」",end:!0,effect:{stat:{wuxing:1},text_after:"「记性不好的人，」婆婆笑了，「就看一眼。眼睛比脑子诚实——看过的东西，忘不掉的。」你回头看了一块无字碑一眼。就这一眼，你知道他说得对。"}}]}]},adv_g058_chuanyi:{id:"adv_g058_chuanyi",title:"路遇老人——在望仙崖把手艺往下传",mother:"M3",channel:"T2",rarity:1,entry:{node:"qd_wangxianya",chance:.13},stages:[{xinglu:"是岁望仙崖逢老人。老人的话糙，理却直——「徒弟出师那天骂你，是好事——他敢自己走了。」",text:"老人见了你，先把手上的活做完才抬头：「客人别笑话，手艺人的规矩，做不完的活不抬头。」「我收徒不收钱。」老人摆摆手，「收钱的手艺传不远——徒弟心里算账，手上就留不住分寸。我挑徒弟只看一样：肯不肯下笨功夫。」「你要是感兴趣，我讲细点。」老人说，「讲了你就懂——懂了的人，走到哪儿都替这门手艺说句话。」",options:[{label:"「说实话——这是真功夫。」",goto:1,effect:void 0},{label:"「手艺而已，不值一提。」",end:!0,effect:{stat:{wuxing:1},text_after:"「过时了？」老人不急不恼，「老规矩过不过时，不看年头，看它护不护人。你哪天吃了没规矩的亏，自然会想起今天这话。」你嘴上应着，心里不服。三年后你真吃了那亏——想起这话时，人在异乡，败得一塌糊涂。"}}]},{xinglu:"是岁望仙崖一课。老人把话说到根上——「手艺不传，人就白活一遭。」",text:"「人家都说教会徒弟饿死师父。」老人把茶碗一放，「我给你讲讲我师父是怎么『饿死』的。」「教不会的那部分，是火候。」老人说，「差半分，药性不对、木头开裂、线走歪——这半分我说了三十年，徒弟们还是得自己烧坏三锅料才能懂。所以我改了法子：先让他们烧坏——心疼了，耳朵就开了。」「你要是也有一门营生，」老人说，「记得往远处传。不一定要收徒——你把活做正了，看着的人自然学。」",options:[{label:"「我若有徒，也这么教。」",end:!0,effect:{stat:{wuxing:1},trait:{ren:1},ledger:{type:"恩",text:"在望仙崖亲手学做老人的活，得「敢露怯」之教"},text_after:"你站了一下午，看老人带徒弟。收工时他问你看出什么没有。你说：「您骂人的话，跟夸人的话一样多。」他大笑：「对喽！手艺人捧徒弟，是害他；骂徒弟，是疼他。你往后再带人，记住这个理。」"}},{label:"「道理谁都会讲。」",end:!0,effect:{stat:{wuxing:1},text_after:"「要钱？」老人愣了一下，随即大笑，「我今天一个字没收你钱，还搭了一下午的茶——你要是听成了要钱，那我这一下午白讲了，你的耳朵也白带了。走吧走吧——」他摆摆手，笑骂道，「亏你今天还看了我半天活。看活不看人，你差得远呢。」"}}]}]},adv_g059_haiyuan:{id:"adv_g059_haiyuan",title:"路遇婆婆——在沉没宫门替故人还愿",mother:"M4",channel:"T3",rarity:2,entry:{node:"lg_gongmen",chance:.12},stages:[{xinglu:"是岁沉没宫门逢婆婆。婆婆的话糙，理却直——「心愿这东西，拖一天就淡一天——淡到最后就真的没了。」",text:"你见婆婆对着一支没吹完的曲子自言自语，像在跟什么人回话。「这愿许了三年了。」婆婆摩挲着一支没吹完的曲子，「走一段，问一段。有人笑我：人都没了，还折腾什么？我说——就是人都没了，才要折腾。活着的人可以等你，走了的人，等不了。」「帮我看看这字还认得出么？」婆婆展开一页旧纸，「水渍沤了一角——这可是他的亲笔，少一个字，愿就缺一角。」",options:[{label:"「愿闻其详。」",goto:1,effect:void 0},{label:"「路远事烦，别找了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「何必？」婆婆站住了，回头看你，「你也有一天会走。你走的时候，愿没还完的滋味，你尝过才知道。我劝你一句——趁身边人都在，把该说的话说了，该办的事办了。别像我，净走夜路。」他走了，你的脚步比来时重。"}}]},{xinglu:"是岁沉没宫门一课。婆婆把话说到根上——「人走了，愿不能跟着走——愿得有人替他走完。」",text:"「我老婆子生前总念叨，」婆婆声音软下来，「这个愿，是为她还的。」「早点还不上，是因为我放不下脸面。」婆婆认了，「当年跟他置气，他托的事我故意拖着。后来他走了，我提着一支没吹完的曲子在他坟前跪了一夜——第二天启程。你还愿，一半还的是他的愿，一半还的是自己的脸。我这张老脸，路上磨掉了一半，如今才算个人。」婆婆重新收拾好行囊：「客人的话我记下了。愿还得接着赶路——它等不起，我也不能老。」他冲你拱手，「你若哪天也遇上该还的愿——别拖。拖，是还愿这行唯一的死敌。」",options:[{label:"「善缘我收下了。」",end:!0,effect:{stat:{wuxing:2},trait:{wen:1},ledger:{type:"恩",text:"捎婆婆一程，听了一个还愿人的故事"},text_after:"你把记得的线索全说了——竟真有一条有用。婆婆愣在原地，半晌，深深作了个揖：「客人，你今天替一个走了两年的人，把愿往前推了三里地。」他非要留给你一样谢礼，你说不必，他坚持：「愿上的账，不能欠。你收下——不然我这一路，就白背了心债。」"}},{label:"「我帮不上，别缠着我。」",end:!0,effect:{stat:{wuxing:1},text_after:"「完了就完了？」婆婆站定，认真看你，「人走茶凉是世道。可我把茶端热的这些年，凉不了——你信不信？你今天说这话，是因为还没遇着走的人。遇着了，你会想起我。」他走了，那句话你揣了一路，越揣越沉。"}}]}]},adv_g060_zengxing:{id:"adv_g060_zengxing",title:"龙骨回廊来了个白送路上的东西的中年汉子",mother:"M1",channel:"T1",rarity:2,entry:{node:"lg_huilang",chance:.13},stages:[{xinglu:"是岁龙骨回廊逢中年汉子。中年汉子的话糙，理却直——「东西有价，搭把手没价。」",text:"你路过龙骨回廊，看见中年汉子正把一缸摆在路边的凉茶摆放齐整——摆完冲空荡荡的路作了个揖。「这东西损耗大，我不是不心疼。」中年汉子笑了，「可我算过另一笔账：一年三百六十五天，总有那么几天，正是有人最需要它的时候。我囤的不是货——是那几天的『正好』。」「你给我评评，」中年汉子指着木牌，「这两个字哪个当头好——『自取』还是『共济』？我想了半年了。」",options:[{label:"「我来记这一笔。」",goto:1,effect:void 0},{label:"「白拿的东西，来路不正。」",end:!0,effect:{stat:{wuxing:1},text_after:"「收买人心？」中年汉子愣了一下，随即苦笑，「我要能收买人心，先把我自己这颗买服帖——它总嫌我瞎折腾。」他把东西收回，也不恼，「客人防着点也好。可你记住：天下收买人心的，都要你报答；我什么都不要——你要是连不要报答的都不敢信，这世道可就真没救了。」他这话说得平静，你却走得脸热。"}}]},{xinglu:"是岁龙骨回廊一课。中年汉子把话说到根上——「路边这点东西救不了命——可有时人就差这一口。」",text:"「我这一缸摆在路边的凉茶，起头不是给人用的。」中年汉子声音低了，「是我给自己备的。」「起头真是给自己备的。」中年汉子坦白道，「那年我落魄，怕自己哪天走投无路，就先备着——备着备着，先被人用了。用的人跟我说谢，我脸上臊——原来我备下的东西，早有人比我更需要。从那天起，这就不是我的退路了，是路上的公物。」「记住这条道的规矩。」中年汉子指指一缸摆在路边的凉茶，「用的时候想着点别人，够用的就别多拿——这不是我的规矩，是路自己的规矩。守住了，这东西就一直有。」",options:[{label:"「规矩我守住了。」",end:!0,effect:{stat:{wuxing:2},trait:{tong:1},ledger:{type:"恩",text:"帮中年汉子记了一日赠账，见一条道的人心"},text_after:"「路上的人认路上的人。」你把这话嚼了一路。后来你在他乡的渡口，看见一个陌生人冒着雨给等船的人撑伞——没人认识谁，可人人都往伞下凑。你站在雨里看着，忽然懂了：那条道上的规矩，早就走出龙骨回廊了。"}},{label:"「世道就这样，你改变不了。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不算上你。」中年汉子点头，「我的账是我的。可你走在这条道上，喝过路边的井水、走过别人修的桥、睡过别人盖的亭子——这些账都跟我一样，没人跟你要过。」他拍拍一缸摆在路边的凉茶，「不用你算我的账。哪天你想起这世道不全是黑的，就够了。」"}}]}]},adv_g061_shouye:{id:"adv_g061_shouye",title:"路遇独臂客——在鲛人遗族聚落夜里替人醒着",mother:"M2",channel:"T2",rarity:2,entry:{node:"lg_jiaoluo",chance:.1},stages:[{xinglu:"是岁鲛人遗族聚落逢独臂客。独臂客的话糙，理却直——「守夜人的觉，是睡给别人的——我少睡一觉，别人多睡一夜。」",text:"独臂客守在一盏渡口的夜航灯旁，火光把他的影子拉得很长，见你近前，先问了句：「夜里赶路，有事？」「我这一盏渡口的夜航灯守了二十年。」独臂客敲了敲它，「二十年，鲛人遗族聚落没出过一桩夜里的大事。人家说是这片太平——我知道不是。是夜夜有人走着。」「夜深了。」独臂客看看天，「你歇你的。我照旧巡我的——鸡叫之前，你听不见一点动静。这是我的保票。」",options:[{label:"「我给您留意。」",goto:1,effect:void 0},{label:"「我家的事不用你管。」",end:!0,effect:{stat:{wuxing:1},text_after:"「有病？」独臂客也不恼，「我这病生了二十年，治好了几百户人的安稳觉。你说谁有病？」他把灯一提，「前头黑，跟紧——有病的人给你照路。」你跟着他走过那段黑路，一路无话。到了亮处他站住：「去吧。有病的人不送了。」你走出老远，回头看那点灯火还立在原地——你忽然觉得，有病的人，比没病的都清醒。"}}]},{xinglu:"是岁鲛人遗族聚落一课。独臂客把话说到根上——「白天人挤人，夜里心贴心——夜里肯应你一声的，都是家里人。」",text:"「有个人在我这儿守过一夜，后来当了官。」独臂客笑了，「他还记得我，你信不信？」「那回真险，是山洪。」独臂客说，「后半夜我听见上游水声不对——平年这时候是涓涓的，那晚是闷雷似的。我挨家砸门，砸了四十七扇。水进村的时候，人都站到坡上了。第二天清点，一只鸡都没少。后来官府来查，问谁先发现的——我说没人发现，水自己来的。他们信了。我为什么不说？说了，下回还得我去砸门——我乐意砸，可功劳这东西，一人占了，别人就不干了。」「我这班，还守得动十年。」独臂客活动着腿脚，「十年后谁接？我挑着呢。你若哪天走投无路——来找我。守夜人缺人手，也缺心里有夜的人。」",options:[{label:"「这一夜，谢过了。」",end:!0,effect:{stat:{wuxing:2},trait:{wen:1},ledger:{type:"义",text:"受独臂客夜路相送一程，鲛人遗族聚落三里无事故"},text_after:"灯熄了，天亮了。你走出鲛人遗族聚落很远，回头看不见灯，可你知道它在——就像你知道这世上有一群人，一辈子活在别人的梦里，为的是别人的梦别变成噩梦。你朝着鲛人遗族聚落的方向作了个揖。天光大亮，路上人多了，谁也不知道你这一揖揖的是什么。"}},{label:"「别拦着我，我要赶路。」",end:!0,effect:{stat:{wuxing:1},text_after:"「我照不了多远，是真的。」独臂客看着手里的灯，居然认了，「可我熄了，还有下一盏——我挑的徒弟，正学着觉浅呢。灯照不了多远不要紧，要紧的是一直亮着。你要赶路就赶吧——」他让开道，「前头三里没灯。你走的时候，替我记着这三里的黑。哪天你点上什么，别忘了我这话。」"}}]}]},adv_g062_shiyi:{id:"adv_g062_shiyi",title:"补给岛的一课：老人替失物寻主人",mother:"M6",channel:"T3",rarity:1,entry:{node:"nh_bujidao",chance:.08},stages:[{xinglu:"是岁补给岛逢老人。老人的话糙，理却直——「失物认人——你替它找到主人，它比你还高兴。」",text:"老人在补给岛整理一箱无人认领的旧信，一件一件编号，比账房先生还仔细。「你看这物件，针脚多细。」老人捧着它给你看，「做它的人花的工夫，比它本身的价钱贵十倍。丢它的人找不找得着它，就差我这样的人肯不肯多问一句。」老人忽然问你：「客人一路走来，可曾在别处见过这样的物件？」他把一件失物举到你眼前。",options:[{label:"「它像是个念旧的人丢的。」",goto:1,effect:void 0},{label:"「这行当，没出息。」",end:!0,effect:{stat:{wuxing:1},text_after:"「痴人？」老人摇头，「你丢了东西就知道了——丢东西的人，个个都是痴人。我见过丢了亡妻一支簪子的铁塔似的汉子，在我这儿哭成泪人。你笑痴——那是你的福气。真到了痴那天，你盼着世上多几个痴人。」他把门为你拉开，「慢走。愿你一辈子用不上我这行。」"}}]},{xinglu:"是岁补给岛一课。老人把话说到根上——「东西无主的时候最可怜——可怜它们连个喊它名字的人都没有。」",text:"「拾遗这行，也有发懵的时候。」老人说，「讲一件，你听听值不值。」「祖师爷是邮差——这话说来话长。」老人笑了，「我师父说的：邮差一辈子送的是信，可信里装的是人的命。丢一封信，散一门亲、误一条命的事都有。所以我师父说，收失物的，跟送信的一个理——你手里过的不是物，是人家的念想。」老人拍了拍一箱无人认领的旧信，「我守着这屋子念想，二十年，一件没敢怠慢。」老人把册子递给你看：「客人，失物账一页一页都在这儿。你帮不上不要紧——记住：往后你丢了东西，先想想它在谁手里；捡了东西，先想想它归谁。这两句话做到了，我这行就算白教了你。」",options:[{label:"「两句话，我记牢了。」",end:!0,effect:{stat:{wuxing:1},trait:{dan:1},ledger:{type:"义",text:"在补给岛学了两句话：丢了先想它在谁手里，捡了先想它归谁"},text_after:"你帮着把那箱旧信按笔迹归了类——竟分出七户不同的人家。老人眼睛都亮了：「七年了，头一回有人帮我拆这个死结。这七户人家，我挨家去送——送完一户，我就少守一件。」他非要塞给你一枚旧铜钱作谢：「失物账上添你一笔——这行的规矩，帮过忙的，都是祖师爷的人。」"}},{label:"「替人守物，自己吃什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"「痴人就痴人。」老人坦然得很，「这世上总得有人痴——都精明着，丢的东西就真没了。你精明你的，我痴我的。哪天你精明不动了、累了，我这一屋子痴，兴许还能给你焐焐手。」"}}]}]},adv_g063_wenlu:{id:"adv_g063_wenlu",title:"海市的一课：驼背阿婆只问不答",mother:"M7",channel:"T1",rarity:1,entry:{node:"nh_haishi",chance:.1},stages:[{xinglu:"是岁海市逢驼背阿婆。驼背阿婆的话糙，理却直——「问句是钩子——鱼上不上钩不要紧，水被搅活了就行。」",text:"你路过海市，驼背阿婆拦住你：「客人，问你个事——你答不上来不要紧。」「我这一辈子没什么成就。」驼背阿婆摩挲着一张折了又折的路引，「就攒了一堆问题。可你别说——城东那个木匠，是回答我一个问题想通了榫卯；西街那个郎中，是回答我另一个问题改了方子。问题会跑——比答案跑得远。」「客人走南闯北，见得多。」驼背阿婆凑近了些，「帮我评评，这个问题，问得蠢不蠢？」",options:[{label:"「这问题，我试试。」",goto:1,effect:void 0},{label:"「问那么多做什么，干活要紧。」",end:!0,effect:{stat:{wuxing:1},text_after:"「我答？」驼背阿婆摊开手，「我要是答得上，还开店做什么？」他指指一张折了又折的路引，「你看这满墙的问题——我答上的不到十个。剩下的，都是别人答的、路教的、年头给的。我这不是卖关子——我是个替人传话的，传天地的、传岁月的、传你自己心里的。你急着要我答，就像问镜子要路——路在你脚下，不在镜子里。」"}}]},{xinglu:"是岁海市一课。驼背阿婆把话说到根上——「问路的人最聪明——他省下的冤枉路，就是他的学问。」",text:"「我最得意的一个问题，」驼背阿婆压低了声音，「救过一个人。」「三十年挂着的那个问题是：人这一生，是答案重要，还是问得对重要？」驼背阿婆缓缓道，「年轻时我赌答案是重要的——答对了就赢了。后来发现，答对的都有过期的一天。如今我改赌了：问得对重要。问对了，答错了能重来；问错了，答对了也是白答。」驼背阿婆笑了笑，「你呢？你怎么赌？不用现在答——这个问题，现在也归你了。」「我送你出门。」驼背阿婆边走边说，「记住——路上遇事，先别急着找答案。先问自己一句：这事我是在看，还是在觉得？这一句，顶你半生的学费。」",options:[{label:"「看，还是觉得——我记下了。」",end:!0,effect:{stat:{wuxing:1},trait:{ren:1},ledger:{type:"义",text:"听驼背阿婆讲哑巴师父的沙地问句，学会「看还是觉得」"},text_after:"「看，还是觉得——这一句你带走了。」驼背阿婆满意地送你出门。后来你在生意上、恩怨里、抉择前，无数次问自己这一句。它不能替你做对的事——可它让你少做了许多自以为对的事。你从此逢人便传这句话，传的时候都说是从一个怪老头那儿听来的。"}},{label:"「故弄玄虚，告辞。」",end:!0,effect:{stat:{wuxing:1},text_after:"「答案？」驼背阿婆把牌子转过来给你看——「只问不答」四个字钉得结结实实。「我这不给答案，跟药铺不卖病一个理：病在你身上，药方在你身上，我这儿只管帮你把脉。」他把门推开，「你要答案，满街都是——街边随便拉个人都能给你一个。可你要问句，就得自己来。你不来，是你的损失。」"}}]}]},adv_g064_jizhang:{id:"adv_g064_jizhang",title:"妖市的一课：老人替人情记着账",mother:"M8",channel:"T2",rarity:1,entry:{node:"dh_yaoshi",chance:.06},stages:[{xinglu:"是岁妖市逢老人。老人的话糙，理却直——「账要当众记、背后清——记账人自己先不能藏私。」",text:"老人的一本记了几代人的情分簿在妖市人人都信——你说不清它记了多少年，只知道比庙里的功德碑还灵。「我这柜里也有死账。」老人翻开一册，「欠账的人没了，绝了户。这账我不销——我把它抄出来，年年清明在庙前念一遍。不为讨——为的是告诉街坊：这个人来过，欠过，也被人欠过。没了户，不能连名都没了。」「帮我断个案子。」老人把两个争执的人拉到一处，「他们都信你外乡人嘴严。」",options:[{label:"「报个名姓，帮我翻翻。」",goto:1,effect:void 0},{label:"「旧账就让它过去。」",end:!0,effect:{stat:{wuxing:1},text_after:"「记它做什么？」老人把笔搁下，「你不记，它就不存在了么？不——它在你心里烂着，在他心里烂着，两败俱伤。记出来，才有得还、有得清、有得忘。账不是记仇——是把烂在心里的东西，拿到日头底下晾晾。」"}}]},{xinglu:"是岁妖市一课。老人把话说到根上——「死账不销——销了，欠的人和被欠的人，心里都空一块。」",text:"「我这行也有对头。」老人冷笑一声，「有人最恨我这本账——你猜是谁？」「最恨我的是人贩子。」老人冷冷道，「他们拐走的孩子，我账上都有底——哪家孩子哪年生、什么胎记、谁抱走的。他们烧过我的铺子，砍过我的门。可账在人心里的那份，他们烧不掉——街上人人替我记着。」老人把柜子锁好，「我这账本为什么比官府的册子灵？因为官府的册子锁在库里，我的账——长在几千户人的嘴里。」「替我记一笔。」老人忽然说，「就说：今天有个过路的客人，坐下来听完了整本账。这一笔记下——你也是账里的人了。」",options:[{label:"「把我记上。」",end:!0,effect:{stat:{wuxing:2},trait:{xin:1},ledger:{type:"恩",text:"在老人账上被记了一笔：「今天有个客人，听完了整本账」"},text_after:"你把那句话带走了。后来你受了人的恩，总会想起那笔「不欠谁的」的账——想起时脸就发热，热完了就认真去还。再后来你也学着记：谁帮过你、你欠过谁，一笔一笔记在心里。你还真把这些教给了你的孩子——账本没传下去，账理传下去了。"}},{label:"「人情最靠不住，你记了也白记。」",end:!0,effect:{stat:{wuxing:1},text_after:"「销不得。」老人摇头，「死账销了，你就当这人没来过。可他来过——他欠账的时候是个活人，有爹娘、有脾气、有舍不得。销账容易，抹一个人难。」他把死账那册抱在怀里，「我清明念他们名字的时候，庙里老和尚说我痴。我说你不痴不懂——被念到的名字，才算在人间留过脚印。」"}}]}]},adv_g065_shouwu:{id:"adv_g065_shouwu",title:"路遇清瘦老者——在万妖山守着一件旧物",mother:"M5",channel:"T3",rarity:1,entry:{node:"dh_wanyao",chance:.11},stages:[{xinglu:"是岁万妖山逢清瘦老者。清瘦老者的话糙，理却直——「它站了几百年，我陪它站几年，不算多。」",text:"你到万妖山时，清瘦老者正围着一盏长明灯忙活，动作轻得怕惊着它。「这东西看着孤，其实不孤。」清瘦老者指给你看，「它身上有几十年的手印。守它的人一代传一代，手印摞手印——它比谁的家底都厚。」「帮我看看它哪儿不对。」清瘦老者退开半步，「外人一眼看出来的毛病，守的人反而看不见。」",options:[{label:"坐下陪清瘦老者说说话",goto:1,effect:void 0},{label:"扫一眼就走",end:!0,effect:{stat:{wuxing:1},text_after:"清瘦老者也没恼，只是摆摆手：「不守也对。守物这行，本来就挑人——不挑出个肯停脚的，守也守不住。」你走出去老远，回头一看，他还在擦。你忽然觉得，这世上的道理，一半在书里，一半在这样的人手里。"}}]},{xinglu:"是岁万妖山一课。清瘦老者把话说到根上——「东西旧了不怕，怕的是没人认它。」",text:"「最难的不是守，是没人懂。」清瘦老者笑笑，「懂的人不来，来的人不懂——守着守着就只剩你一个人了。」清瘦老者展开那件旧物，上面是一行字：「物在人守，人在物传。」——上一任守物人给他的话，如今他念给你听。「往后你路过，来看它一眼。」清瘦老者说，「不用你守——看一眼，它就多活一天。这买卖便宜吧？」",options:[{label:"「这条规矩，我带走。」",end:!0,effect:{stat:{wuxing:2},trait:{dan:1},ledger:{type:"恩",text:"帮清瘦老者修缮一盏长明灯，万妖山的旧物得以长存"},text_after:"你帮着擦完了。手上的灰蹭了一袖子，心里却出奇地熨帖。清瘦老者看着擦亮的一盏长明灯，半天说了句：「行了，今天这一遍，值。」你走出很远才咂摸出味儿来——他谢的不是你，是它今天又被人认真对待了一回。"}},{label:"「我记性不好。」",end:!0,effect:{stat:{wuxing:1},text_after:"清瘦老者也不勉强：「记不记随你。这话搁在这儿，你哪天想起来了，就算我托到了。」你告辞出来，走出一段，那句话还是跟上了你——物在人守。你说不上来哪里被它戳中了。"}}]}]},adv_g066_chuanyi:{id:"adv_g066_chuanyi",title:"在化形妖城，把手艺往下传的独臂客",mother:"M3",channel:"T1",rarity:2,entry:{node:"dh_huaxing",chance:.12},stages:[{xinglu:"是岁化形妖城逢独臂客。独臂客的话糙，理却直——「传艺先传心，心不正，手艺就是凶器。」",text:"化形妖城的作坊里传出说话声：独臂客在讲一面祖传的皮影的用法，讲一句，停半晌，让徒弟自己悟。「外行看手艺，看的是巧。」独臂客说，「内行看的是匀——匀了才稳，稳了才久。做人一个理。」「你想不想知道这一面祖传的皮影为什么是这个形？」独臂客卖了个关子，「知道了你就明白一半了。」",options:[{label:"「这手艺，能传多久？」",goto:1,effect:void 0},{label:"「学这个能挣几个钱？」",end:!0,effect:{stat:{wuxing:1},text_after:"「过时了？」独臂客不急不恼，「老规矩过不过时，不看年头，看它护不护人。你哪天吃了没规矩的亏，自然会想起今天这话。」你嘴上应着，心里不服。三年后你真吃了那亏——想起这话时，人在异乡，败得一塌糊涂。"}}]},{xinglu:"是岁化形妖城一课。独臂客把话说到根上——「我这一双手是从师父手上接来的，得接着往下递。」",text:"「我这辈子收过九个徒弟。」独臂客伸出手比划，「成器的三个，将就的三个，走了样的三个——你猜哪个我记最牢？」「那个走了样的徒弟，拿这门手艺坑人。」独臂客声音沉下来，「我上门去，当着人面把一面祖传的皮影从他手里要走回来——手艺是从这上头学的，现在从这上头收回来。他哭，我也难受。可规矩就是规矩：艺不正，师收之。」独臂客最后擦了一遍手，朝你拱手：「客人慢走。手艺人的话糙，理不糙——你今儿听的这些，够你在别的行当里用一辈子。」",options:[{label:"「我若有徒，也这么教。」",end:!0,effect:{stat:{wuxing:1},trait:{tong:1},ledger:{type:"义",text:"受独臂客所赠一句行话，行走江湖多了一面镜子"},text_after:"你站了一下午，看独臂客带徒弟。收工时他问你看出什么没有。你说：「您骂人的话，跟夸人的话一样多。」他大笑：「对喽！手艺人捧徒弟，是害他；骂徒弟，是疼他。你往后再带人，记住这个理。」"}},{label:"「手艺早晚要绝。」",end:!0,effect:{stat:{wuxing:1},text_after:"「道理是会讲。」独臂客不恼，「可我讲了三十年，徒弟们信了——你嘴上不信，眼睛信了。你进来到现在，眼睛没离开过它三回。」你哑口无言。他笑着送你出门：「不信没关系，手艺等得起。它等你一辈子，我都等得起。」"}}]}]},adv_g067_haiyuan:{id:"adv_g067_haiyuan",title:"路遇婆婆——在佛国香市替故人还愿",mother:"M4",channel:"T2",rarity:1,entry:{node:"xm_xiangshi",chance:.13},stages:[{xinglu:"是岁佛国香市逢婆婆。婆婆的话糙，理却直——「替人还愿这行，赚的不是钱——是夜里睡得着。」",text:"佛国香市里，婆婆捧着一封没寄出去的信出神——你一问，他说这是故人留下的。「这是我欠他的。」婆婆说，「当年他有难处，我没能帮上。如今他走了，我把他的愿当我的债——债这东西，躲一辈子，不如还一趟。」婆婆看着你：「你说，人走了以后，到底知不知道我们还在替他办事？」不等答，他自己接了：「知不知道都要办——这是我的事，不是他的事。」",options:[{label:"「您这愿，尽到心了。」",goto:1,effect:void 0},{label:"「与我无关，让让。」",end:!0,effect:{stat:{wuxing:1},text_after:"「与我无关？」婆婆也不恼，「是啊，天下事都与谁无关呢？他跟我无关的时候，我欠了他一辈子。你走吧——愿你一辈子都用不上替人还愿。用不上，是福气。」"}}]},{xinglu:"是岁佛国香市一课。婆婆把话说到根上——「故人最大的悲哀不是死——是心愿烂在没人知道的地方。」",text:"婆婆沉默了一阵，说：「其实这个愿，我本可以早点还的。」「那回邪门事，我不止遇到过一回——回回都在我想撒手的时候。」婆婆说，「有一年我病倒在客栈，想着这愿怕是还不成了。第二天清早，隔壁房一个货郎来借火，一搭话——他正是我要找的那家的远亲。你说这是菩萨安排？我不信菩萨。可我信：你认真办一件事，全天下都会给你让路。」「你要是记得今天这故事，」婆婆说，「往后见着满头白发的还愿人，别笑他痴。给他一碗水——他替这世上所有走了的人，捎着话呢。」",options:[{label:"「这碗水，我记着。」",end:!0,effect:{stat:{wuxing:1},trait:{dan:1},ledger:{type:"恩",text:"受婆婆所托记下善缘，替走了的人结一个活缘"},text_after:"「尽到心没尽到心，我自己知道。」婆婆摇头，「可你说这话，我路上就不孤单了。还愿人最怕的不是路——是没人说一句『够了，可以了』。你说了一句。我记下了。」"}},{label:"「我帮不上，别缠着我。」",end:!0,effect:{stat:{wuxing:1},text_after:"「帮不上不打紧。」婆婆摆摆手，「别缠着我——这话就伤人了。我讨的不是你的帮，是你让一步路。让一步路，天塌不下来。」他让到道旁，先请你走。你从他身边过的时候，忽然觉得这一步，让得自己心里发虚。"}}]}]},adv_g068_zengxing:{id:"adv_g068_zengxing",title:"在佛骨塔，白送路上的东西的中年汉子",mother:"M1",channel:"T3",rarity:2,entry:{node:"xm_foguta",chance:.06},stages:[{xinglu:"是岁佛骨塔逢中年汉子。中年汉子的话糙，理却直——「我一辈子的买卖：本钱是自己出的，利息是天下人的。」",text:"中年汉子守着一串挂在树上的旧草鞋打盹，木牌上的字被风雨磨得快看不清了，他还是每天来摆。「你仔细看我的木牌。」中年汉子指给你，「写的是『自取』，不是『施与』。一字之差——拿的人心里就平了。善这个东西，得把人的脸面一起护住才算善。」「你给我评评，」中年汉子指着木牌，「这两个字哪个当头好——『自取』还是『共济』？我想了半年了。」",options:[{label:"「我来记这一笔。」",goto:1,effect:void 0},{label:"「白拿的东西，来路不正。」",end:!0,effect:{stat:{wuxing:1},text_after:"「收买人心？」中年汉子愣了一下，随即苦笑，「我要能收买人心，先把我自己这颗买服帖——它总嫌我瞎折腾。」他把东西收回，也不恼，「客人防着点也好。可你记住：天下收买人心的，都要你报答；我什么都不要——你要是连不要报答的都不敢信，这世道可就真没救了。」他这话说得平静，你却走得脸热。"}}]},{xinglu:"是岁佛骨塔一课。中年汉子把话说到根上——「我送的不是东西，是「有人管你」这句话。」",text:"「有一年冬天，来了个贼。」中年汉子说起这事，倒像说旁人。「碑不立。」中年汉子说得干脆，「一立碑，这就成了我的善举。可这一串挂在树上的旧草鞋一年喂饱几百人——是几百个取的人成全了这件事，不是成全我。碑上该刻他们——可他们连名字都不肯留。所以他们不留，我也不留。这事干干净净，比碑好看。」中年汉子朝你挥挥手：「走吧走吧。东西拿了，话也听了——往后你也是个路上的人了。路上的人认路上的人，一眼就认得。」",options:[{label:"「这摊子会一直在的。」",end:!0,effect:{stat:{wuxing:1},trait:{zhi:1},ledger:{type:"恩",text:"在佛骨塔白得一份干粮，后来也学着挂了一壶茶"},text_after:"「我可没说一定是我。」你摆手。中年汉子笑道：「兴许不是。可你今天多站了这半晌——比别人近了一步。这摊子挑人，跟守物挑人一样：挑肯停脚的。」你走出几里地回头望，他还坐在一串挂在树上的旧草鞋边——像路长出来的一部分。"}},{label:"「别拿这些哄我。」",end:!0,effect:{stat:{wuxing:1},text_after:"「哄你？」中年汉子笑了，「我哄你做什么？我又不要你的钱、不要你的命。我哄你，你就信了天下还有点好事——这买卖我亏了还是赚了？」他把东西又塞回你怀里，「拿着。信不信由你——东西是真的，渴了是真的，就这么简单。」"}}]}]},adv_g069_shouye:{id:"adv_g069_shouye",title:"泉眼驿寺的一课：盲眼老者夜里替人醒着",mother:"M2",channel:"T1",rarity:1,entry:{node:"xm_yisi",chance:.07},stages:[{xinglu:"是岁泉眼驿寺逢盲眼老者。盲眼老者的话糙，理却直——「守夜不图别的——图鸡叫的时候，家家还都是囫囵的。」",text:"盲眼老者守在一更天的梆子旁，火光把他的影子拉得很长，见你近前，先问了句：「夜里赶路，有事？」「白天他们叫我老夜猫子。」盲眼老者嘿嘿地笑，「等你夜里病了、丢了东西、被人堵了——你第一个想起的就是老夜猫子。到那时我就不是夜猫子了，是恩人。人呐，白天夜里两张脸，我两样都见惯了。」「夜深了。」盲眼老者看看天，「你歇你的。我照旧巡我的——鸡叫之前，你听不见一点动静。这是我的保票。」",options:[{label:"「我给您留意。」",goto:1,effect:void 0},{label:"「我家的事不用你管。」",end:!0,effect:{stat:{wuxing:1},text_after:"「出息？」盲眼老者笑了，「我这行没出息——没出息到二十年没人抢。可你想想，谁夜里敢不睡？不是我不想睡，是泉眼驿寺几百户人拿觉换了我的不睡。」他敲了敲一更天的梆子，「出息这东西，白天论的。夜里的账，另算。」你将信将疑地走了。后来你在异乡的夜里病倒，是个守夜的老人照看了你——那一刻你想起这句话，眼睛忽然就热了。"}}]},{xinglu:"是岁泉眼驿寺一课。盲眼老者把话说到根上——「夜里的规矩比白天大——因为夜里没人看着，全凭自觉。」",text:"「白天的官府管不了的，夜里都得有人管。」盲眼老者说，「你猜夜里都有什么事？」「师父那句话是：守夜守的不是夜，是人心里那点亮。」盲眼老者摩挲着一更天的梆子，「我用了二十年才懂——灯灭了可以再点，人心里的灯灭了，夜里就真黑了。所以我巡夜从不偷懒：我的脚步声，就是几百户人心里那盏灯的灯芯响。」「我这班，还守得动十年。」盲眼老者活动着腿脚，「十年后谁接？我挑着呢。你若哪天走投无路——来找我。守夜人缺人手，也缺心里有夜的人。」",options:[{label:"「保我十年太平。」",end:!0,effect:{stat:{wuxing:2},trait:{tong:1},ledger:{type:"恩",text:"听盲眼老者讲砸门四十七扇的旧事，识得守夜人的分寸"},text_after:"天亮了。你按盲眼老者教的走了那条新路——果然避开了塌方段。回头望，盲眼老者已经收了灯，正往回走。他的背影在晨光里瘦得像根梆子，可你觉得，这一夜泉眼驿寺的太平，全是这根梆子敲出来的。"}},{label:"「你这灯，照不了多远。」",end:!0,effect:{stat:{wuxing:1},text_after:"「运气？」盲眼老者指指自己的眼睛，「我这双眼二十年没睡过一个整觉——泉眼驿寺每一块松动的石头、每一个白天咽下事的夜行人、每一处该修没人修的堤口，都在我这儿记着。运气是留给没准备的。你说是运气就运气——反正鸡叫的时候，人人都囫囵着，这就够了。」"}}]}]},adv_g070_shiyi:{id:"adv_g070_shiyi",title:"十八峒总寨里替失物寻主人的老妇",mother:"M6",channel:"T2",rarity:1,entry:{node:"nj_bazhai",chance:.11},stages:[{xinglu:"是岁十八峒总寨逢老妇。老妇的话糙，理却直——「遗落的东西不会说话——可它们都在等人。」",text:"老妇在十八峒总寨整理一盒散落的名帖，一件一件编号，比账房先生还仔细。「你看这物件，针脚多细。」老妇捧着它给你看，「做它的人花的工夫，比它本身的价钱贵十倍。丢它的人找不找得着它，就差我这样的人肯不肯多问一句。」「你眼神好。」老妇招手，「帮我认认——这个包袱上的字，是哪府的写法？」",options:[{label:"「这故事有意思，讲讲。」",goto:1,effect:void 0},{label:"「一堆破烂，守着做什么。」",end:!0,effect:{stat:{wuxing:1},text_after:"「不会找？」老妇叹口气，「客人，会找的人，丢的都是值钱东西。不会找的——老人丢了，孩子丢了，痴了的人丢了。他们自己找不了，家里人找疯了。我这行拾的，一半是物，一半是人。」他说完不再看你。你走出去几步，觉得方才那句话，轻佻得不像自己的。"}}]},{xinglu:"是岁十八峒总寨一课。老妇把话说到根上——「世上的失物比失物的人多——总得有人替它们排队等主人。」",text:"「我师父是官府的库吏出身。」老妇说，「他传我这行当，传的却不是收东西的法子。」「发懵的事是这样的：有个妇人丢了亡夫的一枚章，在我这儿登了记，急得三天没吃。」老妇说，「两年后东西寻着了，送上门——她看着章，忽然平静得很，说了声『原来在这』，就收下了，连谢都没谢。」老妇苦笑，「我懵了半个月。后来懂了：她这两年，是把人一点一点放下了。章送到了，她哀也尽了。我这一行，有时候送到的是东西，有时候送到的——是结局。」「天不早了。」老妇点起灯，「我这儿夜里也开门——丢东西的人，是不分时辰的。你慢走，路上小心别落了东西。落了也不要紧——这世上还有我这样的人。」",options:[{label:"「这行当，敬您一声。」",end:!0,effect:{stat:{wuxing:1},trait:{dan:1},ledger:{type:"恩",text:"在十八峒总寨帮老妇归类失物，替七户人家拆了死结"},text_after:"你帮着把那箱旧信按笔迹归了类——竟分出七户不同的人家。老妇眼睛都亮了：「七年了，头一回有人帮我拆这个死结。这七户人家，我挨家去送——送完一户，我就少守一件。」他非要塞给你一枚旧铜钱作谢：「失物账上添你一笔——这行的规矩，帮过忙的，都是祖师爷的人。」"}},{label:"「失物多了，你拾得过来？」",end:!0,effect:{stat:{wuxing:1},text_after:"「吃什么？」老妇指指墙角的一张木床、一只小灶，「我就住这儿。失物招领不收钱——我另有营生，替各家修修补补，饿不死。」他嘿嘿一笑，「你问的不是这个吧？你是问我图什么。图什么——图我娘。我娘丢了她的陪嫁镯子，急疯了。有人替她寻回来了。那年我十岁，站在门口看那个人把镯子递给我娘——我娘笑了。我这辈子，就想当那个人。」"}}]}]}};Object.assign(t,e);export{e as ADVENTURES15};
